/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150924-5","meetingId":"h27-cm09","date":"2015年9月24日","dateIso":"2015-09-24","committee":"総務委員会","time":"午前１０時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","topics":[{"id":"topic-01","title":"では、(1)の第６８号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず、(6)第８１号議案 しながわ中央公園拡張整備工事請負契約","agenda":"では、(1)の第６８号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず、(6)第８１号議案 しながわ中央公園拡張整備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ですが、実際非常用に使うということならば、いろいろな重機等も入ったりする可能性がもちろんあると思うのですが、そのときに、ほかの部分では置ける、置けないということになって、あくまでここのアスファルト舗装にしているところだけが頑丈だというのは、それでいいのかなという疑問を感じたのですが、それだけお聞かせください。","respondent":"多並公園課長","answer":"特にこのアスファルトでつくったところの考え方としては、いわゆる降りるだろうというところを表示しなければいけないというところがあって、目安になるのでこういうふうにやらせていただいたところと、あとは災害時、いわゆるストレッチャーなり何なり急病人を運んだり。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"意見だけ。そういうときに、重機、それからトラック等いろいろ運ぶようなときもあるのかなとちょっと思ったもので、質問をさせていただきました。中身はわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"この１９ページの平面図を見ますと、図面ですから北側のマークがあるのですけれども、実際にこの現場は、しながわ中央公園がこの防災の拠点・起点になると思うのですけれども、こういう場合、実際、現場にこちらが北側とか、そういう印は必要ないものなのか、それをちょっとお聞きしたい。","respondent":"多並公園課長","answer":"もう一つの予算のお話のときの、いわゆる体育館の裏側のところのお話がございましたけれども、そこでいろいろ設計をやりながら組み立ててきたところだったのですけれども、最終的に、裏側もあるのですけれども。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"ここにかなりの方々がまずは逃げてこられるということが想定されると、トイレをもう少し多くつくることはできないのかなと感じるのですが、なぜこの数字で、もう少し増やせないものなのでしょうか。","respondent":"多並公園課長","answer":"簡易トイレといいますか、マンホールトイレにつきましてもいろいろ計算させていただいたところ、ここのＪＴ跡地だけでなくしながわ中央公園も含めて、もし仮設住宅ができた際を想定して計算をしたところ、現在のところその４穴でいいのではないかということで。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"この点については、スペースの問題ということで了解いたしました。それと、あと一点教えていただきたいのですが、この北側というのは、ちょっと地図でよくわからないのですけれども、この北側の接道はどのようになっているのでしょうか。北のほうからもこの公園に入ることはできるようなつくりになっているのでしょうか。","respondent":"多並公園課長","answer":"出入口につきましては、工事ではこの北の一番端っこのところに階段を設ける予定になってあります。そこは６ｍの区道に接続する形で今回つくるものです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"ここに仮設住宅ということを先ほどの話で言われたけれども、災害時、あるいは何か非常時の場合、公園の用途の違いがあったがために不都合が生じることがないのかどうか、そこのところを教えてください。","respondent":"多並公園課長","answer":"ただ、防災上の位置づけからしましたら、災害時はもちろん連携する形と考えておりまして、先ほどヘリコプターの話をさせていただきましたけれども、やはりヘリコプターが降りるときには、人が立ち入るのは非常に危険なところもあります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"運用については、有用性をよくするためのお話だったらわかるのです。厳密的にやはり工事をやるときは、何か用途の許可を出すのではないですか。例えばここはこういう公園で、こちらは防災公園だとか、何か許可上の違いというのがもしあるのであれば、何かあったときにその許可の範疇が違うがために使えなかったり、使えたり、そういう事態が起きないのでしょうかということなのです。","respondent":"多並公園課長","answer":"そういった部分ですと、それ以外の位置づけ、防災公園の届け出はありませんので、そういう意味では、公園上のいわゆる規模としての位置づけは都市計画上の問題だけであって、利用上は大きな障害になるような位置づけ、許可等はないと考えています。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"これはもうごっちゃになってしまうという解釈でいいのですか。下のところは公園遊具があるので、今の現しながわ中央公園と一体でというのはわかるのですが、ここのところだけどうもいろいろな名称とか、役所の範囲とか許可とか使用用途とか、そういうのを考えるとちょっと浮いてしまうのですけれども、そこのところはちゃんと整理できているからやっているのでしょうけれども、ちょっと説明をお願いします。","respondent":"多並公園課長","answer":"ただ、災害が起こったときには、今回ＪＴ跡地が特化した形で整備するほうにしていますけれども、公園としては、先ほども申しましたようにしながわ中央公園として全体的に整備しておりますので、その中の広場ゾーンを。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"これは全部すべて近隣公園ということで考えて、こういうことでたまたま防災機能があるゾーンがここにありますよということで考えるということと、そのゾーンがあることによって、本来公園としての機能の、例えばこっちはいいけれどもこっちはだめだよということは生じてこないということで理解をしていいのでしょうか。","respondent":"多並公園課長","answer":"今の委員のご指摘のとおり、おっしゃるとおりです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"今回は防災機能を持つ公園という整理ですけれども、その内容について、今も幾つか議論があったのですけれども、例えば災害用の電気、電源というのは、この計画ではどういうふうに確保されているのか、いないのかを伺いたいです。ある意味そこから逆算したこういう図面とか配置になっているのか、災害時の運営プランがどうなっているのか等も伺いたいと思います。","respondent":"多並公園課長","answer":"１点目の電源の件ですけれども、非常用の電源がとれる場所ということで、２カ所設ける予定にしています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりいろいろとトイレの不安をよく聞くので、災害用トイレはマンホール直結型というのは先ほど伺ったのですけれども、ここに書いてあるだれでもトイレだったり通常のトイレだったり、これは例えば水が断水したときでも、バケツに水が汲んであってそこに置いてあれば、要するに流すものがあれば使えるという形なのか、それとも断水時には全く使えないものなのか、ちょっと細かくて申し訳ないですけれども。","respondent":"多並公園課長","answer":"ということなので、ヘリコプターのためという意味ではなくて、その脇の中小企業センター側のほうにずっとライトをつけていく形になるのですけれども、そちらのほうに今回２カ所を配置していくような形で考えているので、緊急時に何かというのもありますけれども。","id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"なかなか全部の電源を確保するのは無理だと思いますけれども、いわゆる最低限必要だと考えられるものを自家発電装置や燃料や太陽光パネルや、そういう意味での２カ所の電源ということだったのか、そこだけちょっと確認させてください。","respondent":"多並公園課長","answer":"もう一つが、災害時でも万が一電気が通じなかったときの場合にということで、非常用電源も倉庫の中に配備して、あらゆる形で電源をとるような形の備えはしています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうすると、ヘリコプターが夜間でも降りられるためにライトが用意してあります。発電機がもしほかにあるとしたら、それを持ってきて接続すれば、そのヘリコプター着陸のライトはつきますよとか、いや、そういうものはなくても、街中は停電してもそのライトはつきますよとか、そのような形になっているかどうか、お伺いします。","respondent":"多並公園課長","answer":"先ほどちょっと現地でもご説明したのですけれども、ライトは通常の電気のものと、スポットライト式のと２つありまして、スポットライト式というのは本当に限った形でつけてあります。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"先ほどちょっと現地でもお話しさせていただいたのですけれども、トイレの話ばかりですみません。だれでもトイレがつくのは本当に結構なことだと思うのですけれども、災害時と平時と両方考えて、やはり大人用の簡易なおむつ交換のためのものがぜひつけられたらいいなと思うのですけれども、契約の金額が決まっている中で、そういうこともこれから検討が可能なのかどうか、ちょっと教えてください。","respondent":"多並公園課長","answer":"ただ、今の内容につきましては、ここの部分では、今この契約内容ですけれども、今後の課題とさせていただいて、いろいろな部分の公園の改修、またしながわ中央公園の今あるクラブハウスについても老朽化も大分進んできておりますので、そういういろいろなタイミングを見ながら。","id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"意見です。ぜひつける方向で、契約金額がちょっとどうしても高くなるということはあると思うのですけれども、検討できるのであれば、平常時のことを考えても今とても少ないので、考えていただけるといいなと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり災害時のこの公園の運営について、事前に計画を立てて区民に知らせて、しっかり利用できるようにするしくみが大切だと思いますので、その点については改めて要望して、公園整備については賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"に戻りまして、第６８号議案 品川区行政委員会の委員の報酬および費用弁償に関する条例および品川区監査委員の給与等に関する条例の一部を改正する条例","agenda":"に戻りまして、第６８号議案 品川区行政委員会の委員の報酬および費用弁償に関する条例および品川区監査委員の給与等に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"このたびこのように費用弁償に関する条例改正ということで出てまいりました。ただ、やはり非常勤特別職の職員、議員も含めてですが、報酬をもらっている以上、私は実費相当額に対しても本来ならもらうべきではないと思います。現に実費相当額もいただかないという議員もいるわけですから、その辺も考えて、今後の課題、やはり検討はするべきだと思います。このたびの条例案については賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"実費相当額というのが具体的にどのように運用されるのか伺いたいのですけれども、条文で言うと「最も経済的かつ合理的な経路および方法により出会し」ということですけれども、区議会のほうはバスと電車のみで、事前に届け出を出すということで、今、進んでいると思うのですけれども、ここで言っているいわゆる実費相当額というのはどういう計算方式になるのか、そこを伺いたいと思います。","respondent":"江部総務課長","answer":"３委員会のことですので、それぞれその委員会の中で決定していっていただくことになろうかと思いますけれども、基本的には区議会議員の条例の運用を尊重しながら、いわゆる交通費という考え方をベースに進められていくと。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれの委員会で決めるというのと、この条例の改正がどういう仕切りになっているのか、単純にわからなかったのでそこのしくみを教えていただきたいのと、考え方としては、議会の運用に準ずると思っているということなのでしょうか。もう一回そこをご説明いただきたいのが１点です。","respondent":"江部総務課長","answer":"２点目の出張ということについてですが、今回の出会手当につきましては、基本的に出張ではない各委員会の、教育委員会、選挙管理委員会、監査委員会、監査委員会は協議会ですが、定例会、臨時会に出席、これが出会手当ということで。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"先ほど現地でも少し伺ったのですけれども、地域交流スペースということになっているのですが、防災拠点型ということについて、そこの設備を大きくすればまた契約の中身が変わってきてしまうと思うのですけれども、具体的に契約上はどの辺までの設備がその契約に入っているのか伺いたいと思います。","respondent":"立川経理課長","answer":"実際どういった設備かと申しますと、用途としまして、いわゆる要援護者の緊急受け入れ先という位置づけですので、例えば地域交流スペース内に、車いすに対応した専用のものを設けるだとか。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"車いすが対応できる仕様というのは、具体的に言うといわゆるバリアフリーというか、車いすでできるということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの午前中からの流れでトイレのことが気になってしまうのですけれども、防災拠点にするという以上は、その辺のトイレについてもだれでもトイレはもちろんのこと、何かそういう被養護の、介護とかを必要とされる方が使い勝手の良いことになっていると理解していいのでしょうか。","respondent":"小林施設整備課長","answer":"はい、そのとおりです。バリアフリーのだれでもトイレも地下に持っておりますので、そのとおりです。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"今日現地を視察しまして、外構工事で、全部ではないのですが、コンクリートパネルで埋めて壁をつくっていたところが見えたのですが、一般論から言うとコンクリート打設の工事で持っていくと思うのですけれども、あれはどういう理由からなっていたのでしょうか。","respondent":"小林施設整備課長","answer":"これはすべてに該当するかというと、敷地の条件によって選定ができるものとできないものがあります。あそこについては、ちょっと前面道路の目黒通りからストレートに入ってこられるというメリットがあって、そういう工法を採用しております。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、近隣の方からすれば、そこに新たに大きいビルが建つようなものですから、今後も何か対応できるところがありましたら対応していただいて、近隣とも仲良くやっていっていただきたいと思います。この施設はやはり品川区としては特に重要で、国民、特に区民にとっても大切な施設だと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ一日も早く次の計画が具体化するよう、これは強く要望しておきたいと思います。質問は、工期が平成２９年３月３１日ということですけれども、この工期というのは大体これぐらいのものなのか、ここの立地条件を含めてちょっと通常と違うところがあるのか、そこをご説明いただきたいのと、開所式といいますか開設時期といいますか、そこの今の見通しを伺いたいと思います。","respondent":"小林施設整備課長、立川経理課長","answer":"適正な工法をもとに適正な工期を算出して、今回、平成２９年３月いっぱいということになっております。それと、開所につきましては、平成２９年７月を予定していると聞いております。土地の取得から開設まで、概ね予定どおりです。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"３ページの（仮称）上大崎三丁目高齢者福祉施設等新築工事のところでの辞退、設備等々に関しては入札が行われているけれども、ここのところの全体的なもので、これが辞退になった原因というのがもしありますれば、ちょっと教えていただきたいと思います。","respondent":"立川経理課長","answer":"辞退理由につきましては各社それぞれありますけれども、いわゆる配置技術者の手配がつかない、また積算が合わない、そういった各企業の事情です。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"契約の不調が続いている話を聞いている中で、このところは各企業の台所、いわゆる作業上の理由かと思いますけれども、そこらに関して、ここのところでは人件費の高騰、材料費の高騰、いろいろな要因があるので、これに関してはそれは当てはまっていないような考え方でいいのでしょうか。","respondent":"小林施設整備課長","answer":"今回、この積算についても十分検討しておりまして、直近の単価表をもとに積算をしておりますので、委員ご心配の不調関係につきましては、今回１社の落札があったということで、ほっとしています。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"強度やコストの面では何か違いがあるのかということを教えていただければと思います、それが１点です。それから、先ほどスケジュールで、平成２９年７月開所予定ということだったのですけれども、その間のざっくりしたスケジュール、例えば近隣説明会がいつ頃からあるとか、そういったことも含めて教えていただければと思います。","respondent":"小林施設整備課長","answer":"細かいのを入れますともう何十回もやっていますので、大きなところを説明しますと、一番最初は平成２６年６月３日から計画説明会を行いまして、大きな事業計画につきましてはその後平成２６年１２月１６日等、５回ばかり事業計画説明会は行っております。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"少しずつその工期ですとか単価水準とかが変わってくるとは思いますが、これは要望です。それから、もう一つ伺いたいのは、先ほど出ていました要援護者を災害時の最優先の対象とするということなのですが、この要援護者は高齢者をイメージしているのか、障害者も加えて考えていらっしゃるのかどうか、それをお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"こちらの建物は福祉避難所という位置づけになっておりまして、避難所および二次避難所の避難者と避難生活を送ることが困難な要介護者を保護する施設という位置づけになっておりますので、そちらのほうに当てはまればよろしいかなと思います。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"一つ一つ細かく確認することはしませんけれども、一般的な施設よりもある程度以上の障害を持った方にも対応できるような施設設備が備えられたしつらえになっているという期待を、今のご答弁からはするわけですけれども、それはご答弁いただけますでしょうか。もしそうでなければ、今からでもできるだけのしつらえはしていただきたいと思います。","respondent":"小林施設整備課長","answer":"私の言った今回のこの災害応急対策計画は防災課のほうがメインかと思われるのですけれども、すみません、間違っていたら申し訳ないのですけれども、ここら辺について詳しく私のほうはわかりませんけれども。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"それに基づいて、今後いろいろな内容を見たときに要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほどほかの委員からもありましたけれども、本体のほうで辞退、あるいは落札が１件で、ほかは辞退ということですが、それはもう先ほど質疑があったので結構なのですけれども、ここ二、三年ぐらいずっと落札不調で、品川区では起きてはいないと思うのですけれども、結果としては工事はできているということだと思うのですが、今回４議案一括議題ということでまとめて伺いたいのですけれども。","respondent":"小林施設整備課長","answer":"今の質問でお答えしますと、落ち着いたと言われていても、やはりこれからオリンピックの関係の事業も増えてきますし、業者とちょっとコミュニケーションしていますと、やはりかなりまだまだという感じだと思います。","id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"質問","question":"現場のご苦労も今感じたのですけれども、先ほど経理課長からのこういう状況になったというのは、各社のいろいろな状況もあるし、積算が合わないとか技術者の配置が間に合わないとかということもあるのではないでしょうかというような、多分一般論としておっしゃったと思うのですが、先ほど施設整備課長も１社が落札してくれてほっとしたというのは本当の心情。","respondent":"立川経理課長","answer":"スライド条項の適用に関しましては、国・東京都等の動向を見まして、適用するときは適用するです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"意見","question":"特別養護老人ホームができるということで賛成なのですが、この総務委員会の所管から外れてしまうと言われるかもしれませんが、やはりこの地域交流スペースは、上大崎は本当に施設がないところなので、積算が合わないと聞くとどきっとするのですが、なるべく微調整とかそういうところで、地域交流スペースが有効に近隣の方に使われるように、それから防災拠点が本当に要介護の方たちに有効な形になるように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-03","title":"第８２号議案 土地の売払い","agenda":"第８２号議案 土地の売払い","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"この土地はようやく売却ができたというのはほっといたしました。ちょっと参考までに教えていただきたいのですけれども、この土地は区で利用しようにも、なかなか保養施設のようなものを建て直すのは厳しいというか、制度上難しいという話を聞いていたのですけれども、この購入された相手方というのは、多分別荘関係等々を扱っていらっしゃる会社なのかなと思うのですが、ここは何かを建てられるのでしょうか。","respondent":"立川経理課長","answer":"森泉という会社ですが、こちらは森ビル、森トラストグループの会社でございまして、事業としましてはコンサルティング事業を行っているということです。取得後はグループ会社の保養所兼ゲストハウスを現在のところ予定していると伺っております。","id":"exchange-035"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、そういう個人的に自らのものを建てるのは構わないというような括りだったのですか。営業はだめということには適合しているから、売却できたという理解でよろしいでしょうか。","respondent":"立川経理課長","answer":"ただいま委員からお話がありましたとおり、いわゆる営利目的以外の利用ということで、一応こちらはいわゆる別荘地内にありますので、東急不動産のほうでその辺、各所有者と覚書を交わしまして、いわゆる営利事業を禁止しているという土地です。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"区の土地であるということは、当然区民の財産というわけで、この間の経過の中で少し下げてきた経過がありますけれども、今の時点でどのように思っているのかというところを伺いたいのですけれども、しくみ上、財産価格審議会を通じて価格を決めて、それで販売したけれども、経過の中で政策判断で下げてきたということですけれども、その辺、今振り返ってどうなのかというのを一言伺いたいと思います。","respondent":"立川経理課長","answer":"それで今回、徐々に値下げをして売却したですけれども、国有財産の評価基準というのがございまして、こちらは財務省の基準で、こちらのほうを準用いたしまして、この考え方というのは、一般競争入札対象財産について評定価格を求めるにあたって、需給の状況等を考慮して。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、今後品川区として、また何か区の外に不動産を求めていくような考えがあるのかどうか、そういう可能性はあるのかどうか。そしてそういうことがもし行われる場合には、どういった点に留意をしていくことをこれまでの経緯の中で学んでいるのかということを、ちょっと整理していただきたいなと思っているのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"そういったところを検討しながら、どういう方向に持っていくか、まだ何か決めているというわけではありませんけれども、そういういろいろな外側のファクターだとか、いろいろなものを検討しながら検討を進めなくてはいけないのだろうと思います。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"不動産に関しては、一度重荷になってしまうと、それがなかなか動かせずに何十年も区の財政にマイナスを与えてしまうことも多々ありますので、ぜひ慎重に今後も検討していただく。もしすることがあっても、慎重になっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"平成２７年請願第２２号 固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２７年請願第２２号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"内容については、うちの会派でもサインしているということもあるのですけれども、固定資産税、特に１番の小規模住宅用地に対する軽減措置は、昭和６３年から３０年近くずっとこういう形で、請願は１年ごとの延長ということになっているということ自体が、法の運用として非常にイレギュラーに感じるのですけれども、それを何か改正していこうというような、法そのものを改正していこうという動きは。","respondent":"黒田税務課長","answer":"いわゆる固定資産税につきましては、地方税法に定める税目の一つになりますので、全国一律にまず税法として適用される中で、固定資産の課税評価に対して金額が計算されるという制度の中で、都の独自の制度は東京都の中で当時地価が高かったというような状況がありまして。","id":"exchange-040"},{"speaker":"あべ委員","kind":"質問","question":"例えばその条例のほうで、１年ごとではなく３年とか、そういう話も全く出ていないのでしょうか。","respondent":"黒田税務課長","answer":"いわば東京都に限らず、税に関しましては毎年国のほうで税制改正をやっておりまして、その税制改正の影響を受けて、各地方公共団体、都道府県なり市町村なりがその税制改正の影響を見込んで、どのように改正するかというようなことがあろうかと思いますので。","id":"exchange-041"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問というか、ちょっと教えていただきたいところで、固定資産税、これは議会でも意見書を出しましたけれども、地方税の一部国税化という話と、この固定資産税の軽減措置には、相関性か何かがあるのかないのか。","respondent":"黒田税務課長","answer":"固定資産税について、いわゆる地方税の国税化という分とはリンクしていないと思いますが、国のほうで地方財政計画を立てる中で、各都道府県なり自治体がどのぐらいの収入があって、それに対する需要額が幾らで、それで足りない分を国が地方交付税として出すという流れの中で。","id":"exchange-042"},{"speaker":"本多委員","kind":"意見","question":"結論を出すべきだと思います。内容につきましては、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"中塚委員","kind":"意見","question":"請願第２２号、請願第２３号ともに結論を出すべきということと、内容は理解できますので、採択するということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-05","title":"平成２７年請願第２５号 外国人の人権が十分尊重されることを求める意見書の提出に関する請願","agenda":"平成２７年請願第２５号 外国人の人権が十分尊重されることを求める意見書の提出に関する請願","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"質疑というより意見ですけれども、ここに書かれていた内容、それから先ほどご説明がありましたけれども、やはり基本的人権を守る立場から言えば、単なる憎悪表現という言い方もあるみたいですけれども、憎悪を表現するだけではなくて、その対象者に対して恐怖心を与えたり、あるいは差別を扇動するというようなより積極的な害悪をもたらすものとして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"１点、区の取組みについて、現状認識については先ほど若干ご説明がありましたけれども、このヘイトスピーチをなくす、また許さない取組みとしては、具体的にはどういう取組みがあるのか、そこだけ伺いたいと思うのですけれども、私自身はヘイトスピーチについて、特定の人種や民族に対して差別や暴力をかき立て、権利や自由を制限し。","respondent":"提坂人権啓発課長","answer":"幸い区内でヘイトスピーチというのは起こっていないと把握しているのですが、法務省のほうでも「ヘイトスピーチ許さない」というポスター、リーフレットをつくりまして、啓発活動を進めているところです。区でもそれに沿った形で、積極的に進めたいと考えています。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"区にぜひ貫いていただきたい姿勢ですけれども、今おっしゃるように、異なる文化や、また人権擁護や、これは当然貫いていただきたいと思うのですけれども、在特会は在日韓国朝鮮人の特別永住資格を特権と主張するわけですけれども、植民地支配による在日韓国朝鮮人の苦悩や、村山談話による痛切な反省とおわび、日韓相互理解のかけ橋を強調した日韓共同宣言など。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほど、人権啓発課長からも区の取組みということで伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしても、特に在特会の名前が挙がっていますけれども、本当にこういう永住するに至ったことについて、その経緯を含めて考えると絶対に特権ではないということは明白だと思うのです。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"本多委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。考え方につきましては、今の説明でも国会が審議未了になることが予測されますので、こういう事態に対しましてこの総務委員会で採択をし、国に意見書を出す必要があると考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"意見","question":"今日結論を出すということで、先ほどちょっと申し述べ忘れてしまったことで、全国市議会旬報の５月２５日号を見ますと、全国の各区市町村議会で、ヘイトスピーチについてというもので出された意見書が５６件というところで、これはもう今年の１月から４月の分だけですね。ちょっとネットを覗いてみたら、もう１００以上の自治体で声が挙がっているということも触れられてありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということと、意見書を出すということで、採択を主張したいと思います。在日朝鮮人の特別永住資格を特権などと攻撃する在特会の論理は本当に許されないと私は思いますし、こうしたヘイトスピーチの根絶に向けて、我々政治家、議会が果たすべき役割・責任はとても重いと思いますので、採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日、結論を出すということでお願いしたいと思います。それで、その理由については先ほども申し述べましたけれども、あわせて区に対してお願いしたいことを加えたいと思います。ただその外国人の人権を侵害してはいけないという以上に、やはりいろいろな人たちがつくる社会のほうが活力があるのだというプラスのメッセージも、あわせて地域の中で発信していただきたいということをつけ加えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"我々も本日結論を出すということと、採択ということで、一言意見を言わせていただきます。国でこういう大事なことが今回審議未了になったということは、やはり残念なことです。やはりもっと国でこういうことはしっかり、前向きでなおかつ素早くやるように実行していただきたいと私は強く言いたい、それだけは言いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということで、採択したいと思います。外国人だけでなく、やはりすべての人が同じ人権を持って誰からも尊重される存在であるわけですから、この請願はこのまま採択ということと、それから区の取組みとしては、外国人に限らず、やはりヘイトスピーチということ自体が本来あってはならないものであるということをぜひ啓発していただけるように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-06","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私のほうからは１点だけなのですけれども、初日の自民党・子ども未来の石田秀男議員の質問の「区政運営について」の中で、答弁で「区の施設のあり方を検討する」という話があったのですけれども、具体的にどういうことが今検討されているのか、そのスケジュール観も含めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":36495,"voices":178}},{"id":"h27-20150925-6","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"区民委員会","time":"午前１０時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"町会・自治会の活動活性化のための支援制度の再構築","agenda":"町会・自治会の活動活性化のための支援制度の再構築","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺について、改めて、依頼業務の整理、統合というのは、どういう角度で見直しをしているのかというところを、もう一度、しっかり伺いたいと思います。そのあたりの確認をしたいと思います。八潮は自治会というのがあって、自治会連合会というのがありますので、そういう点では、こういうものにはそぐわない、なじまないかなとちょっと思ったので、そのあたりを確認したいと思います。","respondent":"久保田地域活動課長","answer":"ここの部分は、八潮の自治会のないところということのイメージではございませんので、一般的なマンションの加入等の対応、役割として、そういうことをきちんとやりましょうということを促していきたいという考えです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"支援ということで、後押しが趣旨だというふうなことなんです。拘束ではないとさっきも説明されたのですけれども、今までのような支援体制でなぜできないのか。もう少し、耐震だとか、会館を持つだとか、空き家をいろいろな法的な整備をしながら会館にしていくみたいなことというのは、今までもやってきたけれども、なぜ、ここで条例化なのかというのが、説明を伺っても、まだよくわからないのです。","respondent":"久保田地域活動課長","answer":"それぞれの支援制度も今までたくさんやってきましたけれども、この条例化を根拠に、なぜ町会・自治会を支援するのかということを明確にしていきたいという意味もありまして、条例化を進めていきたいと考えているものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"条例化されたとしても、そこは自由にしておくべきだと私は思っているのですけれども、そのあたりのことをどういうふうに考えているのかを聞きたい。やはりいろいろな取組みの中で参加をする。私はそう思うのですが、区としてはどういうふうに思っていられるのか、そのあたりの見解を伺って、終わりにしておきたいと思います。","respondent":"久保田地域活動課長","answer":"そうした中で、なぜ条例をつくるかというのは、町会・自治会の活動を後押しするということの区の姿勢を明確にするといったこともありますし、町会・自治会を支える上で。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"最後に１点だけ述べて。私は、日常の取組みが大切だとおっしゃった、まさにそのとおりだと思うし、そういう地域のコミュニティを醸成させるような活動ができるような環境に、やはりそこはきちんと守っていくということが大事だと思うのです。無理だと言い切ってしまいましたけれども、そういうふうな危惧をすごく感じるので、そこのところは、少なくとも大事にしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"端的に４点お聞きします。最初に、品川区の町会・自治会加入率というのは約６割と聞いているのですけれども、まずはそれでいいかということ。それが２３区の中でどれくらいの加入率、高いほうなのではないかと思うのですけれども、そのあたり。それから、２３区、もしくは他自治体でもいいのですけれども、こういう条例をつくっていらっしゃる自治体があるかどうかということ。その４点、お聞きします。","respondent":"久保田地域活動課長","answer":"具体的に考えているのですが、何をもって頑張っているかとか、何をもって一生懸命やっているかという基準が非常に難しいということもありますので、頑張っているということの表現をどこで捉えるかはありますけれども、例えば自主的な活動を支えるような支援、仕組み。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川区も、当然、皆様も思っているとおりで、町会・自治会が本当に頑張っていらっしゃるというのは、２３区で見ても、また全国的に見ても、非常に一生懸命取り組んでいるということは確認していただいた中で、さらに、これからの高齢社会だとか、地域包括ケアとか、災害の面とか、いろいろな面でまたお世話にならなければいけないということで。","respondent":"久保田地域活動課長","answer":"１点目ですけれども、私どもも、町会・自治会の事情というものは把握していますので、小さい町会で、やりたくてもできないといった事情も踏まえまして、そういった町会には、違う面での活動を支えるような支援をしていきたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"今の話なのですけれども、４つの町会・自治会で話したところ、ありがたいと言ってもらえたということなのですが、言えなくないですか、反対意見というか、言いづらいですね。そう思ってしまうのは私だけでしょうか。アンケートを配ったということだったのですけれども、そのアンケートというのはいつごろ配ったり、掲載したり、私、知らなくて、伺ってもいいですか。","respondent":"久保田地域活動課長","answer":"今回、町会・自治会の調査研究委員会においても、実際に町会・自治会の会長、５名の方にも委員としてなってもらってありますので、そういった中でも、品川区として町会・自治会の活動を後押しするような根拠となるものが欲しいという意見も出ていたということでございまして。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"その加入促進のパンフレットの作成は、確実に町会の方に渡すというわけではなくて、希望の町会の方にしか渡さないのですか。空き家などを活用した会館はまだないということなのですけれども、空き家の活用はそんなに簡単にできるものですか。空き家を持っている方との話し合いとかも、結構難しい。","respondent":"久保田地域活動課長","answer":"その空き家があっても、町会会館として適しているかどうか。さらに、空き家となっている所有者の方にも、いろいろな事情があって空き家になっているわけですので、そういった意味では非常に難しいです。","id":"exchange-008"},{"speaker":"松永委員","kind":"質問","question":"以前、町会に入りたいのだけれども、誰に頼めばいいかわからないという人もいらっしゃったので、そういった方々のフォローとして、このはがきというのはすごくいいのではないかと思うのです。先ほども、宅建協会だけではなく、ほかもやっていきたいということだったので、ぜひお願いしたいと思いますが、まず、どこ宛てに送られることになっているのか教えてください。","respondent":"久保田地域活動課長","answer":"住所が書いてありますので、住所を見て、私どものほうで町会の区域を調べて確認した上で、町会長のほうにご連絡をして、それで、両者でアポイントをとってもらって加入をしていくというような仕組みで、加入促進のはがきを活用しています。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"それで、今まで、そういったはがきをやられていますが、今、どのくらい、そういった結果が返ってきているのか。それはいつから始められたのか。教えていただきたいと思います。","respondent":"久保田地域活動課長","answer":"数は少ないかもしれませんけれども、２０件は来ているということで、それなりに少しずつは成果が上がってきているのかなと思っているところです。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問・要望","question":"町会加入を促進するということはなかなか難しい部分があって、マンションでもオートロックになって、なかなか教えてくれないという部分もあるし、理事長というか、マンションを管理している偉い人がなかなか教えてくれない部分もあるのですけれども、そういった中で、マンションの加入促進について、何か案とかはあるのでしょうか。一番難しいですけれども、町会に入って、主にメリットというか。","respondent":"久保田地域活動課長","answer":"それとあとは、いろいろな活動をしている中で、やはりファミリー世帯の方はよくあるのですけれども、加入をしていなくても町会の行事とかに子どもが来れば、町会の人は、その地域の子どもですから、分け隔てなく対応はしているのですが、そういったことに対して。","id":"exchange-011"},{"speaker":"松永委員","kind":"質問","question":"わかりました。例えば、いろいろな各町会・自治会で、地域センターごとでもあるのですけれども、お祭り等がある中で、できないとは思うのですが、町会に加入しませんかみたいなブースというのはつくれないのですか。","respondent":"久保田地域活動課長","answer":"そうですね。ご提案として、私どももなかなか、お祭りというと、お祭りのことばかり考えていますので、多く人が集まってくるところを使って加入促進するというのも一つ有効な方法だと思いますので、今後、検討させていただきたいと思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"制定していこうと思っているので、何かご意見があったらという言い方だったら、きっと意見とかも言えたと思うのですけれども、きっとそういう少しの言葉のあれでコミュニケーションがとれなくなってしまったりとかすると思ったのですけれども、どうでしょうか。","respondent":"久保田地域活動課長","answer":"私の説明が不足したのですけれども、私ども、条例を制定しますということでは、条例を制定していきたいので条例案をつくってまいりましたということで、皆様のご意見をお伺いしながら内容を決めていきたいと思っていますので、本日、伺いましたということで。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういったところにうまく応用のできるものはたくさんあると思うので、これももちろん項目ではあるので、その辺どうお考えかというか、条例制定とその後の施策に見直しというタイミングというものもあるようなので、その辺の支援の仕方というのを伺いたいと思います。これが２つ目。これもやはりＰＲのところの評価に反映させるべきと思うのですが、その辺の考え方を３つ目として伺いたいと思います。","respondent":"久保田地域活動課長","answer":"さらには、他課や他部でやっております、いろいろな制度がありますが、そういったものも応用活用ができないかということも検討していきたいと思ってありますので、小規模町会への支援ということも視野に入れながら、再構築の検討を進めていきたいと思ってあります。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"この辺を特化して、スペシャリストというのですか、こういうものも行政マンとして、地域のボランティアとは別枠で、またその支援員の制度があるべきかな、必要が出てくるのかなという気がしています。どこかの地域センターに出向くというよりは、楽をするとかではなくて、全体会に行くのは結構だけれども、やはり自分の村といいますか、自分の町会だけの空間に来ていただくというのを求めると思う。","respondent":"久保田地域活動課長","answer":"支援員制度ということについては、今後の調査研究課題かなとは思ってありますが、私どもも、地域相談窓口というものを設置しましたのは、地域課題解決のために町会・自治会がやっているのですけれども、町会・自治会で抱えているお困りごとを区がちょっと支えよう。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"というのは、うちは鹿嶋神社ですから、１０月にお祭りがあるのですけれども、山車でもおみこしでも、町会にこんな方がいらっしゃったのですねという方が数多く出てくる。たった２日、準備を入れて４日、５日しかないですけれども、ここにポイントを置いていきたいと、町会をお手伝いしている側ではすごく思うのですけれども、毎回、お祭りにもというお話が出ると、答弁は一緒ではないですか。質問です。","respondent":"久保田地域活動課長","answer":"品川区のほうとしても、特定の宗教のほうに支援をするということは、政教分離の原則から大変難しいものがありますが、町会・自治会が今行っている、神社の祭礼ではありますけれども、おみこしを出したり、山車を出したりするということは。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、政教分離というお話が出ましたけれども、これは法律的担保があると思うのです。政教分離だから出せない。それはどういう法律なのか、わかれば教えていただきたい。憲法に出ていますとか、そういうのでいいのです。","respondent":"久保田地域活動課長","answer":"憲法のほうに規定をされているです。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"例えば、どこでどうするかわからないけれども、１回、解釈を議論してみるのも、私はいいと思うのです。公務員の皆様は、憲法に準するとなっているのですから。だから、憲法に出ている以上は、それを遵守しないといけないというのはわかるのですけれども、やはり法の解釈という面が出てくると思うので、ちょっとその辺もこれから考えていっていただきたいという思いもあるのですけれども、いかがでしょうか。","respondent":"久保田地域活動課長","answer":"ただ、祭礼行事をやるということに関して、品川区が助成金を出すということに対しては、憲法上の規定とかからも難しいというふうに考えてありますので、私どもは、今、品川区としてできる範囲の中で、ご協力をさせていただいているです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"よくわかりました。行政として、憲法は守るということで、その法の解釈をいろいろ考えても、今の時点ではできないということを確認させていただいて、すっきりした気持ちで質問を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"渡部副委員長","kind":"質問","question":"いよいよ長年のときを経て、このときが来るのだなという感じがいたします。今日、もし区民委員会に各町会長たちがいたら、久保田課長が大変たくましく見えたのではないか。こんなのが来たけれども、どうやって書いたらいいのだろうというようなお話も耳にはしました。何かその辺、教えていただけるところがあれば、一言、教えてください。","respondent":"久保田地域活動課長","answer":"そういった意見を反映させて、条例化、そして仕組み、３つの柱に基づく支援制度の再構築を図っていきたいというふうに考えてあります。","id":"exchange-020"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ありがとうございました。現に、委員によっては、なかなか出せないというような空欄のところもあると思います。当然、それは町会で何とか出していただきたい。それは当然、区長部局のほうで考えていかれることだと思うのですが、今の時点で、この辺、このような形で町会・自治会を支援していく中で、地域センターの役割というのをどのようにお考えになっているのか、この時点であれば、教えていただきたい。","respondent":"久保田地域活動課長","answer":"それと、地域センターのあり方ですが、平成２８年４月１日で地域センターが大きく変わるということは、今のところ予定はしてございませんけれども、こうした取組みの支援をしていく中で、地域センターのあるべき姿というものも考えながら、より町会・自治会が活動しやすくなる。","id":"exchange-021"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"本当に今の支え愛・ほっとステーション、看板はかかっているけれども何もやっていないみたいなことはなくしていただきたい、看板がかかっていますからね。今でもそうだとは思うのですが、やはりこのような形をとられていくからには、町会からの要望を地域センターである程度、解決ができるような、時間もとらせずにというぐらい、地域センターで役割を持っていただきたいというような要望。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"いろいろ悩んだのですけれども、問題意識だけ、ちょっと言いたいと思っているんですが、さっき、それなりの質問をさせていただいたのですけれども、１３地区に地域割されていますね。その辺について、品川区としてはどういうふうに見ておられるのか。政治団体ですから、個人のものですのであれですけど、その辺についての認識はどうなのかというのをちょっと聞いておきたいと思いました。","respondent":"久保田地域活動課長","answer":"私どもは、町会・自治会の活動を支えるですので、町会長、自治会長が個人の意思で活動されているということに関しては、私どもが意見等を言う立場にはないと考えています。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"そういう誤解を与えるようなことはやはりやるべきではないと思うし、そういう点で、それなりの必要な発言というのは、どこの部分で、どういうふうにするのか、私はわかりませんけれども、区としては、仕切りはしっかり守っていくという、少なくとも同一人物がかからないという角度で捉えていく必要はあるのではないかというふうに思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-02","title":"秋季プレミアム付区内共通商品券発行事業への助成","agenda":"秋季プレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"南委員","kind":"質問","question":"改善をする必要がある部分があれば、それがどういうところなのかというのを伺いたいのと、あと、ネットで見ただけなので、確実性という点ではどこまで信用していいかはわからないですけれども、そういうふうに思いながらも、プレミアム率が品川区は１０％ですけれども、２０％をとっているところもあるし、たまたま３０％ぐらいとっているところも幾つかあるという状況なのです。","respondent":"山崎商業・ものづくり課長","answer":"これも、先ほどの繰り返しになりますけれども、いろいろなノウハウの積み上げとともに、あと、この事業の交付金を国のほうが検討する際も、実は、先代の課長の時代でしたけれども、国のほうから品川区のノウハウを活用したいのだということで、実際にやりとりを品川区とやって。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。何も混乱がなく、しかも広く購入していただけたという効果がそれなりにあったというふうなことで、了解をしたいと思います。品川区も財政的には決して厳しくないし、ゆとりのある財政状況もあるので、やはりやっていっていただきたいということを要望としてお伝えをしておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"意見","question":"１人の上限は幾らかということと、あと、販売方法がこの３つの場所で同じかということと、さっき南委員からも出たのですけれども、問題は本当になかったのかということを聞かせてください。","respondent":"山崎商業・ものづくり課長","answer":"この春につきましては、８億円の発売ということですので、相当、いろいろ初日の対応だとかというのは必要だろうということで、必要なところに警備ですとか整理をしていただくようなことも配置しましたり、事前の準備をかなり品川区の場合はやりましたので。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問","question":"これは問題にならなかったのかどうかわからないのですけれども、ちょっと聞いた意見を言ってもいいですか。その販売方法が同じかというのをなぜ聞いたかというと、名前、住所を記入していれば、そういったことはきっと起きなかったではないですか。でも、そういう対応はなかったということですね。しているのですか。でも、他区の方でも買えてしまったそうなのですけれども、それは問題ではないのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"品川区外の方につきましては、本事業につきましては、商店街振興の意味合いがありますので、来街者が品川区内の商店街で買い物をしていただくようなことも想定をして、品川区外の方でもお買い求めできるというようなことで、制度のほうは設計しております。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"書いている人は１人なのですけれども、それでも大丈夫なのですか。知り合いの名前とかをがーっと書いてしまって、１人の人がそれで買えてしまったことがあったのです。","respondent":"山崎商業・ものづくり課長","answer":"ただ、例えば、ご家族の方で外出がちょっと困難なような方については、家族間でお願いをして、例えば自分の分とおじいちゃん、おばあちゃんの分を一緒に買うというようなことも可能にしておりますので、そういう意味では。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"同居している方ではなくても、家族ではなくても買えてしまっていたわけではないですか。その販売しているときに円滑するように対応しているということですけれども、そうしたら、買い占めが起こってしまっているわけですね。","respondent":"山崎商業・ものづくり課長","answer":"それをご家族内で１人まで、あるいは２人とかというようなことについては、一つの検討事項かなというふうにも思ってありますので、代理購入は何人までというようなことも、一つ、今回は検討事項、制限として取り入れているようなことで、制度のほうは考えていきたいと思います。","id":"exchange-030"}]},{"id":"topic-03","title":"区立総合区民会館・区立荏原平塚総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","agenda":"区立総合区民会館・区立荏原平塚総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"総合区民会館の件ですけれども、文化振興事業団にお願いして、管理していただいているということですが、１面の一番下のところには改修工事というふうに触れているので、これに関して気が付いたのですけれども、私どもも、この間、あそこの施設の点字ブロックについて改修をということをずっと言ってきているのですが、お金もかかることなので、なかなか改善が見られていないというところもあって。","respondent":"間部文化観光課長","answer":"今後も、こういったオリンピック・パラリンピックということで、パラリンピックがあるわけですから、お体の不自由な方が訪れることもありますので、そういった面については先方とも十分協議しまして、工事をする際に。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけ早く、そういう対応で、来年度中には、その工事が入っていければいいかなと考えていますので、そのことも含めて対応していただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"きゅりあんのことなのですけれども、大ホールの授乳室というのは、母子室のことですか。それとも、また別なのですか。","respondent":"間部文化観光課長","answer":"母子室は別に……。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"スクエア荏原、この裏面のほうで、２番で、利用料収入が予算額を上回っていたので、区からの指定管理料の返還につながったとなっているので、ここは利用料金制みたいな感じになっているのですか。そうすると、きゅりあんのほうもそうなっているのだと思うのです。それと、それに合わせて予算を、またもうちょっとハードルを上げるのかななんて思うのですけれども、その辺の考え方を教えてください。","respondent":"間部文化観光課長","answer":"大体、利用が４０％か５０％だろうというところがかなり上がったということがありましたので、その分、返還金が当初予定より１,５００万円ぐらい多く返ってきたというようなことがございました。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"区立総合区民会館、きゅりあんについてお伺いするのですけれども、利用率、稼働率においても高い数字を維持していると私は思っているのですが、２３区の各区においても、こういう区立の総合区民会館というものがあると思うのですけれども、全部はいいですが、そういうところの利用率と比較すると、もし数字的に持っていれば、平均とか、何か例があったら教えていただけますか。","respondent":"間部文化観光課長","answer":"私が聞くところによりますと、立地もあるのですが、大井町の駅前ということで非常に使いやすいという条件はありますけれども、通常の区立の会館におきますと、大体６割程度だというふうにお聞きしています。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"私は、興味を抱いて質問をさせていただいているのですけれども、きゅりあんを引っ張っている館長はどういう方がやっているのか、ものすごく興味があるのですが、これに出ている平成２４年度、平成２５年度、平成２６年度、館長がかわっていないかもしれないし、かわっているかもしれないのですけれども、こういう利用率を維持していく館長は一体どういう経歴、どういうことをやってこられた方なのか。","respondent":"間部文化観光課長","answer":"きゅりあんの館長につきましては、会館のころからなのですが、我々、指定管理が入ってからになりますけれども、きゅりあんの管理課長がきゅりあんの館長ということです。今現在の館長も、先代の館長につきましても、区の管理職のＯＢです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"そうですか。そうですか。指定管理ですから、それを全部システム化してというのはできないと思うのですが、やはりこういう形でも評価をして、一つのうまくいっている事例として、これからも活かして、課も部もあるのですけれども、そういうのはやはりＯＢの方たちを活用していく。ご本人の意思とかはいろいろあると思うのですけれども、これは大事なことだと思うのですが、その辺についてはいかがでしょうか。","respondent":"間部文化観光課長","answer":"これは人によって考え方は違うと思いますけれども、今、高齢社会を迎えておりますから、人生、６５歳から７０歳ぐらいまで定年が延びるといった話の中では、そういった活用も一例としてはあるのかなというふうに認識をしております。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"区内全域で。その点は今、どう課題として捉えられているのかどうか。やはりこれからオリンピック・パラリンピックも控えた中で、地域センター等はその近隣で済む話だと思うのですが、特に全区的なこの３施設、きゅりあんは結構、知られていると思うのですが、この辺、標記の仕方、ガイドの仕方、工夫が必要ではないかと思うのですが、いかがでしょうか。","respondent":"池田スポーツ推進課長、間部文化観光課長","answer":"ということで、ソフト的な部分については、ここ何年もスポーツ協会、そして総合体育館という存在をＰＲするように努めてあります。スクエア荏原につきましては、今年度、３年目ということで、３年目にしては、私自身としては、知名度は上がっているかなという認識があります。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"ですから、これは所管だけではないとは思いますが、働きかけが特に必要だと思ったので、タクシーは一例ですので、そのタクシーもわかるには、ふだんから、その場にお客様を運ばなくても、表示があれば意識の中で深まっていくと思うのです。これはもう最近だけではなく、ずっと思っていたことなので、ぜひご検討をいただければと思いますが、もう一度、ご答弁をいただいて終わりにしたいと思います。","respondent":"池田スポーツ推進課長","answer":"道案内、特に五反田駅、大崎駅、２つの駅が利用できるわけですけれども、どちらからのアクセスについても、歩いて１０分圏内ということですけれども、わかりづらいというところがあるかもしれませんので、ここら辺につきましては、関係各課に。","id":"exchange-039"},{"speaker":"松永委員","kind":"質問・要望","question":"例えば、平成２４年度で戸越体育館はこのぐらいで、平成２５年度はこのぐらいということで、総合体育館は大体これぐらいということで教えていただきたいのと、あと、改善点が必要な事項の中で、新たな事業の企画や需要の低い事業は縮小や廃止とありますが、どういったものが縮小されて、廃止になるのか。","respondent":"池田スポーツ推進課長","answer":"利用者につきましては、人数が少ないということで、実際に来られた人数が１桁、それも５人以内の少ない人数でございましたので、その方には、その場でお話はさせていただいてあります。","id":"exchange-040"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"最初の岡山市なのですけれども、もうちょっと勉強しなければいけなかったのですが、例えば、品川区でこのカウンターをやろうと思ったら、品川区の判断だけでできるというふうに思っていていいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"渡部副委員長","kind":"提案","question":"これは、僕、興味があると思って、委員長と提案させていただいたのですけれども、実は、ヤマダ電機がこの制度を使っていると考えられます。もう６階に免税カウンターができていますので、制度運用を私どもが今回しっかり勉強してお願いすれば、そこに大井町の商店街が乗っかることが制度上、可能なのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"私も、たけうち委員と同じ質問をしようと思ったのです。品川区にどうやって活かして、視察に行ってからなのですけれども、同じ質問だったのです。品川区にどう活かしていくか。そのための視察ですから。今、たけうち委員が質問をなさって、お答えするのが部長かなと。部長が説明しているのだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤原委員","kind":"質問","question":"いや、副委員長、そうではなくて、それで、副委員長が正確にお答えになった。ああ、こういうのはいいなと思ったのです。だって、委員長、副委員長にお願いをしている。いい意味で言っているのです。だから、こうやってお答えできるわけではないですか。いいですよね。直接の質問ではないのですけれども、今の場面を見ていて、やはり区民委員会は時間を短くではなくて、こんな長くなる委員会なのだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/719578?Template=document&Id=2734#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":56582,"voices":146}},{"id":"h27-20150925-7","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)、平成２６年度 指定管理者の管理に対するモニタリング・評価の結果","agenda":"はじめに、(1)、平成２６年度 指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"ちょっとまずは何点かお伺いしていく中で、根本的なことをお伺いしたいのですが、このモニタリング評価の結果、今、冊子になっていますが、これを作成するに当たって、これは各施設に総括シートというか詳細なシートに記入をしてもらって、それから各所管でそれを取りまとめたのがこの冊子でいいのかどうなのかという、ちょっと何かこの文言とか言葉を見ていると、誰が書いたのかななんて思いつつ。","respondent":"永尾高齢者福祉課長","answer":"それで、その後、モニタリングの作業があります。５月末までに指定管理者はモニタリングの報告書を区のほうに提出をして説明があり、区の所管はその後に評価をし、それで経営会議を行って、本日の議会報告というふうになります。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それが満足度が高ければ高いほど、その施設はサービスが向上されたということが目に見えてわかりますので、必要ではないかなと思うのですが、その辺についてお伺いします。利用と稼働はぜひ統一をして、例えば高齢者のところだと、みんな利用率と書いてあって、下では稼働率が達成したと書いてあると、どういう意味なのかなと思ってしまうので、その辺は統一をしっかりしていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ただ、その度合いというのがとても難しいところではあるのですけれども、満足というのが何でもやってあげてしまうことが満足というふうになってしまうのもちょっと問題があるので、ただ、このモニタリングの中で。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どちらにしても、こういった施設は常にそのサービスの向上、多分ゴールはないと思うのですよね。サービスを提供すれば、あり余るサービスという言い方が妥当かどうかは別にしても、サービスを向上するということはやはり人的配置もしっかりと行っていかなければならないと思いますので、今後そういった部分もしっかり目を光らせて、行政として見ていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"幾つかちょっとお聞きしたいのですけれども、管理運営委託料というのが結構、毎年違ったりですとか、ないところとかもあったのですけれども、その考え方ですね。これをちょっと教えていただきたいと思います。稼働率なのですけれども、結構高いところでもさらなる向上をするとかと書いてあるのですけれども、区としてはどういったところを目指しているのか、考えがあったら、お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"ただ、利用者というのはやはり人間なので、急に、例えば通所でいけば、本当は通所する、今日、そういう日なのに、朝ちょっと気分が乗らないなだとか体調すぐれないなということも多いし、また、急に入院してしまったりすることも多くなるということで。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"管理運営委託料のほうはいろいろ工事とかあって増減することがあるという話でしたけれども、八潮南認知症高齢者グループホームは管理運営委託料というのが０円になっているのですが、ほかのところは幾らかやはり管理するには必要だということで委託料があると思うのですけれども、なぜ０円なのかということを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"八潮南ですけれども、こちらは一つの建物になっておりまして、八潮南特養と一緒に管理経費が入っているということで、ちょっと分割ができなかったので、ここが０円というふうにしてあります。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"今、世間でも特養の虐待とか自殺者が出てしまうとか、障害者の施設でもそういった問題が今テレビでも放映されておりますけれども、そういった対策について、区のほうで何か事業者でやっているとか、そういったことを把握されているのか、あと、把握されているのであれば、そういった指導とか、どういった形でやっていかれるのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"事業者への虐待というのはこういう中の取り組みをしていますけれども、障害者のほうだと、事業者の虐待だけではなくて、家族の虐待なんかもあるというところで、そういうものの報告等も事業者からきちんと受けて対応しているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、これまで品川でどのくらい件数があったのか、もしわかれば、教えていただきたいと思います。職員の離職率等なのですけれども、特養ホームですとかほかの施設でも職員が定着しないということが改善点として上げられておりますけれども、区としてはどう考えているのか、どう指導していくつもりなのか教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"虐待ですけれども、ちょっと今出ているのが平成２５年度の数字しか手元にないんですけれども、区のほうでは安心しながわネットワークということで、高齢者虐待、ＤＶ、児童虐待に対しての対応を緊急一時の保護等を行っておりますけれども、平成２５年度の数学でいきますと。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者住宅のほうなのですけれども、どれも老朽化が進んでいると、それによって不具合も出ているということなのですが、修繕計画を事業者としては立てているということですけれども、これも区の施設として、これからどんどん老朽化しているわけですけれども、どういったお考えなのか、これから建て替えていくのか、それとも、大規模修繕してこのまま維持していくのか、そのお考えをお聞きしたいと思います。","respondent":"中山障害者福祉課長、松山高齢者地域支援課長","answer":"多様な選択肢をどのようにその状況に合ったその方にふさわしい選択肢を選びながら対応していくかというのは大きな課題ではありますが、現場レベルでは個々のケースを通じながらやっているところです。高齢者住宅の老朽化への対応についてですけれども、現在、確かにどの施設も老朽化しつつはあります。細かな修繕をしつつ、あるいは、管理者による中長期計画に基づきまして、施設整備の所管と協議しながら検討をしている最中です。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者住宅の施設整備課と調整しているということですけれども、今もうちょっと具体的にお話しできる点があれば、教えていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"高齢者住宅のもう少し具体的なところをですけれども、まだ個々のその住宅の建築や設備におきまして、かなり老朽化の度合いも異なっておりますので、具体的にちょっと今現在お話しできる状況にはございません。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"管理運営委託料なのですけれども、先ほどのお話ですと、基本的に修繕費というのは区が負担するという考え方でいいのかということなのですけれども、ここのさまざまこの管理運営委託料というのが出ていますけれども、これは介護報酬だけでは回り切れないというところを一般財源で補填するということでやっているのかなと思うのですけれども、そこの考え方と、それから、そういうことでいうと。","respondent":"永尾高齢者福祉課長","answer":"それで、このやっている中で、区が委託料として例えば中小の工事について委託料で出しますけれども、出している額というのも、多分障害と高齢と、また、健康課の部分ではちょっと仕組みは違っているのですけれども、高齢の部分でいけば。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでのチェックする仕組みというのは事業者からの報告というのを待つということではなくて、区としてチェックする仕組みというのがあるのかということと、それから、あと、ここの中でも５０ページのかがやき園のところでは、虐待に対しての行動計画を作成して取り組みを強化するということで書かれていたのですけれども、こういう行動計画という、虐待に対してのそういうマニュアルというか。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"社会福祉法人立の特別養護老人ホームについても、例えば成幸ホームであれば、平成２６年には例えば道路のブロック塀の改修の助成だとか、昇降機の更新とか、そういう部分での助成は行っておりますけれども。ここについては職員が障害への理解がしっかりできているかどうか、その障害の理解をした上で、適正な対応ができるかどうか、そこが多分一番職員にとっても苦しいところなのではないかと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、福栄会では虐待を絶対なくしていくということで研修されているということなのですが、ほかの社会福祉法人ではどうなっているのかということと、そういう福栄会ではやっているけれども、ほかのところではやってないというのであれば、全ての社会福祉法人がそういう研修をきちんと行って、虐待をやはり根絶させていくという取り組みが必要だと思いますし。","respondent":"中山障害者福祉課長","answer":"先ほどちょっと力を入れて福栄会の話をしてまったのですけれども、もちろんほかの法人でも研修のほうは実施されています。一番虐待が起こりやすいのが入所施設だと思います。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つお聞きしたいのが、今までもともと品川にあった社会福祉法人に加えて、さまざまな社会福祉法人が品川区に参入をしてきているという中で、そういう社会福祉法人同士で交流をして、介護の質とかにつなげていくような、そういうふうなものというのはあるのかどうなのかと、ちょっと教えていただきたいのですけれども。違ったかな。","respondent":"永尾高齢者福祉課長","answer":"ですので、来年度はもし予定どおりその実務者研修が必要になるというふうに決定になれば、その部分では区が助成をしているということになります。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"介護の中身というのも本当にいろいろと変わってきていると思いますけれども、さまざまな社会福祉法人が区の中にも入ってきているというところでは、いろいろと交流もしながら、さらなるサービスの向上というふうなところにもつながっていくといいなというふうに思っていますので、そういうところも含めて、今後取り組んでいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"基本的なことを教えてください。健康センターは変わったりもしているけれども、このまま品川の福祉を担っていただく社福なわけではないですか。そうすると、その中でも指定管理をしているわけですよね。","respondent":"永尾高齢者福祉課長","answer":"それと、指定管理にすることで、やはり民間の知識やアイデア、工夫、そういうものがより活かせるということと、実際に区でやろうとすると、やはり予算、決算というのが法律上きちんと会計の制度がやはり決まっておりまして、それをやっていると。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"私もそう思っていますし、ぜひそれをしっかり進めていただきたいと思います。これは区営の施設、区の施設なわけですよね。すると、その１行を書き足して、その各施設でそれに向けてどういうふうにしているのだという項目を足すだけで、それは意識づけになるわけではないですか。私はここに改めてその意識を高めてこうしましたよという書く必要がない項目だと思うのです。","respondent":"永尾高齢者福祉課長","answer":"ただ、施設によって福祉の部門とそうでないところとさまざまあるので、その中で企画のほうでなかなか統一しづらいのかなというように思いますので、また検討するときの一つの案件として取り扱いをします。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"そういうのが起きたとき、どうするのかなと。そういうこの指定管理以外で同じことをしている部分がありますよね。小規模多機能もそうだけれども、そういうことがあったときに、どういうほかの部分のところのフォローをされているのか、それはもうちゃんと把握してやっていますよということなのだろうけれども、そこら辺のちょっと考え方を改めて伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"ただ、区がこうやって対応するとか、あと、社会福祉法人であればこういうふうに対応するのだというような具体的なケースをそこで皆さんで話し合っていただいて。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひよろしくお願いします。本当にきのうも話が出たけれども、看護の話なども出るけれども、看護だって非常に大変な今度人材の部分も出てくるのだろうと思いますので、いろいろ情報をとっていただいて、いろいろな事業者の方とも話していただいて、ともにそこの部分は一緒にやっていただければなと、これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"ちょっと２点だけご質問させていただければと思います。","respondent":"永尾高齢者福祉課長","answer":"区としてのＰＤＣＡということになりますけれども、このモニタリングの評価で出てきたご意見に対して、区として改善するための取り組みをどうしたらいいかということを、これを受けて検討を行いまして、それがその結果が予算のほうに反映していくというような流れになります。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"事業者同士のというところになると思うのですけれども、協力体制だったり、あとは、事業者が主体ではなく、区のほうが主体となって情報共有していただいたりですとか、問題の解決を図っていくような、そういった会議は行っていただいているかとは思うのですけれども、その辺、こちら、今出ている課題を見ますと、横断的な視点を持った方が何かアドバイスであったり。","respondent":"永尾高齢者福祉課長","answer":"それで、あと、一般的な情報共有のお話になりますけれども、事業所連絡会というのはその事業所の例えばグループホームだとかケアマネの連絡会とか、そういうものによって複数ありまして、あと、小規模多機能の連絡会というのもありまして、そのそれぞれの同じようなサービス。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"すみません、ちょっとあともう一点、別の質問になってしまうのですけれども、先ほどもありました障害者の方の高齢化による移行の課題なのですけれども、現在は個別のケースで解決されているというところでなのですが、先を見据えて、今現在、解決策を考えていらっしゃる、検討していらっしゃる段階かと思うのですけれども、その辺の見通しも詳しくお聞かせいただけたらなと思います。","respondent":"中山障害者福祉課長","answer":"ですので、個別のケースに合わせながらということで対応はしているところではあるんですが、例えば福栄会にしても、品川総合福祉センターにいたしましても、障害のサービスだけではなく、高齢の部門も持っておりますので、法人の中でもそういった話を積極的にしてもらうことで。","id":"exchange-021"}]},{"id":"topic-02","title":"後期高齢者医療制度保険料","agenda":"後期高齢者医療制度保険料","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"（９）の財政安定化基金の活用について、国の方針が不明なため、今回まだ見込んでいないということなのですけれども、これは国が決めないと、区として活用できないのかということをちょっと確認したいと思います。（１０）のところで、激変緩和措置の詳細が不明だということなのですけれども、今、現行どおりでありますが、このままやっていく考えなのか、お聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"それと、所得が一定額のということで、保険料軽減処置に対する激変緩和措置ですが、これは国の軽減、いわゆる低所得者に対する均等割りの保険料軽減ということでされている部分と、東京都の広域連合が行っている部分、２つございまして、現時点では不明と申し上げましたのは。","id":"exchange-022"},{"speaker":"のだて委員","kind":"確認","question":"２ページ目のところで、昨年と今年の分のところで財政安定化基金拠出というのが０円ということになっておりますけれども、これまで、１８億円とか２０億円、積み立ててきたものだと思うのですが、この前回のときにやらなかった理由と、この今残っている金額ですね。ここに６６億円とありますが、そのまま変わってないのかという確認をお願いします。","respondent":"高森国保医療年金課長","answer":"そういうふうなのも勘案しながら、平成２８年度、平成２９年度の保険料率を算定していくわけなので、その流れの中で、ここで申し上げている安定化基金の拠出金をどうするかというところも、広域連合の議会の中で議論をいただいて決定するという形になっていますので。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"この決定は広域連合のところで決まるということでしたけれども、やはり今回も値上げということで、前回はやはりここの拠出金のところを切り崩して、前年のその前の期のときよりも安くすることができたということがありますので、やはりこういった拠出していっても、今後、続いていくのだろうと、共産党としては反対をしておりますが、思いますので、やはり軽減していくためにも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ということは、今はその積み増しがされていないということで、財政安定化基金というのは６６億円しかないということなのか、そして、その６６億円というのは医療費のかかるだろうという医療費の２％ぐらい分はこの財政安定化基金で、留保しておくということが必要だというふうなことで前の課長が説明されているのですけれども、それで６６億円をとって。","respondent":"高森国保医療年金課長","answer":"この財政安定化基金なのですけれども、財政の安定化に資するために都道府県に設置されたということで、国と都道府県と広域連合が３分の１ずつ拠出して資金を蓄えて積み立ててきている状況になっていまして、現在、委員がおっしゃったように、約６６億円が平成２６年度。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"というところから考えたら、私は前回も０円ではなくて、そういうことの保険料充当にずっとこれだけ充ててきたということを考えれば、本来であれば、積み増すべきものではなかったかなというふうな思いがしているのですけれども、そこの財政安定化基金の拠出をするという考え方は国のほうでどれだけというふうなことが示されて。","respondent":"高森国保医療年金課長","answer":"積み立てについては、国と都道府県というのと、あと、広域連合ということで３分の１ずつですか、拠出する形になっていますので、国の予算でもって幾らという形で総額が決まりまして、それが４７都道府県それぞれに広域連合がありますので、そこに分配される。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということになると、今回、その平成２８年度、平成２９年度の保険料を引き下げるために充てる財政安定化基金というのは、あるのか、ここにはその方針が不明なため、見込んでいないということで書いてあるのですけれども、それが出れば、あるのかどうなのかということについてちょっとお聞かせいただけますでしょうか。","respondent":"高森国保医療年金課長","answer":"申しわけございません。こちらの４項目の特別対策で、財政安定化基金に拠出する１１億円については、積み増しをするというふうな見込みで立てているというふうに聞いてあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"わかりました。理解しました。ということは、財政安定化基金は３３億円だけが２年間で積み増しされるということで、その６６億円を確保するとしたら、３３億円分だけが保険料引き下げに、今までの考え方からすれば、充当できるということで考えていいのでしょうか。","respondent":"高森国保医療年金課長","answer":"この間、積み立てしたり、取り崩したり、いろいろしていますけれども、可能といえば、９９億円が取り崩し可能額になりますけれども、それをするかどうかというのは議会の判断。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。品川でちょっと特例軽減を受けている方が何％ぐらいいるのかということがわかったら教えていただきたいのと。それから、あとは、これはぜひ、１年先延ばしというのではなくて、これをやめてほしいということで、課長会などでもそういうふうな声というのは出していないのか、ぜひとも出していただきたいと思うのですけれども、その点についてもお聞かせください。","respondent":"高森国保医療年金課長","answer":"必要に応じて、課長会、または、部長会等で広域連合のほうには意見という形でお出ししておりますので、ここの今、委員からご指摘がありました保険料の軽減については、国の制度と東京都広域連合独自の制度ということで、二重構造になった形で軽減処置が実はされていまして。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"確かに委員、おっしゃるとおり、後期高齢者医療についてはこの軽減を対象になっている方、数多くいらっしゃるということも理解しておりますので、機会あるごとに、東京都広域連合に対してしっかりした形、また、東京都に対しても軽減は継続するというふうな形で今。","id":"exchange-030"},{"speaker":"石田委員","kind":"確認","question":"１つだけ教えてください。政令どおりで来たときに、今、特別対策を講じているわけですけれども、特別対策というのは、もちろんできる既定だと思うのだけれども、それの確認だけ教えてください。","respondent":"高森国保医療年金課長","answer":"ほかの４６道府県はやっておりませんで、東京都だけが行っているということで、できる既定です。","id":"exchange-031"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう形の中で、みんなこれから高齢者がこれだけ増えてくるとなると、この今の公費が５割で若年者の保険料も４割だなんていうのも入っているということを考えるのであれば、やはりそれはよくよく高齢者の優遇制度、これだけではなくて、やはりそこら辺のところは低所得者の人のそれはしっかり見るところは見るにしても、やはりそこら辺の高齢者の優遇制度については、これだけではなくて。","respondent":"高森国保医療年金課長","answer":"２３区の課長会でも、ここの部分については、２３区としてはそんなに大きなぶれはなくて、継続というふうな形で要望していこうというふうな流れになっているのですけれども、これは東京都というと市区町村もありますので、市区町村は市区町村のまた考え方もありますから。","id":"exchange-032"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"特にあれなんですけれども、この由布市の「健康づくり教室」、「メタボが気になる方」という部分で、たまたま１０月２７日が第１回目ということで、ここは視察とかできないでしょうね、おそらく、どういう形でやられているかとかというのは。たまたま２７日です。それだけです。僕も気になっていますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/866699?Template=document&Id=3428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":70340,"voices":99}},{"id":"h27-20150925-8","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"最初に、(1)の平成２６年度指定管理者による管理に対するモニタリング・評価","agenda":"最初に、(1)の平成２６年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"説明ありがとうございました。わかりました。住宅のほうで少し確認だけさせてください。表の中で、滞納者１件当たりの対応回数という欄がありましたが、これがファミーユの西五反田ともう一つ全体的な別の場所で、かなり２.７８から０.６７という数字が違うのですけど、この辺の理由は何か原因だけ教えてください。","respondent":"矢木住宅担当課長","answer":"一つには、ファミーユ西五反田西館・東館はタワー型の建物でございまして、管理センターからすぐに行けるということと、回数は０.６７回と少ないのですが、この宅建管理センターのほうはその他の電話呼び出し等々の形で対応に努めているというふうに聞いております。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"意見","question":"一応、これ面談した回数と、片方は電話で、電話だから面談はしていないが請求していると。収納率は上がっているから心配ないけど、ちょっと滞納が逆に言うと甘いのではないかというふうに見えてしまったので、例えば電話で督促しているものは督促しているものに載っかったほうが、この資料としてはわかりやすく同じような数字が出てくるのではないかと、ちょっとそれだけ気になったので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"駐輪場２３カ所、大崎を含め２６カ所ですか、その周りの状況も含めた形での放置自転車のあり方、それもやはり１つの指定管理者の中で考えていただく部分、ただ単にそこの管理だけではなくて、その周りのところも。そういう意味での次への課題の展開までの役割を担っていただくのもいいのではないかと思うのですが、その辺、今後の放置自転車を含めた形での考え方というのがありましたら教えてください。","respondent":"田口交通安全担当課長","answer":"この辺の指導も今後徹底していきたいと考えております。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ管理という意味では、そこだけ管理をきっちりとしていただくというのが基本になっているところなのですが、やはり今後の展開をどうしていくかというのは、非常に参考になるご意見等を実際持っていると思うので、ぜひとも今後そういうところも含めての業務をちょっと考えていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"よく区民相談でいただく話なので、この際改めて７,２６０台ありますけれども、そういうのが設置可能な、丸めた数字かもしれませんけれども、その台数ですかと、あとは主な場所とかですか、今後そういう自転車というのはどんどん増えていくと私は思っていますので、先ほど対応の方針のところでもラックの変更とか、そもそもの駐輪場を増加していくという方針がありますけれども。","respondent":"田口交通安全担当課長","answer":"それとチャイルドシートの関係ですが、細かい統計いうのはまだとっていないのですが、今年、大森駅の水神公園で調査をかけたところ、６４０台中５４台、パーセンテージにしますと全体の８.４％、ただ、これはやはり今後増えていくというのも考えられますので。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"利用率については全体としては適切というご判断であるということと、駐輪場そのものだけの運営で、どういう損益分岐点、表とかをつくられてどういうくくりになっているのか、そこまで詳細はわかりませんけれど、今、ご答弁いただいたように、委託だとか、その全体の事業を含めて損益分岐点を出しているのだと思うのですけれども、その中で適切に問題なく運営されているのであれば、長年。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"駐輪場のほうからなのですけれども、恐らく大崎のシンクパークの駐輪場を利用したりするのですが、この大崎地区を指定管理ではなく、除いた理由というのをお伺いしたいのですけれども、あとそれと除かれた大崎地区というのは、現在、指定管理者ではないということですが、どのような運営形態をしているのかもちょっと教えていただきたいと思います。その前は何が原因だったのかということ。","respondent":"田口交通安全担当課長","answer":"先ほど言いましたけれども、撤去活動、指導、啓発、その他いろいろな対策を講じながら、できるだけ駐輪場を利用していただくという考えです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"その辺の危惧の点はどのように解消されるのか。そこについてどのように考えているのかというのを１点伺います。あるいは学割などそういった細かな利用料金の設定導入は私は必要だと思うのですけれども、以前の委員会で出されたこの評価結果というのの検討がどうなったのか。その辺もあわせてお願いしたいと思います。","respondent":"田口交通安全担当課長","answer":"やはり受益者負担という考え方から、現行のままというふうに考えてありますが、これを無料化することでちょっと１点、問題点というのが、今１００％を超えている駐輪場がありますが、これを無料化することによって。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、そこで、長時間とめるのではなく、身近なところに駐輪場があって用事を済ませてというところであれば、そういったところを利用していただいて放置自転車も減らせるというところもあると思いますので、ぜひ一時的な利用無料というところを駐輪場の増設というのもあわせて、ぜひこれから検討していただきたいというのが１つです。","respondent":"矢木住宅担当課長","answer":"３点目、退去者の滞納使用料につきましては、新たな収納方法ですが、こちら、まず収納といたしましては、今まで裁判などでお願いしていなかった弁護士の活用ですとか、または、余りに古い債権につきましては、収納という形とは逆になりますが。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"それと、その設定の根拠の理由をお伺いしたいというのが１つです。先ほどもあったのですけれども、宅建のほうのこちらは１回を下回っているということは、全ての滞納者に対して一度も会えていない方もいるということだと思うのです。改善はしてきているのですごく評価はしてはいるのですが、今の現状での、場合によっては１人につき一度も対応できない現状についての課題というのはどこにあるのか。","respondent":"矢木住宅担当課長","answer":"２点目、対応回数にリンクして収納率も上がっているということで、きめ細かい対応が必要なのではないかというご意見につきましては、委員ご指摘のとおり、そのように対応を、例えば宅建センターの場合ですと１回目で納付書をお渡しして。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"会計上の関係なのですけれども、指定管理の場合に例えば駐輪場でいったときに、管理運営委託費は当然区の歳出になってきて、この使用料はどちらへ入ってくるのでしたか。使用料として入るのでしたか。そこの確認が１点と。その辺で、公設と民設の部分というのはどう考えたらいいのか、考え方を教えてください。","respondent":"田口交通安全担当課長、安井土木管理課長、松代防災まちづくり部長","answer":"使用料については、うちのほうの歳入になります。使用料は使用料で利用料金制はとっておりませんので、使用料として入るという。利用料金制と相殺するようなことはやっておりません。そういった中では、今、２４駅ほどつくっているのですけれども、非常に利用率が高くて定期利用等も含めてお待ちになっている方が多い駅もあれば。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後にちょっと話のあった、大きい自転車の台数を減らすという、自分も結構自転車大きな感じなので置くのに苦労するのですけれども、今、お話があった大森のこれからの駐輪場、先ほど、つる委員からもお話がありましたけれども、電動だとか、子供の乗っている、あれの対応もうまくお願いしたいということで、それをお願いして要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の防災緑化助成の改定","agenda":"の防災緑化助成の改定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"具体的に施工してみると、こういった一応上限は設定しているけれども、大体この上限金額の中で収まるということの理解でよろしいのかということが１つ聞きたいのと。それと、従来のやっていたこの金額助成の制度がありましたけれども、今回、旗の台４丁目で行ったモデル事業を踏まえて、これはリニューアルして全部、防災緑化助成制度になるという理解でよろしいのか。その点をお伺いします。","respondent":"多並公園課長","answer":"もう一つの従来のところとの話ですけれども、生垣助成というのはもともと昭和６３年から進めてきたところなのですけれども、その中で東日本大震災が起こった後に、やはり緑化の中でも防災性を向上させることができないかということで、まちづくりの計画をつくった中で。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"そういうことですと、今回、この改定したものを全区域に適用するという理解でよろしいですか。済みません、そういうことでしたか、失礼しました。ですから、やはり地震が起こったときにどうなるのかという心配もあるのです。そういったところが対象外になっていたりとか、若干ちぐはぐな印象を受けるのですけれども、対象地域の設定における区の考え方をもう少しお伺いしたいと考えています。","respondent":"多並公園課長","answer":"木密地域、この適用の範囲の考え方ですけれども、実はこれは木密整備推進課とよく相談をして考えた話なのですけれども、要するに、現在、この区の中で行っている、先ほど資料の左の真ん中の図の上のところにありますけれども。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"その地域設定についてですけれども、私自身はやはり住んでいて大崎３丁目あたりは、本当にこの事業があったら、さらに防災性が向上するのではないかというような実感をしているところなのですけれども、例えば大崎３丁目を追加するですとか、そういったもっと地域を住民の方から、「ああ、こういった事業があったら助かるわ」とか、「実際ブロック塀多いわ」というようなところで。","respondent":"松代防災まちづくり部長","answer":"その後、今、意見がありましたように、今後の展開として、そういったものを考える時期になれば、計画的にやるべきものだというふうに思っておりますけれども、まずは、ここに集中して防災化重点施策ということで。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"防災のためにやっているのだと、こういうこともやっていますと。本当に大崎３丁目の地域の防災性を向上させたいというのであれば、そういった道路ではなく、ほかにやれること、徹底して感震ブレーカーもそうです。本当に本気になってここで具体化していくということをしていかないと、私は到底防災のための巨大道路なども理解が進まないのではないかというふうな意見を述べまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"先ほど周知する上で個別訪問してなるべく細かくということなのですが、ここのどこを、ブルーのところを全部するのですか。それとも優先順位か何か、そういうことはどこまでやろうとしているのかを。","respondent":"多並公園課長","answer":"今回の周知、新しくやるというのは、こういうのはなかなかご理解いただけないところもありますので、前回も結局旗の台４丁目というのは狭い地区でしたけれども、全部で８０軒ぐらいたしかあったと思うのですけれども、それも個別で回りながらやっていって周知を図って。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"例えばそこは多分やらないと思います、はっきり言って。ブロック塀だと思います。なので、やってほしいところというのがある程度特定されているのかと。だけど、該当者というのはそんなにいるのですかと思ってしまうのです。職員の方も個別訪問されていくのでしょうけれども、無駄ではないですかと思うのです。それはどういうふうに考えられているのですか。","respondent":"多並公園課長","answer":"１点目のこの事業のスキームのお話を、きちんと説明すればよかったのですけれども、沿道の方でいわゆる接道部緑化と言いまして、道に接道するお宅の接道部分の緑化のブロック塀の話です。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"だから、もうわかっていると思います。ここをやってほしいという区側として、ここの沿道のこのお宅、誰々さんのお宅をやってほしいのだと大体わかると思うのです。非常に大きな誤解、対象なのでしょうけれども、でも、本当にやってほしいことにつながっていかないのではないか。変な方向に行っていませんかというふうな可能性もありますということでちょっと気になったのでいかがでしょうか。","respondent":"多並公園課長","answer":"実は旗の台４丁目の地元でいろいろお話ししたときにも同じ話がありまして、それでやはりブロック塀の中でも危険なブロック塀の箇所を個別に回ろうということで、先ほど私が個別に１戸１戸ご説明して、例えばここをやる場合にはこういう考え方になるのですと。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、「あそこ危ない」と他の方から、そのお宅はそういう気持ちが全然ないのに、結局は周りから「あそこ危ないのにこういう制度があるのに何でやらないの」という、責めるような状況にもなりかねない部分があるので、ですから、この説明の仕方、町会に入られるときにもぜひその辺はおわかりになっていると思いますが、気をつけていただきたいというふうに要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"お疲れさまでございました。基本的なことをまず最初に伺いたいのですが、いろいろな段階での発令があるのですけれども、避難準備というのと避難勧告、今回、避難勧告は区では、初ですが、さらに避難指示というのがあるわけなのですけれども、それぞれの経緯を改めてご説明いただければと思います。それと、避難所なのですが、実際どんな体制だったのか、改めてこの場でもお伺いしたいと思います。","respondent":"鈴木（和）建築課長","answer":"内容によっては、長時間対応もありますので、基本的には交替要員も含めて適正な職員の配置を行っていくというようなところが実情です。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"避難所のお話ですけれども、避難ということですが、一晩明かした方が２名いらっしゃったと思うのですけれども、食事はちょっと考え方としてはどうなのかというのをお伺いしたいと思います。そういった体制というのはどうなのかというのを避難所関連でまずお伺いします。ですから、勧告の段階での行政の役割というのは今、どういったものが定められているのか、そこをお伺いします。","respondent":"鈴木（誠）防災課長、鈴木（和）建築課長","answer":"ただし、今回の土砂災害に関しましては６地区を指定しまして、直接、その避難勧告等が対象となる世帯には個別の説明をしていますので、広域にわたる情報伝達、例えば屋外にある防災無線のような伝達方法は、今回は使用しておりません。今回、勧告まで出したわけですけれども、勧告の意味合いについても、先ほど防災課長から説明させていただきましたけれども、個別に説明会を開いて避難指示あるいは避難準備情報、勧告のいろいろ、その場でも質問がございましたが。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"それぞれご答弁ありがとうあります。もう一つ、今回、勧告の対象は２００世帯ではないかと思うのですけれども、実際避難所に避難したのは中学生の方を含む３人だったということです。避難所に避難した方が３人にとどまったという要因ですが、これはどのように区としてはお考えなのか。避難したくても避難できなかったと考えていらっしゃるのか。その辺はどうなのかというのをちょっとお伺いしたいと思います。","respondent":"鈴木（和）建築課長","answer":"やはり、自主的に判断をされて、自宅にとどまったという方が非常に多かったのではないかというふうに区としては考えているところですが、避難の要援護の方等の情報も区としてはつかんでおりますので、今後。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"多分わからないと思うのですが、これから追跡調査をしていく必要があるのではないかというふうに私は思うのですが、それはいかがかということをお伺いしたので、もう一度お答えいただきたいと思います。私は、お話を聞いて、この方のお尋ねはもっともだと思ったのですけれども、品川区としてはこの方のお尋ねに対してどのような回答をお持ちなのか、あわせてお伺いします。","respondent":"松代防災まちづくり部長","answer":"防災課長、建築課長、それぞれに任にあたったものが答弁させていただいたものです。我々としては、常々申し上げているように、いかに最新の情報を区民の方にお知らせするか、それがまず重要なことだと考えています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは最低限必要ではないかと思うのですが、そこに対してのご見解をぜひいただきたいというのと。それと、先ほどのご説明の中で、避難指示が出たときには、品川区の職員の方々が１軒１軒訪問して避難のお手伝いをするというような話もありました。ですから、勧告の段階でやはり必要だというふうになれば、品川区がそういった対応をすることもあるのかどうか、そこをお伺いします。","respondent":"松代防災まちづくり部長","answer":"品川区としては本当に初めての体験として受けとめて、品川区にそういったことが起きた場合どうすればいいかということで考えて、いち早くこの３年間、低地部分の被害を受けるであろう地区の方々に。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"そのほかと言いますか違う角度からの質問になりますけれども。私の質問する権利を奪うのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"はい、ありがとうあります。以前、２年前ほどでしょうか、南品川のほうで不発弾の処理がありました。ですから、ときには一緒に連れ出したりとか、そういうこともしているわけです。私は場合によってはそういったこともしているわけですから、あのときの対応というのは、ぜひ教訓にしていく、実際の姿勢としての教訓にしていくべきだと思うのですけれども、最後にいかがでしょうか。","respondent":"鈴木（誠）防災課長","answer":"避難勧告等の基準についてのご質問ですが、本日、お話しさせていただいていますのは土砂災害に関する発令基準です。今、参考に出されました不発弾は、災害というか危機管理、事象が違いますので、同じ考え方で行動できるものではございません。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"係の皆さま、大変ご苦労さまでした。その中で心配なのは、現場へ出ている方の対応、体の心配です。水害では川の心配ですが、それもありますので十分注意していただきたいということをこれからも要望としておきます。１点だけ、この資料の中で、品川学園に中学生、９年生の方が行っている。その関係で９年生、１人来ていると思うのですけれども、これはご自分で来ているのですか、その辺のところだけ。","respondent":"鈴木（誠）防災課長","answer":"学校のほうは休校ですので、学校としての対応というよりは避難所のほうで一時的に滞在をしていただいたという状況で、お昼ごろには自分の意思でご自宅に帰られたという状況です。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"意見","question":"逆に言うと、この中で学校を全小中学校、休校にしたというのを一緒しておけば、せっかくそれで対応しているということももっとわかりやすくなるのではないかということで、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ハザードマップで示されているかなりの降水量のときのマップだと思うのですが、それと、その被害と今回の被害とではどのぐらい、例えばあと少し降水量が多くなったらああいうふうになってしまうという状況だったのか、その辺はいかがなのですか。あそこまではまだ余裕があるというのは変な言い方ですけれども、どの辺の危険度レベルだったのかと思うのですが、その辺はいかがですか。","respondent":"鈴木（誠）防災課長","answer":"今回、台風１８号への対応で、本部でさまざまな対応をしましたけれども、実は２つありまして、今、ご質問でいろいろご説明した土砂災害と、もう一つは今のご質問いただいた浸水被害です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"防災ハンドブックも配布をしているはずなのですけれども、やはり見ていないのです。高台だと思っていても目黒川沿いの近くだったので、逆に浸水被害を起こすというような地域だってあるのだから、そういうこともあるので、今後、啓発活動をする上では、その点も含めて皆さまに考えていただけるような工夫をしていただきたいと思うのですけれどもいかがでしょうか。","respondent":"鈴木（誠）防災課長","answer":"そういう意味では、ご質問いただいたように、災害の種類ごと、また、区からの情報提供の内容ごとに適切な判断をしていただくというのが基本になるということは、区としても認識をしております。","id":"exchange-032"},{"speaker":"つる委員","kind":"確認","question":"私は、この９年生の避難について、どういう状況だったのかというのを先ほど鈴木委員が確認していただいて、それは理解したのですけれども、また、個別に教育委員会のほうにはそれ以外の部分の課題を確認したいと思うのですけれども、その上でほかの２名の避難者ですが、それぞれ１名、１名で単独でお一人で避難所に来られたとは思うのですが、その受入体制、動線と言うのでしょうか。","respondent":"鈴木（和）建築課長","answer":"そのときの雨の状況ですが、私の認識ですと、やはり降ったりやんだりと、時にちょっと強く降るような状況でございまして、大雨が１時間、２時間集中して長時間にわたって降っているような状況ではございませんでした。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう部分でそれはそれでしっかりと鋭意やっていただきたいというところと、今、申し上げたその避難の判断の部分ですが、家にとどまっていたことによって命が守られたということも当然あるわけですから、非常にその辺の判断の自己責任のところもあるのでしょうけれども、本当にさまざまな、先ほど情報提供という話もありましたけれども、そういったところも含めて区民の方に、また対象地域の方。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、避難所の運営についてですけれども、日ごろ地域で維持して育まれている地域コミュニティを避難所の運営に生かしていくということは大事なことだと思いますけれども、運営体制のところで、住民主体の避難所の自主運営管理の推進と書いてありますけれども、その心といいますか、その意味するところというのが何なのか、教えていただきたいと思います。","respondent":"鈴木（誠）防災課長","answer":"それと、これは先ほど申し上げましたように、一時的な避難のときではなくて、その後の長期、１カ月や２カ月にわたる避難生活のこともありますので、やはり地域のコミュニティが、できるだけ同じ状態のメンバーなり、関係性で集まっていただいて、ご自分たちで運営されるのが。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"その避難所運営のことでもう少しお伺いしたいのですけれども、資料の中で３ページですか、通常時は避難所連絡会議を開いて、役割分担について検討項目の中で検討しているということなのですが、具体的にはこの役割分担というのはどんな感じなのか。避難所によって、その内容というものが違うものなのか、そこをお伺いしたいのと。","respondent":"鈴木（誠）防災課長","answer":"１点目の避難者が倒壊等で増えるのではないかということで、都はその辺、どういう算出をしているかというご質問ですが、これは都のほうで検討委員会や専門家が入ったプロジェクトチームでさまざまなシミュレーションを行いまして、例えば倒壊の棟数であったり。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういった非常時ですから大変混乱するところで、日ごろから行政にあたられている区の職員の方もやはり視野といいますか、経験といいますか、そういったものがすごく重要になってくると思いますので、ぜひ積極的な役割も果たしていただきたいと思うのですけれども、ちょっと答弁の中で役割分担というところなのですけれども、私が伺ったのは、実際に避難所が開設された後に。","respondent":"鈴木（誠）防災課長、鈴木（和）建築課長","answer":"ただし、どちらについても建築基準法なり、いろいろなさまざまな法律で、防災上だけでなく安全確保というのは義務づけられて、それに対応するものが実際に建物として活用されているところでありますので、高層マンションが増えて。さらに国では、東日本大震災後あるいは南海トラフの地震の発生の危険性を受けて、現在、さらに長周期地震動に対する対策試案を検討中でございまして、そういったところを注視しながら、今後。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうことを置き去りにしてどんどんどんどんつくっていくというのは、一度つくったらそう簡単にはこれは５０年、１００年と壊せるものではありませんし、そこにあり続けるものですから、私は行政みずからがそうした防災に脆弱な基盤というのを広げていってしまうのではないか、こういうまちづくりをするということには危惧がありますので、ぜひ、そこは国の法律の規定整備に安心しないで。","respondent":"鈴木（誠）防災課長","answer":"ただし、やはり限られた施設、生活のための施設ではない学校で避難所生活をしますので、そのために先ほど説明をしました二次避難所や福祉避難所、こういうものをあわせてさまざまな方への対応を準備しています。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"今のもう少し具体的に、二次避難所ですとか、福祉避難所で、例えば聴覚障害の方、視覚障害の方などへの設備的な配慮というのは何か今の時点でされているのか。実際そこに行ったとしても、例えば目でファクスですとか、あるいは聴覚障害者にはいろいろな配慮が、手話通訳の方とか、必要かもしれないですし、そうした配慮が必要だと思うのですが、現時点ではどんな体制があるのかをお伺いします。","respondent":"鈴木（誠）防災課長","answer":"特に障害のある方への対応というご質問だと思いますが、障害のある方、特に、通常福祉施設等をご利用いただいている方につきましては、区のほうの福祉避難所に位置づけておりますのが区内６つの社会福祉法人の１３施設です。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問・要望","question":"最後に、防災設備の点なのですけれども、非常用発電装置が軽油１５０リットルで非常照明７２時間ということなのですけれども、要は３日間ということですけれども、やはり大規模震災の場合は停電がまず考えられると思いますので、こうした軽油を燃料とした発電装置ですと、ライフライン、道路とかが遮断されて軽油が３日過ぎたら入ってこないという恐れもあるので、ぜひとも軽油に頼らない。","respondent":"鈴木（誠）防災課長","answer":"例えば救護所があるところでは医療の対応のみであるとか、要配慮、配慮が必要な方への部屋への優先だとかというのはどうしても出てきてしまいますので、燃料のほうは燃料の組合と協定を結んで確保はしておりますが、最低限のものだということで考えていただければと思います。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"マンションの支援のほうはマンション管理組合等から要請があれば、区としてはサポートとかやってくれるのかということと、また、緊急用発電装置についてなのですけれども、４日後には大丈夫ということなのですけれども、今、皆さまスマートフォンとか持っていらっしゃる方がいるので、そういった発電装置とかもぜひご用意していただきたいのですけれども、私の意見としてです。","respondent":"鈴木（誠）防災課長","answer":"どちらも区のほうではできる限りの体制を組んで、今、対応しています。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"どういうときに、一時集合場所になって、どういうときに避難所に行くべきなのかということ。どこでもいいわけです。一生懸命やっているところもあれば、初めてやったというところもあれば、まちまちだったと思うのですけれども、その反省点を、今回少しやっていますけれども、反省点をどういうふうに、今回に生かそうとしているのかということをまずお聞きしたいと思います。","respondent":"鈴木（誠）防災課長","answer":"昨年は残念ながら、衆議院選挙の関係で中止になりましたが、今年度はさらに昨年の訓練メニューに加えて、医療関係の連携だとか、警察署、関係機関、そういうところも加わっていただくというのが拡大、充実したところと、訓練の実施会場となる学校ですが。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"医療体制を今度入れるということなのですけれども、地域センターごとに１カ所ということなのですが、これも今回ぜひ入れていただきたいのは、三十何カ所ありますけれども、基本は地域センター管轄の１カ所の避難所にということなので、そうなると、どういう人が来たときにどこにどういうふうに搬送したらいいのかという、理想は、避難所ごとにそういうのがあればいいと思うのです。最後に備蓄です。","respondent":"鈴木（誠）防災課長","answer":"ご質問にあった軽傷の方、中傷の方、重傷の方、こういう方の対応というのは、先ほど申し上げた拠点病院や連携病院、大きな区内の病院の前にトリアージ用の緊急医療救護所を設置しまして、そこでトリアージをして、目の前の大きな病院で見るのか。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ペットの対応です。ペットの対応はどうなっていますでしょうか。","respondent":"鈴木（誠）防災課長","answer":"それともう一つ、避難所単位で対応し切れない場合には、区のほうで例えば合同の飼育場所を用意するなり、それも難しい場合には、都のほうでそのためのセンターを設置するという役割分担になっておりますので、そういうさまざまな方法。","id":"exchange-044"}]},{"id":"topic-03","title":"の順番では、行政視察でありますが、本件は、藤田都市環境部長のみお残りいただき、行政視察の事前の勉強会を行う予定であります。 よって、順番を変更いたしまして","agenda":"の順番では、行政視察でありますが、本件は、藤田都市環境部長のみお残りいただき、行政視察の事前の勉強会を行う予定であります。 よって、順番を変更いたしまして","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのは、まず、この景観計画の中では、低層住宅市街地と位置づけられているこの池田山の地域なのですけれども、区としてはこの池田山地域の景観の何を評価して残していきたいというふうに思っていらっしゃるのか。ちょっと一般的な資料で説明はあるのですけれども、もう少し池田山地域に引きつけて具体的に伺えればと考えています。","respondent":"中村都市計画課長","answer":"そういった中では、今現在のこの閑静な住宅街のまちなみをできる限り保全をして、良好な環境を保つ。こういったものが景観形成に求める重要な目的というふうに認識をしています。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"この池田山地域なのですけれども、古くから８０年代ですか、この閑静な住宅街、景観、緑と文化を守りたいということで、自主的に池田山環境協定という紳士協定なのですけれども、これを策定したというような過去から、非常にその景観に対しての意識が強い地域なのですけれども、今、区としてはこの池田山環境協定というのを、改めて伺いたいのですけれども、存在はご存知だと思いますけれども。","respondent":"中村都市計画課長","answer":"池田山の環境協定につきましては認識をしています。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"現在、この景観が具体的には超高層のマンション建設ですが、８０メートル級の超高層マンションがこの池田山の入口に計画、建設されている中で、この景観がこのマンションによって壊されたくないというような住民運動が起きている地域です。こうした景観づくりのまちの機運というのは、行政としては積極的に応援して生かしていく姿勢が必要だと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"そういった中では、この景観ですけれども、池田山のこのエリアの中で、そういったところで低層住宅地として指定をされておりますところにつきましては、景観につきましては、外からの見え方ですとか、あるいは閑静な住宅街といった、こういった一定程度の景観のルール。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私はやはり、この地域の景観を本当に守りたいというのであれば、この新たなルールづくりといいますか、これがどうしても不可欠になっていっていると思いますし、マンション、今まだ建設途中ですけれども、そうしたマンションの建築計画に反対運動をしている方々の中にそういう思いが強くあるわけなのですけれども、そうした仕組みづくりという点で、品川区としてはどのようなことが考えられるのか。","respondent":"中村都市計画課長","answer":"こういったものについて、やはり守るべきエリアの外にある建築物の背景について規制をしていくというのは、これは現実的には非常に難しい話なのかというふうに認識をしています。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこまではそういった突出した建物はなかったのです。ですから、私は景観を考える上では、従来にとらわれない支援といいますか、一緒に住民の皆さまの気持ちに寄り添って考えていくという姿勢が大事だということなので、そういうふうに思っているのです。そこをちょっと１つ要望したいのと。その辺の仕組みといいますか、そこをあわせてお伺いしたいと思います。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"例えば１つの選択肢としては地区計画、そういったまちの方々の発議に基づくまちづくりの１つの成果として、地区計画をもって用途地域を変更する。こういったものは可能性としては考えられます。そのために、地域で勉強したいということであれば、自主的なまちづくりの支援というような形で私どもの専門家の派遣の制度等もありますので、そういったものを活用しながら、いろいろご検討していただくというのがいいのかと。","id":"exchange-049"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後とも入れていただきたいと思います。今後のそうした展望はどうお考えなのかをご答弁いただきたいと思います。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、協定があるとされているその範囲、この範囲を多少越えたところについても、事業者あるいは建築主にご案内をしていますので、引き続きそういった情報提供はしてまいりたいと思います。","id":"exchange-050"}]},{"id":"topic-04","title":"都市環境部長に引き続きご同席をいただきまして、予定表の３、行政視察","agenda":"都市環境部長に引き続きご同席をいただきまして、予定表の３、行政視察","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"震災復興のことに関してですが、ちょっと私も復旧と復興というところなのですけれども、いろいろ議論があるところだと思いますので、ぜひ宮古市ではどういうふうにしているのかというのを参考にしながら、本当の意味での住民主体の復興というのはどういうことなのかということを深めていきたいというふうに思いました。もしあれば、部長の問題意識があれば。","respondent":"藤田都市環境部長","answer":"１つは、仙台うみの杜水族館、今回の設置がちょっとこの話がどうつながるかは別な話になってしまうかしれませんけど、もともとマリンピア松島水族館というのが宮城県松島町のほうにございまして、その施設が震災を受けて、もうほぼ使えなくなってしまいまして、その後。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/967161?Template=document&Id=4150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":69075,"voices":136}},{"id":"h27-20150925-9","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件抜き出しています。","topics":[{"id":"topic-01","title":"品川区教育大綱の策定","agenda":"品川区教育大綱の策定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ご説明にあったように、この大綱というのは区長部局で作成をしていくということで、策定の趣旨のところに、首長と教育委員会が協議・調整を尽くし、策定した大綱になるので、主には区長部局のほうで策定をしていると思うのですが、教育委員会がどのようにここのところで協議等を行っているのかを１点教えてください。","respondent":"品川庶務課長","answer":"協議する場ですが、先ほどもご説明にありました総合教育会議です。こちら、区長と教育委員会が、教育のことに関して協議をしていく会議体です。この中で大綱も協議をしていくというものです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"４ページから８ページまで、「大綱の策定にあたって」という資料がついているのですが、これがこれから１０月中旬以降のパブリックコメントに提示される中身なのですか。これだけなのですか。もうちょっとあるのかどうか、その辺を。","respondent":"品川庶務課長","answer":"教育大綱自体は、この資料の表紙の次のページ、１ページとページが表示されている部分から、８ページとある部分までが教育大綱というものになります。ですので、表紙がつくかもしれませんけれども、基本的にはその８ページが今回、パブリックコメントに出されるものです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"１つとても気になるのが、先日の教科書採択のときなんかも、この委員会でいろいろ発言もさせていただいたのですけれども、新しい教育委員会制度に変わっていく中で、今までだったら本当に教育委員会が合議制で全て教育のところを決めていったというところが、私は決して区長部局との懇談を否定するものではないのですが、やはりそこの教育委員会が独立して存在をしている。","respondent":"品川庶務課長","answer":"政治介入等のお話があったと思うのですけれども、当然、総合教育会議等で区長部局と協議しながら決めていくものですので、例えば、区長部局がこの大綱について独自で進めているというものではございませんで、区長部局と教育委員会とで協議しながら進めていくものですので。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多分、これは学校の統廃合に通じる整備のところであると考えていますが、学校の設置や廃止などについては教育委員会の権限で行われるべきものなので、ここに書かれていることがどう影響していくのか。私は、はっきり言って、ちょっと懸念を感じているのです。私は、こういう項目は書いてほしくなかったという思いを持っているのです。これは教育委員会の権限だと思うのですが、見解はいかがでしょうか。","respondent":"品川庶務課長","answer":"そういう国からの通知をもとにしますと、学校の統廃合に関して、これも教育大綱ですから、具体的な内容を記するわけではございません。目標や根本となる方針、こういうものを書くという意味で、このような文章表記で統廃合に関して書いているです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これ、パブリックコメントをとるということなので、いろいろなご意見を十分に聞いていただきたいと考えていますけれども、教育委員長のポストのところも新教育長ということにこれから変わっていくという意味においては、時の政治の流れに左右されない、本当にしっかりと教育を守るために、教育長をはじめ頑張っていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"総合教育会議で話されたということで、教育委員の皆さんからはこれについてどういった意見等が出されたのか、伺いたいと思います。","respondent":"品川庶務課長","answer":"５番目については、文化芸術の振興ですけれども、品川区史を昨年発行しまして、これがすごくいいというお話がありまして、これを活用して、区の身近な歴史を学ぶきっかけにするといいのではないかというようなご意見がありました。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり教育の部分においては、子どもたちの人格形成の場ともなる大事な場ですので、パブリックコメントをやられるというところで、より多くの皆さんに意見を募っていただきたいと思うのですけれども、広報しながわ１０月２１号に掲載されるということですが、そのほかの周知方法があれば教えてください。","respondent":"品川庶務課長","answer":"パブリックコメントというものを出しますので、これ自体が区民全体に周知する方法であるというふうに考えておりますので、基本的にそれ以外の方法については、現在のところは考えていない状況です。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱり教育の分野だけに限らず、パブリックコメントというのは各分野でやられていると思うのですけれども、なかなか本当に少ないもの、数件というものもあるので、そこは本当に皆さんが興味を持っているところだと思うので、自然に集まるというふうには考えず、広くお知らせしていただきたいと思いますけれども、いかがでしょうか。","respondent":"品川庶務課長","answer":"現時点では、パブリックコメントをやって、その後についてはまだどうするかということも決まっておりませんので、まずパブリックコメントで意見を聞くというところで進めていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これを見ると、社会情勢に応じた多様な保育サービスを展開するという、一応、保育サービスや子育てに関しては書いてあるのですけれども、教育環境に関しては「質の高い乳幼児の教育環境の充実を図ります」と書いてあるだけで、具体的な内容があまりないみたいで、あとは初等教育につなぐというようなニュアンスみたいなのですけれども、この辺は、要するに。","respondent":"竹田保育課長","answer":"形になっているものとしては、「のびのび育つしながわっこ」という冊子を作成し、定期的に改訂しながら、保育・教育課程の実践等の検証を行いながら、乳幼児教育の充実を図っておるところです。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"具体的には少し乳幼児における教育というのはどういうことをするかという点をご検討いただければいいと思いますけれども、次に移ります。これは、今の性の乱れに全然触れていないのですよね。そういう性感染症についての、要するに、性に対する正しい認識云々というのはやっぱり健康教育の一環なので、これはぜひ加えたほうがいいのではないかと思いましたが、いかがでしょうか。","respondent":"伊崎子ども育成課長、村尾教育総合支援センター長","answer":"非行を未然に防止する、人とのつながりの中で防止を図っていくという一面は持ってやっているところです。性教育におきましては、現在の学校教育において、小学校、中学校の保健の学習の中で、今、進めているところです。","id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"これは僕の個人的な感想なのですが、それを一つ検討いただきたいのと、それから、一番最後の、品川区の歴史を知ってもらうために、『品川区史２０１４』、僕も読んだのですけれども、非常に重くて、内容があるのでいいと思うのですが、これを活用してもらいたいわけですけれども、具体的にどんなところでどういうふうに活用するかというようなことも少し記載があったほうがいいのではないかと思ったので。","respondent":"品川庶務課長","answer":"ただ、大綱の趣旨が、あまり具体性があるものの表記というよりは、少し大きく、総合的な形で書くというのが趣旨となっておりますので、その辺も踏まえた形で、委員のご意見を参考にしまして、今後また進めていきたいというふうに考えております。","id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今、課長がおっしゃることはよくわかるのですけれども、ところどころ非常に具体的なところがあり、それとの整合性の図り方、よろしく検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこれ、普通だったら１カ月は見てほしいと思うのと、その後の整理というか、せっかくいただいたご意見も活かしていくという意味では、第３回が近すぎると思っているので、やはりこの辺、せっかくやるのだし、苦労して書いたものは活かしていただきたいと区民の皆さんが思うと思うので、その辺、十分配慮していただきたいと思いますが、いかがでしょうか。","respondent":"品川庶務課長","answer":"そういう中で、基本的に２週間という形で、８ページの内容からすれば、適切なパブリックコメントの期間ではないかというふうに考えております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８ページだからこそ意味が深いのかと。いろいろ読み取らなくてはいけない。形はやった、でも、出た意見はどこに活かされたのかというところのご意見もかなり出ていますので、ぜひ今後、いろいろな場面で行われる、条例もありますけれども、中身を変えていく、十分区民の意見が反映できるようなパブコメにしていただきたいと思いますので、今後にぜひ活かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"意見","question":"３つ目は、教育大綱ということなのですけれども、先ほどいろいろご指摘があったように、方針のところで、特に教育の部分の記述が、生涯教育も社会教育と言ってしまえばそれまでなのですけれども、先ほどほかの委員の方がおっしゃっていた、就学前についてもうちょっと記述があったほうがいいということが、随分省略、おそらくたくさんあったのを削ったのだろうと思うのですけれども。","respondent":"品川庶務課長","answer":"２点目ですけれども、８ページ、総合教育会議の表記ということですけれども、多分、見ておわかりになるかと思いますが、総合教育会議の点につきましては、連携・協力という、この部分に含まれているというような考え方です。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。１つだけ、最後の総合教育会議の位置づけについては、ここの中に含まれているというのでしたら、より区民の方に総合教育会議の存在を知っていただくのであれば、何らかの表記があったほうがよいのではないかと思います。特に耳慣れないというか、おそらく多くの方がご存じない形だと思いますので。以上です。要望ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"平成２８年度から平成３０年度の３年間を想定して策定して、その３年間の期間でまた見直しがあって、変化に対応するため定期的に見直しをやっていきますと書いてあるので、その３年間でまた見直しをして、平成３０年度からまた３年間ぐらいで見直しをして、中身が少し変わっていくのか、どういうことなのかというところを教えていただきたいのと、もし検討、検証する際は。","respondent":"品川庶務課長、渋谷指導課長","answer":"長期計画の改訂が３年ごというような形になりますので、長期計画の改訂を踏まえた後で大綱の見直しというようなサイクルになるかと思いますので、今回については３年間という形で考えております。大変説明がわかりにくいかもしれないのですけれども、例えば、学校経営に関して言いますと、法律だとか規則で決まっているからこうこうこういうふうにやらなければいけないという意識から、実際の目の前の子どもを見て。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"見直しはわかりました。意識改革なのですが、まさに子どもたちに教育を教えていくのは先生であって、子どもたちにできるだけ時間をとってあげて、教育の充実をさせていく中で、先生の文言というのがこの教育大綱の基本理念と方針の中に、学校の先生のまさに意識改革とか質の向上というところは書いていないので、その辺はどうお考えかと思って、１点お聞かせください。","respondent":"渋谷指導課長","answer":"品川区の教育改革プラン２１の大きなコンセプトが、先ほどご説明申し上げたとおり、教員の意識改革というところにポイントを当ててきました。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"パブコメを出す意味というか、やりましたということではないと思うので、どういった、ここには青少年とか、就学前とか、地域との関係性とか、生涯学習とか文化芸術となると、学校と教育だけではなくて、まさにいろいろな人たちのかかわりが出てくる中で、いろいろな人の意見というのも中にはあるかと思うので、そういったところも聞ければありがたいと思うのですけれども、その点はどうでしょうか。","respondent":"品川庶務課長","answer":"パブコメについてですけれども、意図するところが、パブコメ以外の説明会か何かというようなところなのかと思うのですが、現在のところは、まず、幅広くパブリックコメントという形で聞いて、その意見等も踏まえて。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"今、品川区のツイッターとかホームページとかいろいろ、ネット環境も充実してきた中で、費用対効果でどこまで回って周知していくかというのも大変だと思うので、割と効果、効率のいい周知の仕方というのも検討していただければと思って、質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"浅野委員","kind":"質問","question":"今回、大綱の策定にあたってということで、パブコメを行うということで、パブリックコメント、毎回パブコメの話なのだけれども、私は言わせていただいているのですが、８ページというのは、これがそのまま出てくるものというようなイメージで聞いたのですけれども、本当にこれが出るのかというのが気になったので、そこについて何点か質問したいのですけれども、生涯学習の充実のところですが、例えば。","respondent":"品川庶務課長","answer":"そういう難しい、区の職員とか、割と区政のことをわかっている方についてはわかる言葉でも、一般的にパブコメに出すとわからないのではないかという用語についてですけれども、その辺は、パブリックコメントを出すにあたってどうしていくかは。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"確かにこれだけの文章では、読むと大層な量ですから、それを理解するというと、かなり時間もかかるし、好きな人は読まれて、また、回答もされると思うのですけれども、やはり一歩、障害と言ったら悪いけれども、わからない部分というのも多分あると思うのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"伊藤副委員長","kind":"確認","question":"大綱の策定の経費はどこのお金を使っていらっしゃるか。国からお金が出ているのでしょうかという確認をまずお願いします。","respondent":"品川庶務課長","answer":"区費で作成するというように聞いてあります。","id":"exchange-023"},{"speaker":"伊藤副委員長","kind":"質問","question":"それぞれの、例えば、教育委員会の教育目標・基本方針、プラン２１があって、子ども・子育て計画となって、具体的なところは、この計画がそこをカバーできているのですよ。だけれども、そこにわざわざ大綱をつくっていくメリットというのは、それは品川区としてどう考えているのでしょうかという点をお願いしたいのです。","respondent":"品川庶務課長","answer":"大綱をつくるメリットですけれども、これにつきましては、やはり自治体の首長が教育行政に関して、一つのこういった考え方というか、そういうことを区民に示すというところの部分についてが非常にメリットになるところではないかというふうに考えてあります。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問","question":"そういうふうに考えていくと、全国の各地方自治体の特色が多分あるわけです、地域や伝統や文化というふうに。そうすると、例えば、品川区では、６ページの下に文化芸術の振興とかろうじて出ているけれども、もしそういったことであるならば、品川区独自のさまざまな文化や芸術をもっと前面に押し出すべきではないですか。いかがですか。","respondent":"品川庶務課長","answer":"今後、また大綱のほうをいろいろ、パブリックコメント等も踏まえて、手を加えていくような状況です。今、委員がお話ししたご意見も非常に踏まえた形で、大綱のほうは策定していく形をとりたいというふうに考えております。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"意見","question":"その中で唯一可能性があるとするならば、やっぱり品川区独自の特色を出していきたいということであるならば、ほかの自治体にはない取り組みがあって、特色があって、歴史や伝統があるから、それを教育大綱の中に展開していって、教育だから、教育に十分展開できるような大綱をつくっていくことがメリットに近づいていくような気がするので、十分に検討していっていただきますようにお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-02","title":"特別支援教室","agenda":"特別支援教室","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"幾つか具体的にわからない点があったのでご説明をお願いしたいと思うのですけれども、最初は新しい訪問指導の方法ということで、３校と４校に分かれているのですが、これは数がこのくらいだということで分かれたのかもしれないのですが、これが３校と４校にした何か根拠とか考え方とかあるのでしょうか。ただ単純に割り切っただけなのか。","respondent":"村尾教育総合支援センター長","answer":"その次に、月曜日から金曜日まで、週１日と考えたときに、自分の学校を入れるとマックスで５校になるので、４校が一番大きい学校になります。距離的なものを考えて、４校または３校というふうにグループ分けをいたしました。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほどのセンター長のご説明だと、週に１回ということだったので、３校を担当しているところというのは、１日余るわけですよね。それは例えば、余分に行くとか何か対応されるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"おっしゃるとおり、３校のところは１日あきますので、例えば、第四日野小学校であれば、第三日野小学校に２回行くとか、その辺はいろいろ形としては臨機応変に活用できるかというふうに考えています。","id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それと、あと、都のほうからも臨床発達心理士が訪問するとか、非常勤の専門員がいろいろ雑務をするとかいうようなご説明があったのですけれども、そうすると、これ、実際、訪問指導教員と、例えば、その辺の、都から来た人と品川区のほうの職員との連携とか役割分担とかというのはスムーズに進むのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"これについては、今後、都のほうから年１０回巡回してくる臨床発達心理士、それと巡回相談とどのような形で子どもたちの情報交換ができるかどうか、または、それぞれの役割分担等については、今まさに検討し、より効果的な活用ができるように進めているところです。","id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それと、あと、裏面の特別支援教室の利用手続きところで、特別支援教室利用不可の判断ということが書いてあるのですけれども、例えば、不可の判断というのは具体的にどういう事例で不可ということになるのですか。","respondent":"村尾教育総合支援センター長","answer":"就学相談なのですが、実際にそれぞれ各家庭のほうで就学支援ファイル等を書いていただき、就学相談においてまず子どもの行動観察、それから、保護者のみになりますけれども医師による面談、そして、保護者等に、今の校長と、また、特別支援教育係等の面接ということで。","id":"exchange-030"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは、軽い例もあるし、逆に、重い例もあるという、両方のケースというのは考えられるのでしょうか。軽い例、要するに、あまり特別支援教室を使わなくてもいいとか、逆に、学校では無理だから、例えば、特別支援学校とかいう場合。重い例とか軽い例とか、これはいろいろなバリエーションとかがあるのですか。","respondent":"村尾教育総合支援センター長","answer":"委員のおっしゃるとおり、面接すると、この子についてはやはり都立の特別支援学校が適しているだろうという判断もありますし、この子については、お母さんが心配をされているのですけれども、通常学級でどうにかなるのではないか、まだ様子を見るというように。","id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それと、先ほど、新しい制度に４月から移るのだけれども、従前の通級指導学級の設置校へ通う形でも、それを希望する人はいいのだというようなご説明だったと思うのですが、そうすると、４月以降というのは、現在の通級指導と、特別支援教室に先生が逆に学校のほうに来るというのが並列されることになるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ただ、東京都のほうは、何年か後には通級指導という形はなくして、全ての学校で子どもに応じた学習、また、支援が受けられるようにというような制度を考えていますけれども、区としては、来年度は並列型ということで、子どもたちのニーズに応じて対応できるように、今。","id":"exchange-032"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"なかなか現場は大変だと思うのですけれども、子どものためにも、あるいは学校のためにもいろいろいい方法とか、いいあり方を探っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"こういった図を示していただいたので、イメージが大分わかりやすくなったと思うのですが、現状についてお伺いしたいのですけれども、先ほど、１２５人のお子さんがいらっしゃるということなのですが、今までは情緒障害等の通級で４校ということ。ここの４校は大体中身的には同じ中身でやっていたのかどうかということと、先生が、４校だから４人だけだったのかどうか、まずそこのところを教えてください。","respondent":"村尾教育総合支援センター長","answer":"今、教員数は、合計で１８名います。それぞれ学校の設置が、やはり通級指導学級の設置のクラス数が違いますので、その辺で今１８名教員がいます。来年度はこの１８名がそのまま継続で対応できるようにしています。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、資格とか研修とか、あと、やはり跡を継いでいただくというか、そういう先生が増えていただきたいと思うのと、先生が通っていくという面では、そこの学校の教師の皆さんとの関係はより密接になっていくかと思うのですが、教員全体のインクルーシブ教育への理解が広がっていく、こういった障害等を持ったお子さんへの関心とか、そこを深めていきたいという先生が増えていかないと。","respondent":"村尾教育総合支援センター長","answer":"力量、研修を含めてお話しいたしますが、まさに本年度、それぞれ通級指導学級の先生方には何回か研修に来ていただいて、具体的な理念とか考え方とか、これからどういうふうにしていくのかということについては、事前に説明をしながら進めているところです。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後に、支援体制というところで、先ほどちょっとご説明があったのですが、非常勤専門員、月１６日の勤務、事務とか準備ということですけれども、こういう方々は資格とかはどうなのかと思ったのと、臨床発達心理士、年１０回なのですけれども、これはどういう回り方をされるのかというところを、わかったら具体的に教えてください。","respondent":"村尾教育総合支援センター長","answer":"特別支援教室の専門員、非常勤職員なのですけれども、教員免許があるのが望ましいというような条件で、特にそれが必須条件ではありません。少し子どもたちとのかかわりがある人とか、教育に十分理解があるような人ということで採用するというような感じでございました。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"今まで通級を利用されていた親御さんにちょっと不安の声があったのですけれども、通級に行っている週１回は、友達にも内緒にして、病院に行くと言いながら通級に通っているという状況があると聞きまして、それがやっぱり自分の学校になってくるというと、何であの子は来ているのにいないのだろうという、周りの理解、これがないと何よりも動きづらいのだということを伺ったのですけれども。","respondent":"村尾教育総合支援センター長","answer":"このチラシの裏面の一番上のほうにも、保護者にまず理解してもらいたいということで、発達障害というのはしつけとかそういう問題ではなくてということでご理解いただくようなこと、また、これについては、まず、保護者のほうには各学校を通してこのチラシをまくとき、また、４月。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。いろいろその子その子に応じて臨機応変にできるようにしていただきたいと思いますし、あと、保護者にも子どもたちにも教員の皆さんにも、やはり広く理解を広げる努力というか、していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"昨日の補正予算、あの中でも、教室の間仕切りとかいろいろ質問させていただきましたけれども、それはそれで対応していただければと思うのですが、先ほどの話の中で、通級が１２５名ということで、これからいろいろ面談とか面接とかをやる中で増えていく可能性はあるという話でしたけれども、今の教室を改装するという中で、どのぐらいのキャパまで大丈夫なのかというのがちょっと気になったので。","respondent":"村尾教育総合支援センター長","answer":"それが６時間目までしかないので、人数割りして、例えば、個別でやるとしても、その教室に２人か３人ぐらいずつで対応できるようなやり方もできるのではないかとか、また、グループで学習をするような形態はとれないかどうか、これについては先行の学校の事例をよく考えながら。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"例えば、今回の通級というか、今回の体制に変更することによりまして、例えば、今まで担当していた先生が今まで担当している子どもとそのまま継続してやるという体制をとるのか、それとも、いろいろな先生がいろいろな子どもたちと接するような形をとるのか、この辺まではどうかということは私も認識していなくて申しわけないのですけれども。","respondent":"村尾教育総合支援センター長","answer":"それについては、保護者、それから本人と十分話をしながら、どうしても今年いっぱい、来年度もこのまま継続してほしいとか、今５年生で６年生まであと１年間だからとかといういろいろなケースがあると思いますけれども、基本的な考え方としては、できるだけ通級機能を残しつつ。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはり子どもたちと、そしてまた親御さんとよく相談をして、本人にとって一番いい方法で進めていっていただきたいと思います。そういう意味では、この体制をやはり大成功させていただいて、品川区の子どもたちを守って、また、しっかり教育する体制をこれからも構築していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねしたいのですけれども、モデル実施をしたわけですよね。それからあと、今、固定級がある小学校があると思うのですが、そこの固定級に先生方が配置されているのですが、そこに関係なしに、通級指導の先生ということでプラス１という形になるのですか、固定級のあるところは。そこの仕組みのところ、固定級が現在あるところ。すみません。","respondent":"村尾教育総合支援センター長","answer":"大きく４点、あったと思います。昨年度以来、インクルーシブ教育のモデル実施を本区のほうでも進めてまいりました。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"新たな仕組みをそのような形で整備して、よりプラスになる指導をしていっていただきたいのですが、１つだけ、先ほど、ベテランの先生方がということでありましたが、特別支援教育に関しては、そういった先生方が長くやられている例が非常に多くて、団塊の方々等がご定年になって抜けていって、かなりそういったところが、専門の方が少なくなっているとお聞きして、さらに新採の方もほとんど、逆に言うと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"伊藤副委員長","kind":"質問","question":"端的にお伺いします。特別支援教室、品川区は平成２８年度より一斉に設置するという表現になっています。そうすると、教員の追加配置が多分必要になってくると思うのですが、その見通しはいかがなのでしょうかというのが１点と、それから、あと、さっきの質問に重なりますけれども、専門の指導教員がいない場合の特別支援教育の展開の穴埋めをどうするかというところがわかりました。","respondent":"村尾教育総合支援センター長","answer":"２点目です。新拠点校も含めたその学校にいる先生、いわゆる指導員が他の学校に派遣した場合、その子は通常は週１回の取り出しですので、それ以外は通常の、自分の所属の学級で学習をしていますので、担任が基本的に学習を対応していくというような考えになると考えています。","id":"exchange-044"},{"speaker":"伊藤副委員長","kind":"質問","question":"人員のことはわかりました。それから、クラスの名前、全校展開していくわけですから、それはいろいろな知恵を使っていただいて、それぞれの学校に由来する名前であったりとかあるわけではないですか。学校の特色もあるでしょうから、それぞれの地域の名前を含めて、ぜひやさしい名前を検討してください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"〔「今年までです」と呼ぶ者あり〕終わってしまうので、これがかなり学校の中では効果があったとお聞きしているのですが、それとのかかわりというか、それはどのようにして、来年度どうなるかという話になってしまうから、ちょっとお話ししにくいのかもしれませんけれども、もし仮に何らかの形でこのモデル事業を区の事業でできるとすると。","respondent":"村尾教育総合支援センター長","answer":"それで、今年度はそれに追加をして、今、通級指導学級を行っている学校に配置をして、実際に先生方が派遣をしてみて、子どもたちの学習としてどうなっているかというのを客観的に第三者として先生と子どもの関係を見ながら、どういう学習の仕方ができるかということを。","id":"exchange-046"}]},{"id":"topic-03","title":"平成２７年度「秋のブックフェア」","agenda":"平成２７年度「秋のブックフェア」","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"秋の子ども読書フェアなのですが、これは今年の４月は荏原文化センターが工事中なので今の時期になったというお話なのですが、例年、大体どのぐらい参加者はいらっしゃるのでしょうか。","respondent":"木村品川図書館長","answer":"昨年の実績ですが、延べですけれども、１,１００名という形です。","id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"人形劇というのは、具体的にどのような団体がされるのでしょうか。","respondent":"木村品川図書館長","answer":"これは、実際に劇団でございまして、正式な名前は今、持ち合わせてございませんで、申しわけございません。そちらに委託して、実施いたします。","id":"exchange-048"}]},{"id":"topic-04","title":"平成２６年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２６年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"家庭あんしんセンターのほうですけれども、私、これがどういった中身で運営されているところなのかというのが、事務事業概要とかを見たのですけれどもちょっと中身がわかりづらくて、どういった事業をされている、提供しているのかというのを具体的に伺いたいのですけれども、ひまわり荘、子育て支援センター、ファミリー・サポート・センター、ショートステイ。","respondent":"廣田子ども家庭支援課長、伊崎子ども育成課長","answer":"私から、子ども家庭支援課で管轄している部分についてご説明申し上げます。ひまわり荘につきましては、配偶者のない女性とお子さんが自立するために生活しています。私からは、子ども育成課が所管いたします子育て支援センターについてご説明いたします。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、ここでの改善が必要な事項というところで、子ども・子育て支援新制度の事業として区が計画に基づき実施していくにあたって、運営方針を見直し、適切に進行管理を行う必要があるというところでは、ここでの子ども・子育て支援新制度で変わってくるところというのはどういうことになるのですか。","respondent":"伊崎子ども育成課長","answer":"そういったところで、この事業の性格が改めて法的に明らかになったということを踏まえまして、これまでは努力義務だったのですけれども、区のほうは取り組んではまいりましたが、明らかに法定されたということを踏まえて。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、あともう一個、ぷりすくーるのほうですけれども、これも改善が必要な事項のところで、「待機児童の増加に伴って年度途中の退職等が生じる」というのはどういうことなのか伺いたいのと、あと、職員の処遇改善に取り組む必要があるというのは、ぷりすくーるとしてはどういうふうに取り組むのかというのがちょっと気になったので、伺いたいと思います。","respondent":"竹田保育課長","answer":"大変申しわけございません。それから、処遇改善につきましては、指定範囲の、権限の範囲の中で、賃金体系等を見直していくです。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"保育士不足が大きな問題になってきていますので、こういった区立の就学前乳幼児教育施設ですので、ぜひここだけでなく、処遇改善を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ひまわり荘では、平成２７年度に入所期間の目安である２年に達する世帯が全体の８割に達することから、自立後の云々という記載があるのですが、これは、要するに、２年間たったら、入所している家族は退所しなければいけないのだけれども、８割が今、それに近づいているというような意味なのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"新規に入所される方、今現在は１７世帯入っているのですが、２０世帯中でまだあきはあるので、今すぐ入りたい方は入れるような状況ではあるので、待たせているという状況はないのですが、この施設を活用して自立支援に取り組んでいくにあたっては。","id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私はひまわり荘の嘱託医だったので、健診などの具体的なことがよくわかるのですけれども、なかなか実際大変だということはよくわかっているのですが、改善が必要な事項というところに載っているということで、例えば、具体的に、２年間で卒業して自立できるような支援とか援助ということに関して、どのような点を改善するとか、評価したらいいのかという総括はされているのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"年に２回面接を行っておりまして、全家庭の母子の母のほうと現場の担当の職員と、区側の母子自立支援員が立ち会って、本人の気持ち、なぜ到達できないのかであるとか、課題についてをそこでさらに洗い出しをして、また、計画の見直しが必要である場合には。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"家庭あんしんセンターなのですが、事業が結構多岐にわたって行われていますけれども、この中で、利用状況というか、ひまわり荘は定員があるのでしょうか。いっぱいになっているかどうか、それをお伺い……。ショートステイとトワイライトの利用状況、ファミリー・サポート・センターは概要で見つけたのですが、トワイライトとショートがわからなかったので、ここら辺の利用状況を教えてください。","respondent":"廣田子ども家庭支援課長、伊崎子ども育成課長","answer":"お部屋の数の関係で、人数ではなくて、２０世帯なのですが、平成２６年度末で卒業した方もいらっしゃって、１３世帯で、今、４世帯入りまして、１７世帯で４３名入所しております。ショートステイにつきましては、平成２６年度の実績で延べ３１泊、トワイライトステイは、延べ利用人数は３,１７６人です。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ショートとかトワイライトのところというのは、何か課題が今現在あるかどうかをお聞かせいただきたいのと、あと、ここのところの職員が、どういった職種の方がどのくらいいらっしゃるのかを教えてください。","respondent":"伊崎子ども育成課長","answer":"職員の配置につきましては、こちら、ひまわり荘と一体的な施設ということでやっておりますので、そちらの職員との支援の体制もいろいろとあるのですが、ショートステイ、トワイライトステイとしましては専門員が１人と、あと、非常勤職員が３人ということでの。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一体ということなのですけれども、自立支援のところとか、そっちの職員も教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長、伊崎子ども育成課長","answer":"ひまわり荘につきましては全部で１４名おるのですが、施設長が１名、母子支援員が３名、少年指導員が２名、保育士１名、調理１名、嘱託医が１名なのですけれども、宿直の非常勤が２名、自立支援充実職員とかで非常勤が１名。失礼いたしました。先ほどのショート、トワイライトですが、ここの人数は４人ですが、専門の職員が２名で、臨時職員、非常勤が２名ということです。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぷりすくーるのほうなのですけれども、下の枠の評価事項のところに、ぷりすくーる西五反田教育・保育課程が完成したと。これ、どういう中身なのか教えていただきたいのが１点と、あと、新制度が始まったと。この後の説明の中にあるのかどうか、新制度の中で、公定価格とかその辺で、今までと不利な場合、変化するような中身というのは何かあるのでしょうか。立場的な違いで。","respondent":"竹田保育課長","answer":"保育・教育課程のほうですが、この中身につきましては、特に重要視したものとしては、保護者との連携、特別支援、それから、職員の資質の向上について理解を深め、ぷりすくーるが目指している子ども中心の保育を目指せるような内容となっております。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問","question":"最後に、再委託業者の見直しということなのですが、現在、どういった再委託をしているのか、その中身を教えてください。","respondent":"竹田保育課長","answer":"今後につきましては毎年度、見積もりを複数社から聴取して、再委託を行っていくです。具体的には、給食委託とか定期清掃、それから、消火設備等々の各種業務を再委託しているものです。","id":"exchange-059"},{"speaker":"浅野委員","kind":"確認","question":"多くは母子家庭なのですけれども、なかなかひとり立ちしていくのが難しいというふうにも話は聞いておりますが、就労に向けた支援として、例えば、手に職をつけるとか、そういうような支援をやられていると、かなり前ですが、聞いた記憶があるのですけれども、それは現在も続いていると思いますが、それを１点確認したいと思います。","respondent":"廣田子ども家庭支援課長","answer":"手に職をつけるという形では、ほかの支援のサービスがあるのですけれども、現在のところ、そこに合致するような方は対象としていらっしゃらないので、あるのが、転職を、今の働き方だと、夜割と遅くなるお仕事ですと、自立した場合に。","id":"exchange-060"},{"speaker":"浅野委員","kind":"質問","question":"いろいろありがとうございました。私も一回お邪魔させていただいたことがあるので、ある意味、きれいなところだという印象はすごく残っているのですけれども、やはりその中で暮らしている方の生活はさまざまかと思います。それで、自立をして、例えば、都営住宅ですとか、そういうところにも入られるというふうに話を伺いました。","respondent":"廣田子ども家庭支援課長","answer":"ただ、ご希望されない場合に、ドロップアウトということもあり得るとは思いますが、再度入るということはないようにしたいのですけれども、状況に応じて、本当に必要に迫られれば、その都度、相談の中で、何がいいかというところで、ただ、居宅があれば。","id":"exchange-061"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認で教えていただきたいと思います。このモニタリング・評価は、前回、どのくらい前か。毎年やるのか、それとも何年かに一度なのかとか、確認で教えてください。取り組んでいる、苦情解決第三者委員を設置して改善に努めているということだったのですが、区民の視点で希望が多いということは満足度が高いということなのかどうかというのがちょっとわかりにくかったので、その辺を教えてください。","respondent":"竹田保育課長","answer":"満足度の点ですが、保護者会等を通じて、在園者の保護者の方からご好評をいただいているところです。そういった評判が近隣の方のお耳に届いて入園希望者が多くなっているというところで、区民満足度も高くなっているのではないかというふうに推測したところです。","id":"exchange-062"},{"speaker":"大倉委員","kind":"質問","question":"満足の視点は、満足度が高い、保護者の方からも、地域のほうからもそういった口コミが広がって、高いということはわかったので、そういうふうに書いていただいたほうがわかりやすかったというところと、あと、モニタリング調査も毎年やっているということで、例えば、前回もいろいろな指摘とか改善点とかというのがあったかと思うのですが。","respondent":"竹田保育課長、廣田子ども家庭支援課長","answer":"といいますのは、去年、開園１０年でいろいろ式典等がありまして、通常の年よりも出費が多くなったというところで、前年まで蓄えていたお金で執行したという関係の中で、通常よりも執行率が多かったということで。昨年の指摘事項については、申しわけありません、このシートではわからないのですが、このモニタリング・評価をするにあたりまして、まず最初に指定管理者みずからが評価をし、区の所管課が評価をし。","id":"exchange-063"},{"speaker":"大倉委員","kind":"確認","question":"その辺を含め、こちらがわかる必要があるのか、またちゃんと把握されて、改善されたというのを確認されていますということだったのでいいのですが、その辺ももしわかればいいかと思って、ＰＤＣＡとかでどんどんよくしていこうという意味では、前回の評価もわかったほうがありがたかったと思って、ちょっと聞きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問","question":"これ、もう一枚、総括シートではなくて、ぷりすくーるについてというのはこれから説明されるのですか。では、そのときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"}]},{"id":"topic-05","title":"品川区立就学前乳幼児教育施設（ぷりすくーる西五反田）","agenda":"品川区立就学前乳幼児教育施設（ぷりすくーる西五反田）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今回、途中経過という報告なのでしょうけれども、ぷりすくーるが新制度移行にあたっていろいろどのような方向に行こうかというところの報告ですよね。その辺がちょっと唐突で、どう受けとめていいのか、今、お話を伺って思ったのですが、今日の報告に至る経過をお話しいただければと思います。","respondent":"竹田保育課長、金子子ども未来部長","answer":"といいますのは、それへの課題といいますか、幼保連携型認定こども園は、先ほどご説明したとおり、設置主体が国、地方自治体、学校法人、社会福祉法人に限られておりますので、今の指定管理者は特定非営利活動法人ですので。プリントと説明については、ほぼ課長の説明どおりなのですけれども、最後のほうのくだりでありました、今、運営しているＮＰＯの子育て品川については。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"次に聞きたかったことを今答えていただいて、設置主体が運営しなければならないということは、今は区立で運営しているけれども、ここが新しく社会福祉法人を設立できたならば、区としてはその先を考えていくということなのですね。どういう形なのか、そこが一番疑問だったのです。","respondent":"竹田保育課長","answer":"今、このＮＰＯが社会福祉法人の設立を目指しておりまして、社会福祉法人になった暁には、幼保連携型認定こども園を運営していくという形になろうかと思います。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが形が変わっていくということですよね。もう一つ、幼保連携型認定こども園というのは今まで品川区にないので、区立の保育所型の認定こども園は、今、３件ありますね。私立のところでも認定こども園はあるのですが、この辺、違いを教えていただきたいのですが。これを選んでいくという意味で、違いを説明してください。","respondent":"竹田保育課長、今井待機児童対策担当課長","answer":"今回の幼保連携型認定こども園ですが、こちらについては、先ほど申し上げたとおり、幼稚園教諭の免許と保育士資格を持った保育教諭が従事するというところです。新制度の認定こども園と現在の認定こども園の違いということでございましたが、今、ご説明しましたとおり、前も制度として幼保連携型認定こども園というのはございました。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"幼稚園は幼稚園、保育園は保育園という、そこのところの連携はどう図られるのかと思って、私もよくわからないので質問してみたのですが、新しくトライをするといった意味では、いろいろすごく検討はされていると思うのです。なので、ちょっと聞いてみたのですけれども、すっきりしないのですが、あと、運営主体が社会福祉法人になるということは、今の形態から変わるということですか。","respondent":"金子子ども未来部長","answer":"新制度になってどこが変わったかという一番大きなところは、従来の幼保連携型というのは、あくまでも幼稚園と保育園、それぞれの法規制にのっとって認可された施設が、２つがくっついたものでしかなかったのです。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"今までも幼保一体でいろいろ苦労していたのは、文科省のところと厚生労働省の両方のところが管轄をしながら一体的に運営していた困難さを、直轄的には内閣府がなるわけですか。どうなのですか。私もあまりイメージが浮かばなかったのですが、でも、それにトライをしていくということで、区は支援をしていくということなのですか。今日は単純な、単なる報告だけなのですか。せっかくのご報告なので。","respondent":"竹田保育課長、金子子ども未来部長","answer":"数々検討した結果、先ほど申し上げました幼保連携型認定こども園を目指していくという概略の方向性が決まりましたので、今回はその方向性で進めするというご報告です。これについて詳細を検討していかなければならないということですので、これからさらに詳細なところ、それから、スケジュールについて、課題はたくさんあるのですけれども、詰めていかなければならないという現在の段階です。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前からどうするのかと考えていたので、これからまだ時間がちょっとかかりそうなので、見守りながら、意見を言うべきときは発言させていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それだとすると、それは５番でよくて、６番にぷりすくーるがあって、５番が区としての考え方ということで、区の施設について、もちろんぷりすくーるも区立なので、含めてのお話だと思うのですけれども、そこで、ぷりすくーる以外のところの認定こども園化について、これはそれと同じぐらいのスピードで進めていっていくというのでしょうか。","respondent":"金子子ども未来部長","answer":"ですので、これも経過措置があるので、５年間は猶予があるから５年間は保育教諭にならなくてもいいのですけれども、５年たてば保育教諭になっていなければなりませんので、この辺をどう見極めて、どういうふうに転換していくのかという展望を持ちながら。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。今、お話のあったハードルがあるとは思うのですが、それこそ就学前教育の先頭に立ってきた品川区ですので、ぜひとも今お話があったようなハードルを越えて、これは新制度でありますけれども、そちらに進んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4866#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":63059,"voices":190}},{"id":"h27-20150925-5","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"総務委員会","time":"午前１０時００分～午後 ３時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を108件抜き出しています。","topics":[{"id":"topic-01","title":"第６７号議案 平成２７年度品川区一般会計補正予算","agenda":"第６７号議案 平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"それと、情報のセキュリティですけれども、ウイルス対策ということですけれども、攻撃を受けるツール、侵入経路は、何を想定しているのかということなのですけれども、一般的にはメールの添付資料を開いたときだったり、ＵＳＢを差したときだったり、様々な侵入経路はあるわけですけれども、どういうところの侵入経路を今一番強化しようとしているのか。","respondent":"秋山財政課長、仁平情報推進課長","answer":"最初の、補正に絡む考え方という部分ですけれども、最初にご説明させていただきましたけれども、今回も、６月補正のときにも説明させていただきましたけれども。２３区の中でほかで使っているかまでは承知しておりませんけれども、品川区は先行するのかと考えています。次に、インターネットの分離の関係です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"セキュリティの関係ですけれども、いろいろ資料を交えながらご説明いただけるとありがたいと思うのですけれども、つまりは、区の職員の方々、中小企業センターとか地域センターとかも含めて、あらゆるパソコンのインターネットやメールのやりとりが１つのサーバを経由して使われるということで、それぞれのパソコンが直接。","respondent":"中山企画部長、工藤選挙管理委員会事務局長","answer":"最初に、まず補正の全体の姿勢にかかわる部分です、スピード感みたいなところでのご説明ですけれども、今回まさに、例えば認証保育所の運営費助成の公定価格が決まって、本来もっと早くやりたかったけれども。こういった部分の機材の貸出しが増えるだろうということで、今、手持ちの機材に若干この２０万円を使って追加するというのが実情です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"セキュリティのほうはこれで最後にしますけれども、いろいろ強い体制をつくっていかなければいけないと思うのですけれども、今回の年金機構の対応を見ると、もう１つ、初動の取組みが結果として遅れてしまったことが後から広がってしまったり、部署間の連絡がスムーズでなかったり、そういうお話も伺いました。","respondent":"工藤選挙管理委員会事務局長、仁平情報推進課長","answer":"八潮高校の模擬選挙等の狙いです。こちらは、最後に報告事項でやらせていただく予定ですけれども、いわゆる法律の関係が６月に改正されまして、来年の参議院選挙から選挙権が１８歳に引き下げられることが決定されたわけです。そういう体制が現在も副区長をトップにしました統括情報管理者が緊急判断するという体制になっています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"例年この総務委員会で総合審査をやる、もちろんその前提としてそれぞれの常任委員会で審査をして報告を受けた形にはなってはいるのですけれども、いわゆる考え方だったり、根拠だったり、そういう議論がなかなか総務委員会で正直やりにくいというか、答弁者も含めてやりにくいというのは私の実感で、これは例年この形でやっているので、今回からというわけには決していかないのはよくわかるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"プレスで発表されるということは、公に出るということで、新聞紙上にも載るということ。そういうｉｆの中で、否決された場合には、どのような考え、どのような方法でこの事業を遂行あるいはまた出していかれるのか、そこの危機管理上の考え方について伺いたいと思います。","respondent":"秋山財政課長","answer":"補正予算が否決された場合ですけれども、当然否決をされた場合には、その分の支出というか、予算は執行できないですので、それは何らかの対応はそれぞれの、今回であればいろいろ案件をお出ししていますので、その中でどうするかということを考えて。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"あくまでも議会の側です。ないように、あるようにというのは議会のほうの立場であって、ないようにしていただくのは行政は当たり前というか、やっていただくのは当然のことだと思うのですけれども。いろいろな流れの中で議会の色合い、性格、委員構成も変わってきていますので、そこらの危機管理を今後どのようにされていくか、もう１回伺いたいと思います。","respondent":"中山企画部長","answer":"新たにそれが必要であれば、ご議決の際の議論も踏まえた然るべき提案の仕方をしながら、いろいろ議会とご相談しながら、それを再度執行していくタイミングを図りながらやっていくという部分がある、これは次善の策として考えるですけれども。","id":"exchange-006"},{"speaker":"あべ委員","kind":"確認","question":"確認を兼ねてお伺いしたいのですけれども、今回の補正をざっくり拾ってということで、この中で、例えば児童福祉費で８億円余り、ほとんどがそれに当たっている。全体としての今回の構造といいますか、性格といいますか、あるいは工夫したところと言ったら変な言い方なのですけれども、どういう発想の流れでこういう形に落ち着いたのか、ご説明いただければと思います。","respondent":"秋山財政課長","answer":"ただ、その額面の多寡については、１つ大きいものがあるからほかを出すとか出さないとか、そういうような判断は私どもとしてはしておりませんで、あくまでもいろいろな事業、出てきた事業について、補正をする必要があるのかないのかという必要性を。","id":"exchange-007"},{"speaker":"本多委員","kind":"意見","question":"新たな事業や国庫支出金等に連動して追加計上が必要となった経費、早急に予算措置を講ずる必要があるということで補正が組まれているのですけれども、平成２７年度が全部終わった時点で、この全ての予算に対する執行率が出てくるのだと思うのですが、この補正を見ると、本当に区の方針ですとか、区長の公約ですとか、それを積極的に推し進めるぞという意思がすごく伝わってくるのですけれども。","respondent":"秋山財政課長","answer":"ほかにも新たな事業ということで、ネウボラ関係の事業等もありますけれども、これも執行率ということは今の時点でまだ執行は当然していないわけですけれども、補正を出してやるということにおいては、当然執行率は高くなっていくべきだし。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"ここでタイ語をわざわざ持ってきた、それはどういうわけですか。大体例えば英語で、ここの圏内なら英語で済んでいるわけですよね。それを例えばタイ語をやった、では、今度、別の国の要望があったら、それもそういう表示をするのか、そうすると、いろいろな各世界の外国語がいっぱい並んで、その表示の種類があふれてしまうと思うのですけれども、ここはどうしてタイということに設定をされたのですか。","respondent":"秋山財政課長","answer":"タイに関しましては、当初の中でもタイからの観光客の観光業者等との大田区との合同事業ですとか、いろいろやっておりましたので、そこの中でタイの、今回、２月にタイの旅行博がありますというところで、そこに向けてタイの観光マップを作成するということで、今回。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"恐らくここの圏内なら、タイならば英語で済んだのかと思うのです。それと、先ほどもおっしゃられましたけれども、では、ほかの国と、これからオリンピックに向けて、またいろいろ交流がされると、またそこの国の言葉の表示板も出すのか、そういうふうになる、わざわざここでタイ語を選ぶ、またここで出していくというのも何か不思議な気がしたので質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"私、６月の総務委員会のときにも発言させていただいたと思うのですけれども、情報は絶対に漏らさないという覚悟でお仕事はしていただきたいけれども、なおかつそれに対して何かあったときの具体的な初動というか、それを考えるのがやっぱり危機管理だと思いますので、もうちょっと区民が情報を預けるに当たって安心できるには、何かあったときのすごく素早い反応、それが責任者というところまでいかなくとも。","respondent":"仁平情報推進課長","answer":"何か起こりますと、異常がありますとメールを自動で送ってくれるとか、夜間でもそういう受信をしながら監視を続けているものですので、何かの場合には緊急対処が必要になるというケースもあるのかと思います。","id":"exchange-011"},{"speaker":"吉田委員","kind":"意見","question":"いろいろな情報が漏れたケースを、そんなにすごく詳しく見ているわけではないのですけれども、システムの問題はとても大事ですけれども、ヒューマンエラーというか、人の意識の問題が大きいような気がしています。その辺まで含めて、ぜひ今後の対策、危機管理ということを考えていただけたらと思います、意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"あくつ副委員長","kind":"質問","question":"私も同じところで恐縮なのですけれども、ネットワーク・セキュリティのところで、先ほどの質疑でいろいろあったのですけれども、先ほどのご答弁の中でもありましたけれども、また、先ほどの質問でもありましたけれども、情報の責任者は、統括情報管理者ということで、これは副区長の充て職になられているのですか。","respondent":"仁平情報推進課長","answer":"３点目、攻撃です。庁内のネットワークには外部からの侵入はできないようなしくみをとっております。ただし、その外側で感染しているところがありますと、攻撃があるかないかと言われますと、攻撃はあります。そこではじき返している。","id":"exchange-013"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"総合審査なので深くは参りませんけれども、今伺ったところ、本当に区民の方々が想像している以上に情報の漏えいの危機は今そこにあるというか、本当にこれは重く見ていかなければいけない、補正予算は非常に大事なものだと思います、今回組んであるものについてはそう思います。それは希望として言わせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"すまいるスクールですけれども、時間が延長されることに伴う職員の体制が不安定だということと、利用料の有料化は間違っていると思いますし、子育て支援の大幅な後退であり、これは止めるべきだと思います。補正予算全体の評価としては、こういった前進面はあるものの、生活保護の改悪やすまいるスクールの改悪、子育て支援の重大な後退、これは重大な問題だと思いますので、総合判断として反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問・要望","question":"今回の補正は非常に基本的な取組みにかかわる、事業にかかわるもので、ぜひしっかり進めていただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、この点については賛成しかねるのですけれども、一方で、ほかのいろいろな施策について、今の情報のセキュリティのことなどはぜひぜひやっていただきたいと思いますし、そういうことを勘案いたしまして、この１点はなかなか賛成しかねるところがあるのですが、全体としては賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"品川区教育大綱の策定","agenda":"品川区教育大綱の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それと、本題のこの大綱の策定についてですけれども、まず、この大綱の位置づけについてなのですけれども、ずばり教育委員会の独立性はどう担保されているのか、この点を伺いたいのと、この大綱の位置づけのフローチャートみたいな資料が１ページ目にありますけれども、品川区基本構想に教育委員会を縛るという、そういう関係があるのか、そこの２点を伺いたいと思います。","respondent":"江部総務課長","answer":"マイク使用につきましてということで、２回目、確かに第１委員会室というところで、１回目は第二庁舎の会議室で、ちょっと狭めのところで特に音声の問題はなかったのですけれども、第１委員会室に変えた関係で、ちょっと聞き取りづらかったなということはお詫びしますが。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"資料については、この間、議論のあったところですけれども、未確定な資料であっても、その場で議論されている資料であり、傍聴者も認めているわけですから、私は持ち帰っていただいても何ら問題はないと思いますので、ぜひ改善していただきたいと思います。マイクについては、いろいろ改善を進めていただきたいと思いますので、よろしくお願いいたします。それは要望です。","respondent":"柏原企画調整課長","answer":"イコールそれが教育委員会を縛るとか拘束するというものではなくて、繰り返しになりますけれども、お互い協議しながら、そういった方針を示していくという内容のものです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"どちらかがどちらかを縛るものではないと、同じように拘束するものではないということですけれども、その上で、５ページ目の学校教育の充実というところですけれども、ここに「校舎改築や学校配置のあり方について検討します」という記述があります。これは学校統廃合のことを指しているのか伺いたいのと、区長が教育委員会に学校統廃合を求めると、そういう内容のことなのか、ご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"そういったところからの考え方から来ているところが１つと、それから校舎改築等々、今後進む老朽化であるとか、そういったところを踏まえながら、学校の改築等々については検討していかなくてはいけないだろうという趣旨の中身です。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"趣旨がわからないのでもう一回伺うのですけれども、つまり「学校配置のあり方について検討します」とは学校統廃合のことを指すのか、区長が教育委員会に統廃合を求めるという大綱になるのか、そこを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ここの５番目のところの文章ですけれども、一番頭のところに「良好な教育環境の確保のために」ということで、委員もご指摘いただきましたけれども、人口動向の検討であるとか、諸々大きく社会環境の変化があるといったところがあります。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう少しやはり、教育とは何ぞや、品川にはどういう子どもが育ってほしいのかということをきっちりと、哲学の部分、理念の部分から大勢の方で語り合っていただいて大綱というものをつくっていくという、これはその方が私は大綱というものにはふさわしいのではないかと思います。","respondent":"柏原企画調整課長","answer":"この大綱の中身で想定といいますか、話をしていますのは、こちら、４ページのほうから順番に言っておりますけれども、就学前教育の部分からありますので、基本的には学齢期に入る前の方では幼稚園や保育園、そういったところでの入られる方々。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"地域のことでも、例えばお知らせは区立学校にしかいかない。最後に、文化芸術の振興とあるのですが、生涯学習が教育大綱の中に入っているという、私は実はちょっと違和感がありまして、これはむしろ生涯学習大綱で分けて展開すべきものではないだろうかと思っているのです。これは教育大綱が位置づけられた後なので。ちょっとこれは私、考えていただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"ただ、品川の場合はそれはもう何年も前から教育委員会から離して違った形で動いておりますので、そういった今までの動きとかも考えながら、今後の検討の課題なのだろうというふうに思ってあります。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれご答弁ありがとうございました。今回初めて教育大綱というものをつくられているわけですが、ある程度、スケジュール的に限られているというふうに認識しておりますが、総合会議の中でさらに品川らしい肉づけ、理念というものを今後またしっかりと議論していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"その中で特に一番重きを置いていただきたいのは、子どもたちの日常生活を見守れるような環境を区側でしっかりつくり上げていってほしいと、一人一人目が届くような、それが自殺等、いじめ等、様々な広い分野に行き渡ると思うのですが、そういう大綱をぜひつくり上げてほしいという意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"私、策定の手続きのところで１つ質問させてください。だから、先ほどの教育委員の方からのご意見とか、パブリックコメントで出た意見がどのような形で生かされていくのか、その辺のことを教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"それからホームページにも当然掲載いたしますけれども、ホームページでも全文が見られるような形で出す予定です。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、言葉は悪いですけれども、とにかく意見は聞きましたよという姿勢を示すだけみたいな手続きになってしまうと、とても嫌だというふうに思いますので、その辺を具体的にどう生かすか、もうちょっと教えていただけるといいと思うのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"スケジュール的にどこまでということはありますけれども、基本的にはそういう形で区の会議に、こういう意見がありました、それに対してこういう考え方です、それに対して修正するのかしないのかということも含めて、総合教育会議でご議論いただくという流れで考えております。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"言葉で幾つかあるのですけれども、時間がないので１つだけ伺いたいのですが、５ページの学校教育の充実というところで、「子どもたちの「生きる力」、「生き抜く力」を養うことのできる市民科の推進に努める」とあるのですけれども、逐語でやっていると本当に時間がかかってしまうのでこれだけ聞きたいのですが、「生きる力」と「生き抜く力」はどういう違いがあるのか。","respondent":"柏原企画調整課長","answer":"どちらかと言いますとスローガン的なところが大きいかというふうに思います。もちろん「生きる力」、それからこれから子どもたちが社会を生き抜いていくといいますか、進んで生きていくのだというような意味合いを込められたというふうに認識しております。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほど言ったのはそういう意味ではないと思うのです。先ほど、これは基本構想とか長計の中で議論していくべきものだということがあるのですが、まさに私も長計とかを読んでいて、非常にここの部分が品川区はちょっと寂しい、薄いなという部分は常に感じているところなので、これこそ品川区の、せっかく区長が、首長が絡むということであるものですから、ここを厚くしていただきたい。","respondent":"柏原企画調整課長","answer":"それは全部推し進めていく分野だろうというふうには思ってあります。それが教育委員会がいいのかどうかはまた別の議論になろうかと思いますが、そこは区としても推し進める分野であるというふうに思ってあります。","id":"exchange-029"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"教育委員会で進めるとかということではなくて、大綱の話をさせていただいていますので、せっかく今回、首長部局とやるということは、今回、この俎上に上がって総務委員会でやっているわけですから、そういった観点でぜひ推し進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-03","title":"町会・自治会のあり方と区との協働に関する調査研究","agenda":"町会・自治会のあり方と区との協働に関する調査研究","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"方向性は大歓迎なのですけれども、ちょっと気になるところがありまして、「品川区町会・自治会の活動活性化推進条例」という仮称なのですけれども、方向的にはいいのですが、気持ち的には、「町会・自治会支援条例」というような名称のほうが、我々会派が求めていたイメージなのですけれども、一番最初に、Ａ３の資料１のほうに、「町会・自治会との協働による」と「協働」というのが頭に来ていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問・要望","question":"中身に入りますが、加入促進なのですけれども、具体的に今まで議論していたのは、住み続けたい品川区ということで、新しく住む方もずっと長年住んでいる方も、一軒家でしょうがマンションでしょうが、加入していただきたいという思いがありますけれども、いろいろとこれまでも新しくできたマンションとかにも、区がパンフレットを配って加入を推進。","respondent":"柏原企画調整課長","answer":"そういったところも含めて、もう既に一部の地区では回り始めましたけれども、町会等とのご意見を伺いながら、どういった方向性がよろしいのかということは検討したいと思ってあります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、理念条例にもかかるのですけれども、来年の第１回定例会に出したいということですけれども、予算案を上程とありますけれども、理念条例だけれども、この条例に予算をつける、予算の執行も伴う条例ということになるのか、これを進めるに当たってのいわゆる一般会計予算のことを差しているのか、そこの関係も教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"予算との関係ですが、条例を考える中で、具体的な施策ということで資料１に記載させていただいているのですが、例えば真ん中のほうにある地域全体でメリットを感じられるような支援制度の再構築ということで、助成制度の再構築であるとか、活動拠点の整備等々。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん町会・自治会にぜひ大勢の方に加入していただきたいとも思いますけれども、一方で加入しなければならないという拘束は、やはり自己決定することですからできないわけですね。そういう意味では、ここで言っている区の責務と区民の役割、責務と役割とは何がどう違うというふうに考えているのか、そして先ほど言った私の問題意識はどういうふうに考えているのか、そこを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"全体の考え方ですけれども、先ほども申しましたように、町会・自治会の活動のためのバックボーンになる１つの規定といいますか、考え方というところを捉えてつくろうというふうに思っているところですので。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうした条例がなぜ必要になってきているかということを感じます。既に品川区としては、ＮＰＯなどに対する支援策を持っておりますけれども、ＮＰＯに限らず、みんなが町会活動をすればそれで地域課題の全てをカバーできるわけではありませんので、そこのバランスをどのように今後とっていくかということ、そういった視点は区としては一方ではお持ちなのでしょうか。その点をまずお聞かせください。","respondent":"柏原企画調整課長","answer":"いろいろな地域でいろいろな貢献をされている方々がいらっしゃるのは存じておりますし、全くこの町会・自治会の条例ができるから、その方たちを否定というのは、全くそういう考えは持っておりませんので、そういった方たちに対してもどういった支援ができるかというのは。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ幅広く地域活動、あるいは社会活動を捉えていただきたいと考えています。もう１点なのですけれども、「町会・自治会の行政への協力業務のあり方の見直し」とあります。この点についてもご意見を伺えればと思います。","respondent":"柏原企画調整課長","answer":"ケースによってですけれども、例えば、どういうまちの入り方をしたほうがいいのか、説明会はどのようにしたらいいのか、そういうものもあわせてご相談する中でというところがありますので、条例化の中で書くかどうかはちょっと置いておきまして。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問・要望","question":"もちろんいい建設業者、組合もいますけれども、区としては、できるだけそういうことに対して助言なり勧誘をしていただきたい。では町会のあり方は、区民にとって、町会員にとって何なのかというときに、区への要望とかご意見などを、皆さん、町会を通じて言ってくださいというようなしくみをつくると、町会の存在感が強まるのかなという気もしますので、それは一言言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"やっぱり本気でちゃんと防災と考えたときには、どこに自分のこの地域でのコミュニティへのつながりをつくろうかというのは、真剣にみんな考えるところだと思いますので、まずは町会に参加している人たちの防災とかそういうことではなくて、もうちょっと地域全体のことを考えたような取組みがあると、町会の方にすごく負荷がかかってしまうのかもしれませんけれども。","respondent":"柏原企画調整課長","answer":"ただ、いかんせんいろいろな、今でも加入率は６０％前後だというところがありますので、昨今、いろいろな住宅事情等も含めて、どのように進めるかというのは、町会の方々にさらに聞きながら進めていくというものです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"ネットとしては、ずっと町会はすごい大事で、私ももちろん町会には入っていますけれども、それ以外の人たちが増えているというその実態をまずは受け入れて、そこの人たちも意見を聞いたりするような形をまずはつくって、それから町会加入を進めていただきたいと思いますので、そのように今後考えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"あくつ副委員長","kind":"質問","question":"条例案を拝見させていただきまして、私も町会活動をさせていただいている人間として、もう一度改めてクローズアップしていくということは非常に大事なことだと思いますし、基本的には賛成なのですけれども、町会・自治会、２つ目に自治会というふうに並列してあるのですけれども、私の地元の地域というのは、品川区内で１０幾つある都営住宅のうち９つがある地域で。","respondent":"柏原企画調整課長","answer":"ただ、地域ごと、それから各町会・自治会ごとに個別の課題があったりということはありますので、この条例そのものが網羅的にそれを全部解消できるかどうかということはありますけれども、それぞれいろいろな課題があるということも承知しながら、区の支援。","id":"exchange-040"},{"speaker":"あくつ副委員長","kind":"意見","question":"ありがとうございました。問題点は把握していただいているというところでありましたので、条例案の中に書き込めなくても、運用に当たっては、ぜひそういったところの、本当に自治会として成り立っていけないという状況もありますので、そこのところも勘案した運用をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"あべ委員","kind":"意見","question":"すみません、１点だけ、さっき言い忘れてしまったので。名称なのですけれども、活性化とつくと何となく、今活性していないみたいに見えてしまって、ちょっとどうかなと。これ、「活動推進条例」だけで十分ではないかと私は思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]},{"id":"topic-04","title":"品川区シティプロモーション","agenda":"品川区シティプロモーション","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"確認ですけれども、今回この規模で認定事業ということですが、今後、来年度以降、どのような形で考えていらっしゃるか教えてください。","respondent":"中元広報広聴課長","answer":"今回初めてこういう形で認定事業を募集をさせていただいたのですが、なかなか内容的にもまだまだ、もう少し詰めればもっと事業化できそうなものもございましたので、現段階では来年度につきましても、今年度と同規模の予算要求をする予定です。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは企業がご自分の業務にかかわることでイベントを組まれて、そこに区の税金が１５０万円入っていくというのは、ちょっとほかのものと毛色が違うみたいに感じるのですが、現段階では、そんなに品川区というのはこういうキャラクター系と言ったらいいのですか、グッズ系のものが特に産業として集積しているわけでも、例えば池袋みたいにそれを目指して全国から人が来てというわけでもない中で。","respondent":"中元広報広聴課長","answer":"第１回目としては、男性も含めてですが、少し若い女性の方の注目度が高いイベントを少し入れてみたいというところがあったということと、また、地元への連携というところも考えられているというところで採用をさせていただきました。","id":"exchange-044"},{"speaker":"あべ委員","kind":"意見","question":"今回、これを採択して事業に対して助成を出すというだけではなくて、ぜひ振り返っていただいて、どういう効果があったのか。あるいは、やったことを今後どうつなげていくかという、育てたり、メンテナンスの部分も含めて、事業の助成金を生かしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"今回、７つの事業が採択されたということですけれども、この採択数というのか、数というのか、そういうものはどういうことで決まっているのか、そこを伺いたいのと、年１回ということなのでしょうか。それと、助成対象経費ですけれども、いわゆる人件費に当たる部分はないという考えなのか、この助成対象額がどういうふうな考えで対象としているのか、そこも伺いたいと思います。","respondent":"中元広報広聴課長","answer":"どの程度分けて募集するとか、その辺のところも今回実施がどの程度行われるかの実施状況を見ながら検討していきたいと考えています。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１つ伺いたいのですけれども、品川区の都市イメージおよび地域の魅力の発信につながる事業というと、随分枠が広く、ある意味、品川で活動すれば何らかのことを伝えたい、知ってもらいたいと思ってそれぞれが活動しているわけで、その媒体が、スポーツであることもあるだろうし、趣味の世界であっても規模が大きくなってくれば、随分また技術もスキルも魅力も上がってくるかもしれないし。","respondent":"中元広報広聴課長","answer":"認定事業として区から認定する以上は、やはり収支見込みや数値目標をきちんとしていただいて、実施体制とか実施能力のところも今後も含めて見するというところはあります。","id":"exchange-047"},{"speaker":"あくつ副委員長","kind":"質問","question":"キャッチコピーが決定をしたということで、今後１.(2)で、ロゴマークを作成して、品川区の魅力発信を行う際に広く活用していく。これが品川区との関係性は深いと思うのですが、ＰＲというところで、例えば会場にどれぐらい区外の方がいらっしゃるのかとか、そこら辺の情報があれば、認定の中で、多分判断基準の中であったのではないかと思うのですけれども、教えてください。","respondent":"中元広報広聴課長","answer":"１点目のロゴデザインですが、委託事業で、今年度、電通のほうに委託をしていますので、ロゴデザインはやはりプロのデザイナーの方に何案かつくっていただいて、それをもとに区のほうで決定していきたいと考えています。","id":"exchange-048"},{"speaker":"あくつ副委員長","kind":"意見","question":"キャッチコピーなのですけれども、前回このキャッチコピーを我々のところに６案、絞り込んだものを見せていただいたことがあったのですが、だから、今回出て、なるほどなというところもあるのですけれども、本当に最後はセンスの問題なので、できればロゴマークもある程度絞り込んだ段階で見せていただいたほうが後々いいのではないかというところもありますので、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]},{"id":"topic-05","title":"マイナンバー制度の進捗状況","agenda":"マイナンバー制度の進捗状況","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"ということは、今の３４人というのは、９８人以外の方が３４人という意味なのでしょうか。","respondent":"仁平情報推進課長","answer":"支援措置以外の方で初めてご相談を受けて、３４名の方は区に住民票を有する方ということで、ご相談を受けた上で居所登録を行ったというものです。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問・要望","question":"改めてそれなりの数字があるなと思うのと、それから把握されていない方で３４人、多分これ、必要な方の全部ではないのだろうと思うので、こちらの登録期間は９月２５日でまさに本日までとなっているのですけれども、今日以降といいますか、明日以降といいますか、今後ご相談があった場合も何らかの対応は考えていただけると考えてよろしいのでしょうか。ぜひそうしていただきたいと思いますが。","respondent":"仁平情報推進課長","answer":"そうすると、区のほうに最終的には通知カードが戻ってくることになりますけれども、この場合には、例えば転居しているのかどうか調べて対応するとか、もしなければ。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"今のお答えの続きみたいな感じなのですけれども、ＤＶ被害者の方で一番困ることが想定されるのは、この自分が届けなければいけないという情報を得られない状況で、住民票がもともとの家にある方ではないかと思うのですけれども、そこに届いてしまうのでしょうかというのが１点。","respondent":"仁平情報推進課長","answer":"その後、区のほうで３ヶ月程度保管ということになるのですけれども、その間に自分の分がどうなっているのかということでお問い合わせがあれば別の対応ということになるというような戸籍住民課の話でした。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"その数を大体どれくらい、何％とか、そういう見込みでいらっしゃるか、それを伺いたいのですけれども。戻ってきてしまう数。","respondent":"仁平情報推進課長","answer":"全区民の中で、大体郵送物を出しますと、ほかの事例を挙げますと、１％となりますので、１万通ぐらいは戻るのではないかというような、そういう見込みを立てています。２０万世帯ぐらいになりますので、そのうちの１万世帯ぐらいということを見込んでいるということです。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問","question":"やむを得ない理由で受け取ることができない方は申請されているということですけれども、自分のカードはいわゆる世帯主には郵送されないということでよいのか、そこを１点伺いたいのと、あと、この通知カードというのに自分の１１桁の番号があるわけですけれども、これは持ち歩くものなのですか、それとも家で大事に保管しておくものなのですか。","respondent":"仁平情報推進課長","answer":"１点目の居所情報を登録された方なのですけれども、通知カードのほうは世帯単位で発送になりますが、情報を登録された方は、その登録された先の変更先といいますか、登録された住所のほうに通知カードを特別に発送するというような対応になります。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"既に与党内からも反対の声が上がっていますので、今、迷走しているわけですけれども、そこが今どういう状況なのか伺いたいということと、自分の１１桁の番号が自分の管理も、また中小企業や零細企業にとっての管理もとても負担になってくると思うのですけれども、そこも伺いたいと思います。","respondent":"仁平情報推進課長","answer":"事業者における番号の扱いですけれども、これは税関係の法定調書等に従業員の個人番号を記載したりということが法令で義務づけられてきてしまいますので、この辺の管理については、各事業者のほうで安全に管理していただくことになるかと思います。","id":"exchange-055"},{"speaker":"あくつ副委員長","kind":"質問","question":"コールセンターをつくっていただいたということなのですけれども、９月１日から開設をされているということなのですが、現在、３週間から４週間、一月はまだ経っていないですけれども、ＦＡＱというのでしょうか、区民の方からどのようなお問い合わせが多いのか、何件ぐらいあったのかということがわかればで結構ですけれども、そこら辺を教えていただければと思います。","respondent":"仁平情報推進課長","answer":"個人番号カードの取扱い、それと同じように、居所情報関係の相談ということでの受付も多いです。主立ったところは以上です。","id":"exchange-056"}]},{"id":"topic-06","title":"東品川一丁目付近外下水道管再構築工事請負契約","agenda":"東品川一丁目付近外下水道管再構築工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"次の工事もそうなのですけれども、最近工事が多くて、必要な工事だとは思いますけれども、全体のボリュームからすると、今どれぐらいまで進んだところなのか。どれぐらいかかるというか、全体のボリュームがわかれば教えていただければと思います。全体というのは品川区内ということです。","respondent":"立川経理課長","answer":"その辺の資料を持ち合わせてございませんので、回答については控えします。","id":"exchange-057"}]},{"id":"topic-07","title":"北品川二、五丁目付近下水道管再構築工事請負契約","agenda":"北品川二、五丁目付近下水道管再構築工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"これは北品川二丁目の工事と五丁目の工事２件を取り扱って契約ならびに工事をされる内容と思うのですけれども、この２件を１つのものと扱っているのは、距離的に近いからということなのでしょうか。","respondent":"立川経理課長","answer":"詳細については聞いていないのですけれども、いわゆる工事金額であるとか、工期であるとか、その辺のバランスを東京都と協議しまして、合体できる工事については合体して発注しているというふうに聞いているものです。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"この前のことは聞いてみないとわからないのですけれども、この北品川二丁目と、むしろ１つ目の東品川一丁目のほうが現場が近いので、一緒にするのだったらこちらなのかと思ったのですが、工事内容の話なのか、その他にいろいろな事情があるのか、もしおわかりだったらご回答を、地理的な問題だけではないのですか。","respondent":"立川経理課長","answer":"委員ご指摘のとおり、地理的な問題だけではなくて、やはり工期とか周りの地域の状況、そういったものを勘案して、地域について組み合わせをしているというところだと思います。","id":"exchange-059"}]},{"id":"topic-08","title":"品川区施工能力等審査型総合評価方式の対象工事の拡大および評価項目の配点変更","agenda":"品川区施工能力等審査型総合評価方式の対象工事の拡大および評価項目の配点変更","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"地元業者ということで、適用工事価格が引き下げられたことも一定の効果があるだろうと思います。質問なのですけれども、これ０.５から今回１.５点に上がって、この１.５という数字、どのように最終的にこの数字に持ってこられたのか。０.５から１.０でもなく、２.０でもなく、１.５と考えられた何かロジックがあると思うのですけれども、そこを教えていただければと思います。","respondent":"立川経理課長","answer":"今回、１点から３点に引き上げるところで、その割合については変更しないでそのまま持ってくるということで、１.５点と１.５点ということになりました。","id":"exchange-060"},{"speaker":"須貝委員","kind":"意見","question":"というのは、こういうふうに押さえられてしまうと、新しいところでそれなりに努力して安い工事価格で入札しようとしても、なかなかとれない。今回の場合は、加点をこういうふうに上げるということは、どうしても新規業者にとって不利ではないかと思うのですが、地域の業者を育成するという意味はよくわかるのです、その辺はどういうふうに考えていらっしゃいますか。","respondent":"立川経理課長","answer":"委員ご指摘のございました点ですが、まず、総合評価方式の適用というのは、現状で大体対象となる工事につきましては、年間で６０件前後でございまして、その全てを適用するということではなくて、徐々に増やしていくということは考えておりますけれども。","id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、今度、実績がないからと始まっていて、さらに努力して、ほかのところでは当たり前のように工事をやって、入札して落札もしているけれども、こういうハードルを上げられてしまうと、経験があって、実績もあっても、なかなか品川区に入ってくるとこういう加点云々で、ゲタと言ったらおかしいですけれども、ハードルがある限り。","respondent":"立川経理課長","answer":"実際、入札におきまして申込要件というのは、品川区の公共工事の過去５年間において、どれぐらいの受注実績があるかというところを一番に考え、そこから申込みができるできないということがあって、そういった事業者のために、そういった案件以外の少額の工事ですけれども。","id":"exchange-062"},{"speaker":"本多委員","kind":"質問","question":"それが１個目にあるのですけれども、それで、あえて区政協力している実績のある工事事業者が進めていくに当たって、ここに書いてある理由に「安定的な品質の確保と、不良不適格企業の参入防止」というところで、安かろう悪かろうという、そういったものがないように何か工夫をしてほしいというのが我々が常に言ってきたことで、そういった意味で、この総合評価方式のポイントを上げたり。","respondent":"立川経理課長","answer":"実際の災害対応の実績ですけれども、区のほうで水防本部等を設置しますと、建設防災協議会等に待機をしていただきまして、実際、各地域の見回りというか、点検というか、そういったところもやっていただいておりまして、もし崖が崩れたとか。","id":"exchange-063"},{"speaker":"本多委員","kind":"質問","question":"経理課長だから、もうそれ以上あまり聞きたくないのですけれども、年間どのくらいあるかだけ、ざっとわからないですか。多いか少ないか。","respondent":"立川経理課長","answer":"水防本部が立ち上がるたびにお願いしています。","id":"exchange-064"},{"speaker":"あくつ副委員長","kind":"質問","question":"昨年の行革のまとめのときにもお願いをさせていただいて、地元のお声を反映させていただいた中でこういった形で、今回、総務委員会に報告いただいたことは非常に評価すべきところだと思います。１年で考えたときに、総合評価方式を適用した工事はどれぐらい出ているでしょうか。","respondent":"立川経理課長","answer":"件数の根拠ですが、２３区の状況を見ますと、総合評価方式で工事を発注している件数が大体平均しますと２０件ということで、まずはその平均的なレベルを目標に実施していきたいということで、この件数にしています。","id":"exchange-065"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"具体的な数を今日初めて伺いまして、現状で発注のものも含めると１５件、２０件を目指していくということで、６０件のうち２０件ということで、これが本格だというふうに受けとめましたので、わかりました。ぜひ拡大をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]},{"id":"topic-09","title":"地方税の賦課及び徴収に関する事務に係る特定個人情報保護評価の実施結果","agenda":"地方税の賦課及び徴収に関する事務に係る特定個人情報保護評価の実施結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"区民公募を実施して、件数が１件ということですけれども、これで区民公募を実施したと言えるのか、そこを伺いたいと思います。","respondent":"黒田税務課長","answer":"いただきました意見はお一人からですが、品川区のホームページのこの件に関するパブリックコメントのアクセス件数を見ますと、７月１日から７月３０日までパブリックコメントを実施しまして、７月の月間アクセス数ということですと、約３,０００件のアクセスがあったですので。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"アクセスは３,０００件あったかもしれませんが、区民意見公募をこれで実施したと言えるのかというふうに、そこを伺いたいと思います。反省すべきことがあれば、それは率直にしっかり次回につなげていっていただきたい、もちろんそういう思いですけれども。","respondent":"黒田税務課長","answer":"この区民意見公募につきましては、区で行っておりますパブリックコメントの手続きに沿って行っておりますので、手続きに沿って実施したというふうに考えています。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"回答が１件というこの実態から見れば、とても実施したというふうには私は言えないと思います。それと、このパブコメの制度そのものですけれども、ここに回答原案とありますけれども、これは１件のこの方に、区はこういうふうに考えておりますという返事を出すのか、そこを伺いたいと思います。","respondent":"黒田税務課長","answer":"パブリックコメントの意見の回答原案につきましては、ホームページにパブリックコメントのページがございまして、そちらのほうに回答を記載するのと、広報紙のほうで回答を記載いたしますので、この方だけに回答するということではなくて、質問の要旨と回答について。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"お寄せいただいた意見に対する区の見解もご本人に直接伝えることもない、また説明会を開くこともない、資料は区政資料コーナーとか、閲覧はできるけれども配布はしない等々、今回の１件ということ、今回に限ったことでもないですけれども、やっぱり例年少ない状況は真摯に受けとめて制度を大きく改善して、形だけの区民意見公募にならないように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問","question":"私は、２ページ目のその他の意見というのは、第三者点検をしていただいて、この修正意見のほかにという、その他の意見というのはどういう扱いなのですか。これで何か変わるということはないのでしょうか。その他と、この修正意見の扱いの違いと申しますか、その点、教えてください。","respondent":"黒田税務課長","answer":"2)の情報漏えいに対する職員の教育についてというのは、これは評価書に記載はあるのですが、午前中の委員会の中でも議論がありました、情報に対する職員のヒューマンエラーをなくしていくためには、継続的な教育でありますとか、職員の理解を深めるために、これについては。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、手続きとしてやったからいいということではなく、いかに多くの人から意見をもらおうかというその姿勢で、その１つがパブリックコメントという手法ですねという、そういう感じだったのです。最初の質問、これ、反映されていると考えていいのですか。","respondent":"黒田税務課長","answer":"１点目のその他の意見について、今後の反映方法ですが、評価書に何か記述を行うということではなくて、例えばセキュリティにつきましては職員の研修等を強化月間等に全職員に行っているというところもありますし、そういった中で。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、私の先ほどの意見は、手続きに則ったからこれで終わりだということではない姿勢で今後のものをとっていただきたいということを申し上げましたので、そのことをぜひ踏まえて、今後いろいろ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"あべ委員","kind":"提案","question":"もちろん、しくみとしてパブコメをとることになっているので、それはパブコメはこういう形でとっていただきたいのですけれども、むしろセカンドオピニオン的な、専門性がある方々に向かってご意見を伺ってみるというようなことも、この先でも何でもいいんですけれどもできるのではないだろうか、特に品川区というのは情報系の企業も集積していますし、また。","respondent":"黒田税務課長","answer":"パブリックコメントではございませんが、今回はしくみの中で第三者点検という中で、委員の中に情報システムの専門家がお二人おりまして、１名の方は国の内閣府のセキュリティに関する審議会の委員もされている方という意味では。","id":"exchange-074"},{"speaker":"あべ委員","kind":"提案","question":"だから、今回の件も含めてなのですけれども、あるいは今後、情報化というものについては、いろいろな方がいろいろ細かい分野でいろいろな提案をされているようで、それが活力になっているような部分が大きいと思いますので、今後、そういう一般の区民に対してお話を聞くだけではなくて、技術系のものについて、そういった団体なり。","respondent":"黒田税務課長","answer":"今回、特にこの地方税のシステムにつきましては、ＬＧＷＡＮと呼ばれる地方の共生ネットワークという意味で、各自治体をつなぐようなシステムに乗っておりますので、公開されていないようなセキュリティ情報も中にはという中では。","id":"exchange-075"},{"speaker":"あべ委員","kind":"質問・要望","question":"表に出してはいけないものを出して議会が検討させてという話は全然していなくて、公開にかけているものも別に出していいものだけしか出していないわけですから、それ以上のことを言っているわけではないので、ただ、こういう難しい内容については、パブリックコメントと言ってただ投げるだけでは、なかなか答えに結びつかないのかというところから伺ってみましたので。","respondent":"黒田税務課長","answer":"パブリックコメントについては、委員ご指摘のとおり、非公開情報を出しているというわけではございませんが、地方税の賦課及び徴収に関する事務と申しますと、情報セキュリティ対策をする部分と、税を賦課、徴収するという事務の中で。","id":"exchange-076"},{"speaker":"あべ委員","kind":"提案","question":"なぜそんなふうになったのか。こういうお答えというのは、普通よりは詳しい方くらいからしかお答えは返ってきようがないわけですから、そういうところもどうですかというご提案を差し上げているので、別にそれ以上のものを、パブコメ以上のものを出して、それを何とかしろとか言っているわけではないので、そこはもうご理解いただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"大沢委員","kind":"確認","question":"今やりとりを聞いていると、行政側の肩を持つわけではないのですけれども、瑕疵があるように聞こえるのですけれども、今、課長に確認をさせてもらいますけれども、これは２番のところの区民意見公募手続云々という国のフォーマットに基づいてこれは行ったということでいいわけですね。","respondent":"黒田税務課長","answer":"国のフォーマットに様式を定めまして行ったものです。","id":"exchange-078"},{"speaker":"大沢委員","kind":"意見","question":"そうなると、規則に従いながら行った。そこの中でたまたま専門的知見を要する、これを見ても地方税の賦課及び徴収に関する事務に係る、これはどう見ても普通の一般的な区民の方は、こんな長い難しい単語を並べられたのでは、パブリックコメントも集まるわけがないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"大沢委員","kind":"質問","question":"だから、専門的、確かに国のフォーマットに則ってパブコメを行ったということだけれども、これは自治体の裁量でこういう難しいものに対しては、パブコメを行わずして、今、どなたか委員が言ったように、然るべき知見を持った方たちに投げて意見を集約することはできないのですか。","respondent":"黒田税務課長","answer":"今回の件の中では、パブリックコメントという国民の意見聴取という部分と、専門的見地という二本立てで点検を行っておりますので、この中で特定個人情報保護評価について担保しているというものです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"規則に則ってやって１件しかない云々というような文句みたいなものが出ているから、それはいかがなものかという、規則に則ってやっていることはやっているわけですから、その行動については云々ということは、僕はそういう意見をするべきではないと思う。","respondent":"黒田税務課長","answer":"一応定めになっておりますのは、広く国民の意見を求めるものというような法に記載のあるところで、その中で区のパブリックコメントという手続きに則って行いまして、先ほど、あべ委員からもご指摘ありましたが、意見をいただいた方が全く普通の一般区民かどうかというのは。","id":"exchange-081"}]},{"id":"topic-10","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"３ページ、７２か月分というのが、７２か月というと６年、私は債権の放棄はこれは妥当で仕方がないというふうに思います。理由なのですけれども、民法が変わったのでしたか。時効のことは、３ページの１番目は時効は関係ないのでしょうか。家賃は１０年ぐらいですか。なぜこの区切りでこうなのかということを教えてください。","respondent":"福島会計管理者","answer":"ただ、難しいところは、高齢者住宅は一度入ってしまうとなかなか出すことが難しいということで、こうなってしまったというふうに言っておりました。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問・要望","question":"時効が途中中断したりしたということですね、それはわかりました。それはわかったのですけれども、後半の、やっぱりやむを得ないし、退去を迫るというよりできること、これは総務委員会から外れるかもしれませんけれども、何か別の保護のあり方を検討するとか、アドバイスするとか、そちらの方向に私としては行っていただきたいということを意見として申し述べて、了解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"あべ委員","kind":"意見","question":"今の件なのですけれども、著しい困窮状態の８３歳の方、退去していただいたということで、あまりにも品川区は冷たい区のように見えるのですけれども、実際には何か別の形で出ていった、ただ８３歳の困窮した方を家の外に放り出してしまったわけではないですよね。きちんとそこをご説明いただかないと、後で議事録を読んでびっくりしますから。","respondent":"福島会計管理者","answer":"最終的には、平成２５年２月２８日に長男のところに、長男もある区で精神疾患で生活保護を受けているのですけれども、そこで都営住宅に同居したという形で決着はついたものです。","id":"exchange-084"},{"speaker":"あべ委員","kind":"意見","question":"いろいろご苦労もあったとは思うのですけれども、できるだけ年数が経たないうちに別の制度につなげてあげることも大切なのだと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-11","title":"八潮高校での出前授業・模擬選挙の実施","agenda":"八潮高校での出前授業・模擬選挙の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどは失礼いたしました。職員というか、そういう積み上げから出てきたのか、そこを伺いたいと思います。ただ、学校も学校で今いろいろ忙しいですから、学校との調整にはなってくると思うのですけれども、どれぐらいの時間、１時間目、２時間目、３時間目、どれぐらいの単元でやるのか、少しそこの概要を教えていただきたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"そのような形で、いろいろと各小・中学校、高校によって、授業時数、どれぐらいとれるのかとか、学校との打ち合わせの中でいろいろとカリキュラムを考えながら実施しているというところが実情です。","id":"exchange-086"},{"speaker":"あべ委員","kind":"質問","question":"今の授業の内容についてもう少し伺いたいのですけれども、これ、そもそもスタンダードのカリキュラムがあってやっているのかどうなのか。それから、実際に授業をされているのは、選管の職員の皆様なのでしょうか。明るい選挙の方々とも連携してということだったのですが、教育委員会との関係は、どのような体制で実施をされているのかということを教えてください。","respondent":"工藤選挙管理委員会事務局長","answer":"小・中学校でやる場合の教育委員会との連携ですけれども、そちらのほうにつきましても、いろいろと私どものほうでも、校長会等でこのようなカリキュラムを用意できるというお話をさせていただきまして、いろいろと小・中学校でもカリキュラム等が入っていまして。","id":"exchange-087"},{"speaker":"あべ委員","kind":"意見","question":"そういった意味では、ぜひ学校の先生方も交えながら、この授業の中で何を学んでほしいかということも含めて、これからだと思いますけれども、いい授業にしていっていただければと思います。ぜひ制度が始まるまでには全校で経験できるような形で積極的に教育委員会のほうと進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問","question":"一度実施された学校の先生方の評価というか、そういうことで、これ、ある学校が１学年だけやってもあまり意味がないような、継続ということが必要なのではないかと思いますが、その辺の学校側の反応などはいかがでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"その結果としまして、数問設問を入れましていろいろとアンケートをやったところですけれども、例といたしまして「今後、あなたは投票へ行こうと思いますか」という設問には、約５８％の方が行ってみようという話で出ております。","id":"exchange-089"}]},{"id":"topic-12","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"昨日述べたとおりなのですけれども、答弁の中で区施設のあり方を検討するというふうに聞こえたのですけれども、今、新しい計画を作ろうとしているのか、今の計画に何か見直しを行っているのか、要するに、区施設のあり方を検討とは何か、ご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"資料はご用意していないのですが、今後の施設のあり方とか有効活用の検討というところで、１つは、きっかけといいますか、今、総合戦略で人口の推計等をやっているところですけれども、今後の人口の構成であるとか、そういったところに変化が予測されるといったところから。","id":"exchange-090"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ。その総合管理計画の策定準備に今入っているということですけれども、完成、発表までのスケジュール感、見通し、また議会への報告、段取り、スケジュールを、そこだけご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"来年度からは、実際に中身の検討というところに入っていきたいと考えています。一定程度、外部の方も入っていただく中での、策定委員会という名前になるかどうかはあれですけれども、検討会形式をとれればというふうには思ってあります。","id":"exchange-091"}]},{"id":"topic-13","title":"総務委員会を再開いたします。 それでは、行政視察","agenda":"総務委員会を再開いたします。 それでは、行政視察","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"それぞれ非常に興味深い視察で楽しみなのですけれども、北九州市のフィルム・コミッション、これも読んでいると、例えばこれまで１７０本ぐらい映画、ドラマがあって、それを見に行く私たち品川区ではかなりいろいろな撮影が既に行われている風景を目にしますが、品川区として、そういったテレビ、ドラマ、映画等々の撮影がどのくらい行われているのかというのは、そもそも把握をされているのでしょうか。","respondent":"中山企画部長","answer":"ただ、公園などで撮影の使用許可を出していたりとか、そういうものを足し込むと、大小コマーシャルなども入れると年間数十本はあるようですが、正確な数は把握しておりませんので、今のことを含めて、どういう形でそれぞれに、実は文化観光課などでもそういう点での把握は。","id":"exchange-092"},{"speaker":"あくつ副委員長","kind":"質問","question":"今のに関連して、本当におっしゃるとおりで把握をされていない。ただ、議会の図書館とかへ行くと、ロケ地のデータ集みたいなものが置いてあります。品川区ではどのくらいロケをやっているか、有名なところです。ＣＭ等までどこまで載っているかわかりませんけれども、そうすると、すごい数がデータとしてあるので、ある意味、放っておいても来るのです、誘致などしなくても来るわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"あべ委員","kind":"意見","question":"誘致をするというより、今来ているものをどう生かすかのほうが、多分、品川としては中心かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"あべ委員","kind":"質問","question":"そうですね。そういうことを勉強するほうが、今、先ですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"中塚委員","kind":"質問・要望","question":"皆さんご存じの北品川のゴジラにはじまり、たしか品川線の出入口、昔は何もない、あそこは結構撮影していて、小さい頃テレビで見ていても、あそこでまた刑事物をやっているとか、そういうのをよく見ていましたけれども、整理してみて、どこが一番使われているのか、逆にどこが一番求められているけれども、実はいろいろな行政の許可とか、申請とか、いろいろな手続きのところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"あべ委員","kind":"質問","question":"お店紹介とか、食べ歩きとかまで把握できないのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"あくつ副委員長","kind":"意見","question":"オープンデータですけれども、品川区も幾つかのオープンデータを出していると思うので、少なくともそれは我々の資料として、自分で調べてももちろんいいのですけれども、先ほど部長がおっしゃったような、そんなに変わらないぐらいのものは出して、利用できるものは、防災アプリをつくるためのものとか出ていると思うので、一応、委員としては情報を把握していきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問","question":"戻ってしまうのですけれども、フィルム・コミッションで、これ、北九州の場合は、経済効果が結構、それはスタッフとかが映画の撮影ということで滞留されるので、経済効果まで算定していらっしゃるのですけれども、例えば品川でテレビとなるとまたちょっと違って、そこから品川が映像を通して発信されるという意味では、もう既にあるかと思うのですが、それが経済効果まで結びつくような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"あくつ副委員長","kind":"意見","question":"歳入のところで、公園を借りたりすると、大体５００万円とか６００万円とか、そういうのはあるのですけれども、台東区のフィルム・コミッションなどだと、独自の試算をしていて、テレビにそうやって台東区が映る。そのことによってかなりの、何千万円単位の広告効果はあるという言い方はしています、何とも言えないですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"あくつ副委員長","kind":"質問","question":"フィルム・コミッションは全国でいっぱいありますけれども、休眠状態のものもいっぱいあるので、うまくいくところもあれば、失敗するところもある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"あくつ副委員長","kind":"意見","question":"見に行って、そのまま導入するというのは難しいと思うのですけれども、ただ、やっぱり何らかのヒントがあるのではないか。先ほど中塚委員もおっしゃっていたように、いたるところで撮影を見るので、それを何か資源として生かせないものかということは常々考えていますので、何かヒントがあればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問","question":"同じようにフィルム・コミッションなのですけれども、住民の理解がすごくあるというふうにさらっと書いていらっしゃるのですけれども、やっぱりそれなりの理解を得るような努力というか、そういうことがあったのではないかと思うのですけれども、私は以前住んでいたところでしょっちゅうテレビドラマの撮影に使われて、やっぱり住んでいる住民の交通、偉そうになってあれですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"あくつ副委員長","kind":"意見","question":"私も先に調べたので、やっぱりシティプロモーションという観点で言うと、シビックプライド、住民の誇りを醸成するためのシティプロモーションという１つの手段であって、映画撮影のボランティアに何千名という市民の方が登録されていて、映画の撮影等に駆り出されるのです。それでスタッフの方も非常にケアをするというところもあるので、やっぱり大歓迎なわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"あべ委員","kind":"意見","question":"難しいですよね。品川の場合は、しょっちゅう、許可を得ているのかどうかわからないのに通行止めにされてみたいな感じで、ちょっと不満もありますよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"あくつ副委員長","kind":"質問","question":"ロケーションはいいのですけれども、多分、アクセスがいいから品川を使うということは。許可もとらずにゲリラでバッとやってしまうということもあるのでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"本多委員","kind":"質問","question":"これ、予算はどうなっているのですか。経済効果がすごくわかりやすく書いてあるので、予算がどうなっているのか。行ってみて、この辺を調べて、成功例、失敗例、いろいろなところを参考にできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"大沢委員","kind":"質問","question":"この日々谷さんという方は、職員ですけれども、今回はお会いできるのでしょうか。北九州市の職員ですよね、この人。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":92389,"voices":278}},{"id":"h27-20150928-14","meetingId":"h27-cm09","date":"2015年9月28日","dateIso":"2015-09-28","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"幾つか指摘と質問ですけれども、民泊の件で、たまたまテレビでこの間放映されていましたけれども、これを進めることの中で、例えばごみ出しの問題とか、プライバシーの問題等々、民間のところを丸きりお借りをして、そこに海外の方が泊まることについては、それ自体は問題ないのですが、その様々なルールについて非常に問題があるという指摘があったので、確認しますけれども、旅館業法の特例の説明の中で。","respondent":"柏原企画調整課長、今井待機児童対策担当課長","answer":"そこは判断がなかなか難しいところではあるのですけれども、荷卸しのところでなかなか苦労されているというお話は聞いてありますので、もう少し、これはどういった形で進めたほうがいいのかというのは検討が必要だろうと考えています。都市公園を活用した保育所の設置に関してですけれども、今回第２回定例会の補正予算といたしまして、保育園整備の検討のための経費をご議決いただきまして、現在。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"それから荷卸しの件は、本当にハードルが高いことをわかりながら質問しているのですけれども、でも、どうしても、私たちのところで様々な相談を受ける中で、やはり納得できない方も一部いらっしゃるわけです。ただ、ここに言ってもどうしようもないことはわかるのだけれども。だから、今、課長は別な形とおっしゃったけれども、どういう形をお考えなのですか。","respondent":"柏原企画調整課長","answer":"具体的にどういう形が一番よろしいのかというのは、今の段階では難しいのですけれども、今回の国家戦略特区を使うという１つの考え方ということで出てまいりましたので、この形がよろしいのか、それとも、先ほども若干触れさせていただきましたけれども。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"提案","question":"オリンピック・パラリンピックもあるということも含めて考えていくと、１つの窓口ができたわけですから、ぜひ品川区におきましては、様々な形で提案をして実現を図っていただきますようお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"藤原委員","kind":"提案","question":"特に保育と福祉の問題で、６、７で、現実にこういうふうに２つ委員会のほうから出ているのですが、まずこれをどう所管としては捉えたかということをお伺いしたいのです。それと８、９で福祉、せっかく担当の課長が来ているので課長に答えていただきたいのですけれども、これもこの特区で提案しているのですけれども、現実問題、それとメリット・デメリット、行政側はどう捉えているのかお伺いしたいです。","respondent":"今井待機児童対策担当課長、大串福祉計画課長、竹田保育課長","answer":"公園を占用するということは、一方では、公園の多目的な利用と共存していかなければいけませんので、広さや、待機児童の多い地域も含めて。そうした中で、今後整備予定である平塚橋、上大崎、あるいは昨年１２月にオープンしました杜松。ここにおきましても、保育士登録の欠格事項に外国人は含まれておりません。特別区の各区の実施する保育士採用試験にも受験可能となっておる現状です。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"提案","question":"それからあと、この４番のところ、今一応国のほうへ提案済みと。台東、墨田は国と、品川は東京都とやっているというお話が前にあったのですけれども、その辺の今の現状というのですかね、その辺を教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"台東、墨田とは、改めて具体的に何かできないかということで今後話をしていきたいと考えているところです。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました、それでは１点だけ。いわゆる旅館組合ですね、そうすると、今のお話だと、あまり積極的ではないけれども、先ほどのいろいろな細かい一定の条件が、組合から区のほうに、こういったものをきちんとしてくれるならば仕方ないかなとなっていると受けとめたのですが、１、２で結構なのですが、大体どのようなことが出ているのかわかれば教えてください。","respondent":"柏原企画調整課長","answer":"それを、今回の旅館業法の特例は１週間、７日まで短くしています。ですから、７日以内は旅館業法に入るのですけれども、それを超えると旅館業法から外れるという規制の緩和なのですけれども、その日数の部分についてもう少し弾力的にできないか。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"それと特養のところですけれども、先ほど随分区のお考えも出てきたのですけれども、終の住みかでありますので、本人の尊厳が守れるという意味では個室であるべきだとは思うのですが、先ほど補助金との関係のご説明が多かったのですけれども、本人の尊厳というか、特養ホームのあり方としての個室というところで区がどう考えているのか、そこら辺の観点からもう少しお伺いしたいと思います。課題があると。","respondent":"今井待機児童対策担当課長、大串福祉計画課長、竹田保育課長、中村都市計画課長","answer":"それ以外のものは、児童福祉の最低基準では決められておりますけれども、参酌基準ということになっておりますので。介護人材におきましては、処遇改善加算等々入った形で、その辺についても改善を一定程度行いながら、働きやすい職場。保育の外国人の活用の件ですが、先ほどご説明したとおり、外国人の方にも一定程度広げられている。一方で、一定の課題もあるのが現状です。特に接道の２ｍですけれども、この２ｍの幅が最低必要だというのには１つ理由がありまして、主に経路を。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、都市公園を活用した保育所のところですが、５,０００m2以上のところで現在区としては検討するということでしたが、いろいろな課題も先ほどお話しされました、あると思います。ここでお伺いしたいのは、５,０００m2以上で具体的に実際に区が検討する対象になっている公園を挙げていただきたいのが１つ質問です、５,０００m2以上の公園がどこなのかということです。","respondent":"今井待機児童対策担当課長、大串福祉計画課長","answer":"区立全園の中で、地域需要とバランスを見ながら検討しておりますので、はっきり言えば、一定の広さがあって、一定の広場がある、そういう公園を検討しておりますので、具体的な名称は今申し上げる段階にはございません。ただ、なかなかその導入におきましてはいろいろな問題があることも、先ほどの保育の人材と同じような形で問題は持っていると認識しております。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、水辺のことで、５番の水辺観光ルート開拓に向けた憩いの場の設置ということで、横線が並んでいますが、先ほどの説明では、運河には建築物は建てられないということで、天王洲のT.Y. HARBORは運河ではなくて船として活用しているということで、ああいう形でできているという話でした。","respondent":"柏原企画調整課長","answer":"いずれにしても、１つの手法として、例示としてお話しさせていただきましたけれども、いろいろなやり方があるのではというのは、今後も検討していきたいと思います。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"民泊について伺いたいのですが、今現在どういう課題があると思われているのか。先ほど関係団体との意見交換もしているというところで、ぜひ、そういった住民の方、マンションなどでそういった民泊が行われているようなところもあるかと思うので、そういった住民の方の声を聞いていただきたいなというところもあるので、そういった方々との意見交換とかというところは考えているのかどうか、教えてください。","respondent":"柏原企画調整課長","answer":"実際、やりたいという事業者がいらっしゃいますので、そういった方々とも話をしながら、そういった地域の方々とのお話し合いも進めていかなくてはいけないと考えています。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問・要望","question":"まさにインターネットを利用した宿泊というところの規制という部分は、ある程度しっかりやっていくことで、例えばマンションに住んでいる方の又貸しなどという話もあって、結構問題になっているという中で、そういうつもりで住んでいない方たちが、そういった外国人が連日入ってきて、安全上の不安も思われていると思いますし、品川区もそういった意味ではかなり利用が多いのも現状なのでそういった部分。","respondent":"柏原企画調整課長","answer":"委員おっしゃっていただいたように、そういった形でいろいろな方が入ってくることへの不安、それからいろいろな課題が出てくると思いますので、条例化するに当たっても、丁寧な形で話をしながら進めていきたいと思ってあります。","id":"exchange-011"},{"speaker":"横山委員","kind":"提案","question":"１点だけお願いいたします。旅客不定期航路事業における２点間運行の許可のところで、先ほど説明の中に、初めにアジアヘッドクォーターを使えないかという話が出ていたというのがございました。こちらはなぜ、国家戦略特区ではなくてアジアヘッドクォーターをまず使えないかというご提案があったのか、もし情報がありましたら教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"それは、アジアヘッドクォーターの中で、羽田とお台場のところに不定期航路が１路線だけ認められておりまして、そういう広がりで活用したらどうだろうかというお話があったのですけれども、先ほども申しましたように、アジアヘッドクォーターのほうは。","id":"exchange-012"},{"speaker":"横山委員","kind":"意見","question":"それが、今回は目的が違ったりエリアのほうが該当していないので、国家戦略特区ということで、現在、平成２７年６月に提出されていて、今後のスケジュールと言いますか、実際、アジアヘッドクォーターのほうでは認められていますので、進めていただいていると思うのですが、目途と言いますか、今後どのあたりで動きがさらに加速してくるのかなという、感触のほうをお聞かせいただけたらと思います。","respondent":"柏原企画調整課長","answer":"アジアヘッドクォーターの関係ですけれども、アジアヘッドクォーターを担当している東京都の部局と話はしておるのですが、先ほど言った理由からなかなか、あまり積極的な回答はいただいていないという実情があります。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"様々にご説明ありがとうあります。１点、水辺観光ルート、確認をさせていただきたいのですが、今回、台東区、秋葉原から羽田空港の、このシルバーウィークに試運転がされて、この運河沿いを走る船に、私もチケットがとれましたので乗ってみました。非常に良かったです。","respondent":"柏原企画調整課長","answer":"残念ながら、品川区に関しては、区としてはこの件に関しては関与していないのが現状です。ただ、天王洲の事業者が入っていただいていますので、今後、その事業者と連携をとりながら進めていければと思ってあります。","id":"exchange-014"},{"speaker":"のだて委員","kind":"提案","question":"今、様々いろいろなお話ありましたけれども、この特区の制度の活用、しくみとして、今、１４個挙がっていますけれども、どれが適当なのかということをお聞きしたいのですけれども、既にこの網かけしているところは提案しているところなのでいいと思います。提案済みのものもありますから、これもできるということだと思いますけれども、ほかのところについてお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"４番、５番にかかわるところ、特に４番に関しては、我々としても提案しておりますので、特区として進めていきたいと思ってあります。","id":"exchange-015"},{"speaker":"のだて委員","kind":"提案","question":"この場での議論だというお話でしたけれども、そうすると、私は商店街アーケードの更新の件でご提案させていただいたのですけれども、障壁となる法令はないと書いてありますけれども、自治体での話し合いだというお話でしたけれども、そうすると緩和することは可能なのか、お聞かせください。","respondent":"柏原企画調整課長","answer":"そういった意味で申し上げますと、国家戦略特区は、冒頭申し上げたように、国の法令、制度を規制緩和することによって物事が進められるというのが大前提でありますので、そういった形で、法令としては障壁になっているものはないですので、逆に規制緩和と言いますか。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"私からは、先ほどからいろいろな委員から質問がありましたけれども、空き家を活用した短期宿泊滞在ということで、今、旅館組合の方といろいろお話をされているということと、あと大阪市が先行して条例案を出したということなのですが、その結果を見て今後進められていくと思うのですが、その組合とのお話し合いをしている中に。","respondent":"柏原企画調整課長","answer":"ですので、組合のほうから出てくるであろうご意見、それから実際やろうとしている事業者の考え方、その辺のマッチングと言いますか調整は、我々行政の仕事であろうと思ってあります。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"ぜひ今後とも進めていただけたらと思います。最後に立入検査に関してなのですけれども、これは旅館業法に入っているのでしょうか。無知ですみませんけれども、お願いしたいと思います。","respondent":"柏原企画調整課長","answer":"当初の旅館業法の特例のほうで言うと、その辺があまりないような枠組みだったものですから、一定程度の部分については立入調査・検査が必要ではないかという厚生労働省の見解が出たところでございまして、そういった枠組みを入れながらの条例化になるであろうと考えています。","id":"exchange-018"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"幾つか伺いたいと思います。ところが、今度の、短期的な、先ほども言った民泊とは言ってはいけないよという部分は、短期的なとか、いろいろなそういう部分でいくと、そこら辺がどうなるのかという部分があるわけです。大阪もどういうふうにしたのか私はわからないけれども、そこら辺のことも行政は一歩踏み込んでやると思われているのかどうか、そこら辺のところの考えを教えてください。","respondent":"柏原企画調整課長","answer":"もう一つは、区域です。エリアを決めるという考え方がありまして、例えばお隣の大田区あたりは、そういった方向を少し考えているのではないかという情報が若干入りつつあります。ですので、品川区の場合も、そのエリアという考え方も入れるかどうかを含めて、検討しています。","id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"言葉に気をつけて発言をしますが、大阪市が出してきた。区の全体の中でやっていくのだろうなとなると、果たしてそれがどういう形で進んでいくのかという疑問が大分あるのです。やりたいと言う人は、私もよく話しているから、彼のバイタリティだったらできるだろうと思うけれども、ここら辺のところの考え方をやはりきちんと整理したほうがいいような気がするのだけれども、もう一度考えを教えてください。","respondent":"中山企画部長","answer":"全体にかかわる話なのですが、国家戦略特区そのものは、ご説明もあったかもしれませんけれども、いわゆる民の実施主体がやりたいということについて、全国一律の規制によって障壁があるということについて、いろいろ分析して、メリット、また影響等も含めて。","id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"不定期航路はやっていただきたいと思いますが、もう一つ、今の話に反するような話になるかもしれないけれども、例えば運河などの休憩場所等の話、これはまず桟橋が第一に必要だと思うのです。桟橋があって、例えば日本丸だって山下公園で、固定係留するのだったら建築許可をとって、建築確認を出してやっているというものもあるわけです。この認識が一緒かどうかを聞きたい。","respondent":"柏原企画調整課長","answer":"ただ、かと言って、これだけ品川の場合は水辺があって、港湾という大きな壁がありますけれども、それがあるにしても、これだけあるところを活用しない手はないというのは、やはり考え方としてありますので、大きな課題ではありますけれども。","id":"exchange-021"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"幾つか伺いたいのは、先ほどの多床室の話をします。それが２割、３割いるのであれば、私は多床室があっていいと思います、そういう意味では。そういうのも私は押し進めるべきだと思っているけれども、そういう意味の中で、これからの多床室を含めた特養のあり方、そうすると、１回そういうアンケートをとってみたらいい、もしやるなら。そこについて、どういうふうにお考えがあるのか聞きたい。","respondent":"大串福祉計画課長","answer":"その後といったところになってこようかと思いますけれども、そうした中では、先ほどご提案あったような、地域密着型の小規模な特養、こういったものも検討の視野に入れておりますし、多床室の関係につきましても、十分検討させていただければと考えているところです。","id":"exchange-022"}]},{"id":"topic-02","title":"公有地・跡地活用に関すること","agenda":"公有地・跡地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"２つ提案したいのですが、１つ目は、この土地を購入して活用するという提案の中身についてですけれども、改めて、池田山なのですが、住民の方にどんな要望があるのか伺ってみたのですけれども、この池田山に住んでいる方々、自分たちが住んでいる地域の歴史や文化、あるいは守ってきた緑、こうした環境をすごく重んじる気風というか誇りがあるなと改めて感じました。","respondent":"柏原企画調整課長","answer":"検討会ですけれども、そういった中で、取得するかどうかも含めてまずは検討ですので、そういった形で、仮にもし取得という判断が出るのであれば、そういった中で、先々まちの方々にどうお話しするかというのはあるかもしれませんけれども。","id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"取得するか否かがまず検討だということなのですけれども、現段階で取得するかどうかの判断でも、地域の皆さんの声がすごく大事な要素であるかと考えています。ですから、品川区としては、どういう段階で地域の皆さんの声を伺うお考えがあるのか、今の時点であればお伺いしたいのが２つ目です。区としては、行政需要という点では何を足りないと考えているのか、それを３点目としてお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"例えば保育の問題であるとか、それから区全体のことでいきますと、やはり高齢者施設等々、そういったものは、ここに限らず、区全体の中でもいろいろなところで需要としてあると認識していますので、バランスを見ながらこういったところは計画していきたいと考えています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望としては、ぜひ、先ほど紹介したように、地域の中にはいろいろ高齢化への不安などありますので、積極的に、区の基金も８１５億円に達しておりますので、ぜひ、こうした基金も活用して、公有地を取得して区民のための活用をしていただきたいと要望します。","respondent":"柏原企画調整課長","answer":"金額につきましては、まだこれは国のほうが幾らという提示をしているわけではありませんし、我々のほうも鑑定評価しているわけではありませんので、はっきりしたものはないですけれども、路線価を見て想定する中では、少なくとも十七、八億円は下らないと思います。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今の意見が議会の意見だと思われると困るので指摘をしますけれども、議会としては、財政も十分配慮しながら、最も大切なことは、品川区の様々な行政目的があって、それと財政もしっかり鑑みながら、この場所を購入するかしないかも含めて総合的なバランスをとっていかないと、大きな税金を投入するわけですから、政策の費用対効果が非常に弱くなっていく。","respondent":"柏原企画調整課長","answer":"例えば、ここですと、１,４００m2でそれほど大きな建物は建てられない、それから周りの環境、土地と言いますか、住民の方々のご意見、いろいろ踏まえたとき、それからその金額に要する財政負担、それから行政需要にどういったものがあるか。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668787?Template=document&Id=5994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":39273,"voices":77}},{"id":"h27-20150929-18","meetingId":"h27-cm09","date":"2015年9月29日","dateIso":"2015-09-29","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問","question":"当初は、この野球場は、もとに戻さないと言われていましたけれども、今度のホッケー場についてはどうなるのか。オリンピック後の考え方として、どう見ていたらいいのか、そのあたりも教えていただければと思います。","respondent":"本多委員長、小川オリンピック・パラリンピック準備課長","answer":"ただいま、担当課長から、東京都の特別委員会からの情報提供ということですけれども、お答えできる範囲でお願いいたします。当初の予定では、委員ご指摘のとおり、野球場の６面全てにホッケー競技場をつくるという予定をしておりましたが、大会中には、今、申し上げましたとおり、第一球技場と第二球技場をメインとサブと使います。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"時間がないところ済みません。それはそれでわかったのですけれども、私が聞きたかったのは、このメインピッチとサブピッチのホッケーのここのところがどうなるのかということを知りたかった。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"サブにつきましては、第二球技場につきましては、そのまま観客席等も残していって、現状どおり復帰して、これまでと同じように第二球技場については使うということで聞いております。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462476?Template=document&Id=6480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":4127,"voices":16}}]);
